const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\n9901803\n00:00:00.000 --> 00:00:02.080 align:middle line:10%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:00:38.740 --> 00:00:44.420 align:middle line:0%,start position:50%,middle\n心灵捕手\n\n2\n00:03:33.380 --> 00:03:37.009 align:middle line:100%,end position:50%,middle\nf(x)的模平方，dx\n\n3\n00:03:38.819 --> 00:03:41.308 align:middle line:100%,end position:50%,middle\n下次课前请做完Percival\n\n4\n00:03:42.148 --> 00:03:45.637 align:middle line:100%,end position:50%,middle\n大学时虽已学过 但复习无妨\n\n5\n00:03:50.086 --> 00:03:51.286 align:middle line:100%,end position:50%,middle\n谢谢 史蒂芬\n\n6\n00:03:53.555 --> 00:03:57.894 align:middle line:100%,end position:50%,middle\n走廊黑板上有高级傅里叶算式\n\n7\n00:03:58.464 --> 00:04:01.293 align:middle line:100%,end position:50%,middle\n希望有人能在学期结束前证明它\n\n8\n00:04:01.433 --> 00:04:03.563 align:middle line:100%,end position:50%,middle\n解出这道题的人不但会获得我的青睐\n\n9\n00:04:03.663 --> 00:04:08.301 align:middle line:100%,end position:50%,middle\n还会因此名利双收\n成就将被记录 姓名也会刊登在\n\n10\n00:04:08.301 --> 00:04:13.300 align:middle line:100%,end position:50%,middle\n麻省理工《科技报》上\n\n11\n00:04:13.470 --> 00:04:17.139 align:middle line:100%,end position:50%,middle\n往届得奖者包括诺贝尔奖得主 菲尔兹奖得主\n\n12\n00:04:17.239 --> 00:04:18.909 align:middle line:100%,end position:50%,middle\n著名天体物理学家\n\n13\n00:04:19.009 --> 00:04:22.208 align:middle line:100%,end position:50%,middle\n还有不起眼的麻省理工教授\n\n14\n00:04:22.328 --> 00:04:25.487 align:middle line:100%,end position:50%,middle\n就这样 如果有问题\n\n15\n00:04:25.487 --> 00:04:28.107 align:middle line:100%,end position:50%,middle\n我相信汤姆会解答\n\n16\n00:05:04.408 --> 00:05:06.617 align:middle line:100%,end position:50%,middle\n嗨 威尔\n\n17\n00:05:06.617 --> 00:05:07.167 align:middle line:100%,end position:50%,middle\n柯斯滕 你好吗？\n\n18\n00:05:07.277 --> 00:05:07.907 align:middle line:100%,end position:50%,middle\n很好 你呢？\n\n19\n00:05:08.017 --> 00:05:10.116 align:middle line:100%,end position:50%,middle\n好\n\n20\n00:05:10.116 --> 00:05:11.746 align:middle line:100%,end position:50%,middle\n昨晚我没跟凯茜上床\n\n21\n00:05:11.856 --> 00:05:12.646 align:middle line:100%,end position:50%,middle\n- 没有？\n- 没有\n\n22\n00:05:12.856 --> 00:05:13.815 align:middle line:100%,end position:50%,middle\n为什么？\n\n23\n00:05:14.285 --> 00:05:16.285 align:middle line:100%,end position:50%,middle\n不知道 凯茜！\n\n24\n00:05:16.285 --> 00:05:17.085 align:middle line:100%,end position:50%,middle\n干嘛？\n\n25\n00:05:17.185 --> 00:05:19.744 align:middle line:100%,end position:50%,middle\n为什么不让我爽\n\n26\n00:05:19.744 --> 00:05:20.894 align:middle line:100%,end position:50%,middle\n- 就像平时那样？\n- 去你的\n\n27\n00:05:20.894 --> 00:05:24.583 align:middle line:100%,end position:50%,middle\n还有你的爱尔兰诅咒 查克\n\n28\n00:05:24.763 --> 00:05:28.592 align:middle line:100%,end position:50%,middle\n我才懒得为你那根小鸡巴费劲张腿\n\n29\n00:05:28.862 --> 00:05:30.521 align:middle line:100%,end position:50%,middle\n回家自己打手枪去吧\n\n30\n00:05:30.631 --> 00:05:32.131 align:middle line:100%,end position:50%,middle\n小老二！\n\n31\n00:05:32.131 --> 00:05:34.130 align:middle line:100%,end position:50%,middle\n小老二！\n\n32\n00:05:34.500 --> 00:05:36.160 align:middle line:100%,end position:50%,middle\n威尔 她少了一颗牙\n\n33\n00:05:36.940 --> 00:05:39.809 align:middle line:100%,end position:50%,middle\n她皮肤也不好 我…\n\n34\n00:05:39.809 --> 00:05:42.738 align:middle line:100%,end position:50%,middle\n再说 摩根最后娶她的赔率是5比2 你懂吧？\n\n35\n00:05:42.738 --> 00:05:48.277 align:middle line:100%,end position:50%,middle\n朋友的准老婆总不能一直睡 这可不对\n\n36\n00:05:48.277 --> 00:05:49.107 align:middle line:100%,end position:50%,middle\n你去哪？\n\n37\n00:05:49.547 --> 00:05:50.636 align:middle line:100%,end position:50%,middle\n我要走了\n\n38\n00:05:50.816 --> 00:05:53.546 align:middle line:100%,end position:50%,middle\n去你的，这就要走？\n才10点吧？\n\n39\n00:05:53.646 --> 00:05:54.615 align:middle line:100%,end position:50%,middle\n我累了\n\n40\n00:05:58.085 --> 00:06:00.194 align:middle line:100%,end position:50%,middle\n爱尔兰诅咒？\n\n41\n00:06:00.194 --> 00:06:03.035 align:middle line:100%,end position:50%,middle\n她才不懂 根本没有什么爱尔兰诅咒\n\n42\n00:07:10.718 --> 00:07:13.349 align:middle line:100%,end position:50%,middle\n出局 别再往我身上投球\n\n43\n00:07:13.399 --> 00:07:14.590 align:middle line:100%,end position:50%,middle\n不要再靠近本垒板\n\n44\n00:07:15.771 --> 00:07:17.031 align:middle line:100%,end position:50%,middle\n你选哪个？\n\n45\n00:07:20.243 --> 00:07:21.703 align:middle line:100%,end position:50%,middle\n你会被起诉 你知道吗？\n\n46\n00:07:21.813 --> 00:07:23.844 align:middle line:100%,end position:50%,middle\n你以为我怕你啊 你这混蛋？\n\n47\n00:07:23.844 --> 00:07:25.315 align:middle line:100%,end position:50%,middle\n是你他妈的太靠近本垒板\n\n48\n00:07:25.745 --> 00:07:29.517 align:middle line:100%,end position:50%,middle\n凯西下周要在哈佛的酒吧当保安\n\n49\n00:07:29.617 --> 00:07:30.448 align:middle line:100%,end position:50%,middle\n我们应该去\n\n50\n00:07:30.558 --> 00:07:31.918 align:middle line:100%,end position:50%,middle\n到那边干嘛？\n\n51\n00:07:32.188 --> 00:07:32.829 align:middle line:100%,end position:50%,middle\n不知道\n\n52\n00:07:32.829 --> 00:07:36.891 align:middle line:100%,end position:50%,middle\n去收拾几个聪明小子 咱们应该能混得开\n\n53\n00:07:39.232 --> 00:07:40.673 align:middle line:100%,end position:50%,middle\n哎哟 臭痞子\n\n54\n00:07:41.513 --> 00:07:45.245 align:middle line:100%,end position:50%,middle\n- 怎样？ 你很凶吗？\n- 来啊！\n\n55\n00:07:45.245 --> 00:07:47.736 align:middle line:100%,end position:50%,middle\n来啊 来啊 就这样\n\n56\n00:07:47.968 --> 00:07:50.804 align:middle line:100%,end position:50%,middle\n（欢迎参加1972班麻省理工校友会）\n\n57\n00:07:58.091 --> 00:07:59.081 align:middle line:100%,end position:50%,middle\n- 兰博教授？\n- 是的\n\n58\n00:07:59.902 --> 00:08:03.464 align:middle line:100%,end position:50%,middle\n我是你的应用理论课学生\n我们都在数学与科学大楼\n\n59\n00:08:03.574 --> 00:08:04.794 align:middle line:100%,end position:50%,middle\n过来\n\n60\n00:08:05.405 --> 00:08:06.705 align:middle line:100%,end position:50%,middle\n今天礼拜六\n\n61\n00:08:07.846 --> 00:08:09.537 align:middle line:100%,end position:50%,middle\n除非你今晚想和我喝一杯\n\n62\n00:08:10.177 --> 00:08:11.557 align:middle line:100%,end position:50%,middle\n或许吧\n\n63\n00:08:11.557 --> 00:08:13.598 align:middle line:100%,end position:50%,middle\n我们等不及星期一再弄清楚\n\n64\n00:08:14.019 --> 00:08:15.149 align:middle line:100%,end position:50%,middle\n弄清楚什么？\n\n65\n00:08:15.289 --> 00:08:16.760 align:middle line:100%,end position:50%,middle\n是谁证明了这个定理\n\n66\n00:08:22.123 --> 00:08:25.624 align:middle line:100%,end position:50%,middle\n（G表示图形）\n\n67\n00:08:38.471 --> 00:08:42.032 align:middle line:100%,end position:50%,middle\n完全正确\n\n68\n00:08:42.032 --> 00:08:43.313 align:middle line:100%,end position:50%,middle\n谁解的？ 杰克？\n\n69\n00:08:43.313 --> 00:08:45.654 align:middle line:100%,end position:50%,middle\n不是我\n\n70\n00:08:45.654 --> 00:08:47.165 align:middle line:100%,end position:50%,middle\n尼米许？\n\n71\n00:08:47.165 --> 00:08:48.795 align:middle line:100%,end position:50%,middle\n怎么可能\n\n72\n00:08:52.507 --> 00:08:53.438 align:middle line:100%,end position:50%,middle\n快，乔伊，就是现在！\n\n73\n00:08:53.548 --> 00:08:55.009 align:middle line:100%,end position:50%,middle\n比利·麦克纳马拉要上场了\n\n74\n00:08:55.109 --> 00:08:57.550 align:middle line:100%,end position:50%,middle\n快点 小子！\n\n75\n00:08:57.650 --> 00:08:58.810 align:middle line:100%,end position:50%,middle\n乔伊 把球救回来 快\n\n76\n00:08:58.920 --> 00:09:01.722 align:middle line:100%,end position:50%,middle\n麦克 把球压下来 就是这样\n\n77\n00:09:01.722 --> 00:09:03.923 align:middle line:100%,end position:50%,middle\n好样的 往二垒跑 麦克\n\n78\n00:09:06.514 --> 00:09:11.186 align:middle line:100%,end position:50%,middle\n摩根 穿条纹裤的姑娘是谁？ 她屁股真翘\n\n79\n00:09:11.567 --> 00:09:12.767 align:middle line:100%,end position:50%,middle\n那屁股真不赖\n\n80\n00:09:12.877 --> 00:09:13.928 align:middle line:100%,end position:50%,middle\n她跟谁一起？\n\n81\n00:09:14.038 --> 00:09:16.479 align:middle line:100%,end position:50%,middle\n那个他妈的意大利佬 我真讨厌那混蛋\n\n82\n00:09:16.579 --> 00:09:17.639 align:middle line:100%,end position:50%,middle\n威尔认识他\n\n83\n00:09:17.850 --> 00:09:18.680 align:middle line:100%,end position:50%,middle\n是啊 我认识\n\n84\n00:09:18.780 --> 00:09:19.981 align:middle line:100%,end position:50%,middle\n该死的卡迈恩·斯卡帕利亚\n\n85\n00:09:19.981 --> 00:09:22.152 align:middle line:100%,end position:50%,middle\n他幼儿园时把我揍得好惨\n\n86\n00:09:22.152 --> 00:09:23.082 align:middle line:100%,end position:50%,middle\n那个人？\n\n87\n00:09:23.192 --> 00:09:24.023 align:middle line:100%,end position:50%,middle\n嗯\n\n88\n00:09:25.523 --> 00:09:27.614 align:middle line:100%,end position:50%,middle\n操他妈的 去弄点东西吃吧\n\n89\n00:09:28.265 --> 00:09:30.196 align:middle line:100%,end position:50%,middle\n摩根 你不跟她讲话吗？\n\n90\n00:09:30.466 --> 00:09:31.456 align:middle line:100%,end position:50%,middle\n去她的\n\n91\n00:09:32.106 --> 00:09:32.937 align:middle line:100%,end position:50%,middle\n我倒想吃个皇堡\n\n92\n00:09:33.737 --> 00:09:34.728 align:middle line:100%,end position:50%,middle\n去凯利餐厅吧\n\n93\n00:09:34.908 --> 00:09:36.338 align:middle line:100%,end position:50%,middle\n摩根 我才不去凯利餐厅\n\n94\n00:09:36.439 --> 00:09:37.809 align:middle line:100%,end position:50%,middle\n你只是喜欢那儿的外卖女孩\n\n95\n00:09:37.909 --> 00:09:39.400 align:middle line:100%,end position:50%,middle\n而且要多绕15分钟路\n\n96\n00:09:39.580 --> 00:09:42.742 align:middle line:100%,end position:50%,middle\n我们他妈的还能干吗\n难道连15分钟都挪不出来？\n\n97\n00:09:45.183 --> 00:09:45.953 align:middle line:100%,end position:50%,middle\n双层汉堡\n\n98\n00:09:45.993 --> 00:09:46.864 align:middle line:100%,end position:50%,middle\n双层汉堡\n\n99\n00:09:49.025 --> 00:09:50.085 align:middle line:100%,end position:50%,middle\n双层汉堡\n\n100\n00:09:50.625 --> 00:09:53.767 align:middle line:100%,end position:50%,middle\n查克 我点的是双层汉堡\n\n101\n00:09:53.867 --> 00:09:56.568 align:middle line:100%,end position:50%,middle\n闭嘴 我知道你点了什么 我当时就在这儿\n\n102\n00:09:56.668 --> 00:09:57.939 align:middle line:100%,end position:50%,middle\n那就把我的三明治给我\n\n103\n00:09:58.039 --> 00:09:59.930 align:middle line:100%,end position:50%,middle\n什么叫你的三明治？ 是我买的\n\n104\n00:09:59.930 --> 00:10:01.971 align:middle line:100%,end position:50%,middle\n摩根 你身上有多少钱？\n\n105\n00:10:02.081 --> 00:10:04.642 align:middle line:100%,end position:50%,middle\n我说了，买刨冰时就能把钱找开\n\n106\n00:10:04.642 --> 00:10:08.154 align:middle line:100%,end position:50%,middle\n刚停车时我就说了\n把我的三明治给我，别混蛋了\n\n107\n00:10:08.254 --> 00:10:11.085 align:middle line:100%,end position:50%,middle\n好，把你身上的16美分给我\n\n108\n00:10:11.195 --> 00:10:13.056 align:middle line:100%,end position:50%,middle\n你那三明治他妈的得分期付款\n\n109\n00:10:13.266 --> 00:10:15.828 align:middle line:100%,end position:50%,middle\n好了 先放这儿给你留着\n\n110\n00:10:15.828 --> 00:10:16.798 align:middle line:100%,end position:50%,middle\n我们让你分期付款\n\n111\n00:10:16.798 --> 00:10:18.539 align:middle line:100%,end position:50%,middle\n你每天就带6美分过来\n\n112\n00:10:18.539 --> 00:10:20.170 align:middle line:100%,end position:50%,middle\n周末给你汉堡\n\n113\n00:10:20.170 --> 00:10:21.400 align:middle line:100%,end position:50%,middle\n你怎么这么混蛋？\n\n114\n00:10:21.510 --> 00:10:23.171 align:middle line:100%,end position:50%,middle\n我他妈又不是免费发三明治的\n\n115\n00:10:23.281 --> 00:10:25.842 align:middle line:100%,end position:50%,middle\n我看你该办个信用额度\n\n116\n00:10:25.952 --> 00:10:29.014 align:middle line:100%,end position:50%,middle\n就像你们买沙发时那样 分期付款\n\n117\n00:10:29.354 --> 00:10:32.185 align:middle line:100%,end position:50%,middle\n记得你妈那一年每天交10美元吗？\n\n118\n00:10:32.296 --> 00:10:34.056 align:middle line:100%,end position:50%,middle\n她终于按Rent-A-Center\n分期买到沙发\n\n119\n00:10:34.156 --> 00:10:35.257 align:middle line:100%,end position:50%,middle\n可以把食物给我了吗？\n\n120\n00:10:35.367 --> 00:10:37.058 align:middle line:100%,end position:50%,middle\n这是你的双层汉堡\n\n121\n00:10:39.359 --> 00:10:41.860 align:middle line:100%,end position:50%,middle\n等等 查克\n\n122\n00:10:41.860 --> 00:10:42.410 align:middle line:100%,end position:50%,middle\n慢下来\n\n123\n00:10:42.410 --> 00:10:43.201 align:middle line:100%,end position:50%,middle\n那边有谁？\n\n124\n00:10:44.353 --> 00:10:46.313 align:middle line:100%,end position:50%,middle\n- 还不知道\n- 喂，混蛋！\n\n125\n00:10:46.480 --> 00:10:48.899 align:middle line:100%,end position:50%,middle\n- 什么？\n- 就是你，臭婊子\n\n126\n00:10:48.982 --> 00:10:52.152 align:middle line:100%,end position:50%,middle\n- 闭嘴！\n- 走吧\n\n127\n00:10:52.236 --> 00:10:53.445 align:middle line:100%,end position:50%,middle\n走吧 威尔\n\n128\n00:10:53.612 --> 00:10:55.030 align:middle line:100%,end position:50%,middle\n给我吹吧！\n\n129\n00:10:55.027 --> 00:10:56.957 align:middle line:100%,end position:50%,middle\n我们15分钟前才见过那家伙\n\n130\n00:10:57.058 --> 00:10:59.899 align:middle line:100%,end position:50%,middle\n当时就该揍他 现在我们正吃零食呢\n\n131\n00:11:00.099 --> 00:11:01.400 align:middle line:100%,end position:50%,middle\n闭嘴 摩根 你也得去\n\n132\n00:11:01.400 --> 00:11:01.990 align:middle line:100%,end position:50%,middle\n我才不去\n\n133\n00:11:02.100 --> 00:11:02.660 align:middle line:100%,end position:50%,middle\n那就别去\n\n134\n00:11:02.770 --> 00:11:03.901 align:middle line:100%,end position:50%,middle\n我不去\n\n135\n00:11:04.441 --> 00:11:05.802 align:middle line:100%,end position:50%,middle\n你他妈的给我去 摩根\n\n136\n00:11:06.672 --> 00:11:09.003 align:middle line:100%,end position:50%,middle\n我跟你讲 两秒内不滚出去\n\n137\n00:11:09.113 --> 00:11:10.874 align:middle line:100%,end position:50%,middle\n等我扁完他们 就扁你\n\n138\n00:11:11.014 --> 00:11:13.315 align:middle line:100%,end position:50%,middle\n卡迈恩，是我，威尔，记得吗？\n\n139\n00:11:13.415 --> 00:11:14.746 align:middle line:100%,end position:50%,middle\n我们是幼儿园同学\n\n140\n00:11:29.373 --> 00:11:33.025 align:middle line:100%,end position:50%,middle\n- 操，快走，兄弟！\n- 踩烂他的脑袋！\n\n141\n00:11:33.025 --> 00:11:36.987 align:middle line:100%,end position:50%,middle\n把他按倒 制住那个混蛋\n\n142\n00:11:43.030 --> 00:11:44.090 align:middle line:100%,end position:50%,middle\n混蛋 去死吧！\n\n143\n00:11:45.539 --> 00:11:47.124 align:middle line:100%,end position:50%,middle\n使劲点！\n\n144\n00:11:59.438 --> 00:12:03.690 align:middle line:100%,end position:50%,middle\n威尔 威尔 快走\n\n145\n00:12:03.740 --> 00:12:07.552 align:middle line:100%,end position:50%,middle\n威尔 快点 快走\n\n146\n00:12:08.502 --> 00:12:09.763 align:middle line:100%,end position:50%,middle\n别激动 别激动\n\n147\n00:12:10.003 --> 00:12:12.244 align:middle line:100%,end position:50%,middle\n伙计们 谢谢你们赶来\n\n148\n00:12:12.244 --> 00:12:13.795 align:middle line:100%,end position:50%,middle\n过来！\n\n149\n00:12:21.388 --> 00:12:22.889 align:middle line:100%,end position:50%,middle\n啊 操\n\n150\n00:12:30.062 --> 00:12:33.664 align:middle line:100%,end position:50%,middle\n我没看错吧 班上怎么突然多了这么多人？\n\n151\n00:12:34.615 --> 00:12:36.195 align:middle line:100%,end position:50%,middle\n不过我绝不认为\n\n152\n00:12:36.195 --> 00:12:40.077 align:middle line:100%,end position:50%,middle\n你们真是来听我讲课\n\n153\n00:12:40.077 --> 00:12:43.519 align:middle line:100%,end position:50%,middle\n而是想知道那位神秘数学奇才是谁\n\n154\n00:12:45.250 --> 00:12:49.712 align:middle line:100%,end position:50%,middle\n沉默的天才 出来领奖吧\n\n155\n00:13:00.447 --> 00:13:03.379 align:middle line:100%,end position:50%,middle\n抱歉让观众失望了\n\n156\n00:13:03.379 --> 00:13:07.751 align:middle line:100%,end position:50%,middle\n看来今天不会揭晓了\n\n157\n00:13:08.291 --> 00:13:11.422 align:middle line:100%,end position:50%,middle\n不过我和同事们商量过后\n\n158\n00:13:11.563 --> 00:13:14.634 align:middle line:100%,end position:50%,middle\n眼下外面的黑板上有一道题\n\n159\n00:13:14.764 --> 00:13:16.825 align:middle line:100%,end position:50%,middle\n我们花了两年多才证明出来\n\n160\n00:13:17.705 --> 00:13:21.507 align:middle line:100%,end position:50%,middle\n那么我就直说了 挑战已经摆在眼前\n\n161\n00:13:21.637 --> 00:13:25.339 align:middle line:100%,end position:50%,middle\n但全体教授也已踊跃作答\n\n162\n00:13:25.739 --> 00:13:29.321 align:middle line:100%,end position:50%,middle\n（市法院 南波士顿区）\n\n163\n00:13:38.626 --> 00:13:40.507 align:middle line:100%,end position:50%,middle\n什么时候开庭提审？\n\n164\n00:13:40.637 --> 00:13:41.567 align:middle line:100%,end position:50%,middle\n下星期\n\n165\n00:14:07.420 --> 00:14:10.301 align:middle line:100%,end position:50%,middle\n对不起\n\n166\n00:14:10.301 --> 00:14:11.952 align:middle line:100%,end position:50%,middle\n你在做什么？\n\n167\n00:14:11.952 --> 00:14:12.912 align:middle line:100%,end position:50%,middle\n对不起\n\n168\n00:14:13.823 --> 00:14:16.054 align:middle line:100%,end position:50%,middle\n你不能在人家的方程式上涂鸦\n\n169\n00:14:16.154 --> 00:14:17.414 align:middle line:100%,end position:50%,middle\n你别走！\n\n170\n00:14:17.554 --> 00:14:18.685 align:middle line:100%,end position:50%,middle\n去你的！\n\n171\n00:14:19.095 --> 00:14:21.156 align:middle line:100%,end position:50%,middle\n别耍聪明 你叫什么名字？\n\n172\n00:14:44.998 --> 00:14:46.428 align:middle line:100%,end position:50%,middle\n我的天\n\n173\n00:14:53.382 --> 00:14:54.542 align:middle line:100%,end position:50%,middle\n好像是对的\n\n174\n00:15:10.600 --> 00:15:13.571 align:middle line:100%,end position:50%,middle\n蠢到什么程度才会连那份工作都被炒？\n\n175\n00:15:13.812 --> 00:15:16.403 align:middle line:100%,end position:50%,middle\n在屋子里扫地有那么难吗？\n\n176\n00:15:16.513 --> 00:15:18.844 align:middle line:100%,end position:50%,middle\n米奇 你连扫地都能被开除\n\n177\n00:15:19.044 --> 00:15:20.945 align:middle line:100%,end position:50%,middle\n那是因为管理层重组\n\n178\n00:15:21.055 --> 00:15:23.486 align:middle line:100%,end position:50%,middle\n没错 把他们手下那群蠢货也一并重组了\n\n179\n00:15:23.586 --> 00:15:26.298 align:middle line:100%,end position:50%,middle\n闭嘴，你被开除的次数\n比金枪鱼装罐的次数还多，婊子\n\n180\n00:15:26.298 --> 00:15:28.529 align:middle line:100%,end position:50%,middle\n至少我现在有份工作 对吧？\n\n181\n00:15:28.629 --> 00:15:29.259 align:middle line:100%,end position:50%,middle\n是啊\n\n182\n00:15:29.769 --> 00:15:31.290 align:middle line:100%,end position:50%,middle\n威尔 你为何被开除？\n\n183\n00:15:31.430 --> 00:15:32.701 align:middle line:100%,end position:50%,middle\n管理层重组\n\n184\n00:15:35.602 --> 00:15:37.403 align:middle line:100%,end position:50%,middle\n我舅舅或许能让你进拆除队\n\n185\n00:15:37.513 --> 00:15:38.273 align:middle line:100%,end position:50%,middle\n可以吗？\n\n186\n00:15:38.614 --> 00:15:41.015 align:middle line:100%,end position:50%,middle\n你耍我 我昨天还问过你\n\n187\n00:15:41.185 --> 00:15:42.946 align:middle line:100%,end position:50%,middle\n我昨天告诉你不行\n\n188\n00:15:42.976 --> 00:15:45.607 align:middle line:100%,end position:50%,middle\n嗨 凯西！嗨 凯斯！嗨 大凯斯！\n\n189\n00:15:48.158 --> 00:15:49.179 align:middle line:100%,end position:50%,middle\n坐这边\n\n190\n00:15:58.043 --> 00:16:01.175 align:middle line:100%,end position:50%,middle\n哦 这就是…这就是哈佛酒吧？\n\n191\n00:16:01.515 --> 00:16:04.036 align:middle line:100%,end position:50%,middle\n我以为墙上会有方程式呢\n\n192\n00:16:05.787 --> 00:16:08.918 align:middle line:100%,end position:50%,middle\n我要一壶店里最好的啤酒\n\n193\n00:16:16.702 --> 00:16:17.362 align:middle line:100%,end position:50%,middle\n暂停\n\n194\n00:16:17.873 --> 00:16:21.134 align:middle line:100%,end position:50%,middle\n我要去撩撩吧台那几个哈佛辣妹\n\n195\n00:16:21.374 --> 00:16:23.845 align:middle line:100%,end position:50%,middle\n- 看我的吧\n- 帮我们钓几个\n\n196\n00:16:39.813 --> 00:16:43.045 align:middle line:100%,end position:50%,middle\n- 你好\n- 你好\n\n197\n00:16:43.045 --> 00:16:44.205 align:middle line:100%,end position:50%,middle\n你好吗？\n\n198\n00:16:44.305 --> 00:16:45.076 align:middle line:100%,end position:50%,middle\n好\n\n199\n00:16:45.246 --> 00:16:46.807 align:middle line:100%,end position:50%,middle\n两位美女\n\n200\n00:16:46.917 --> 00:16:47.467 align:middle line:100%,end position:50%,middle\n常来吗？\n\n201\n00:16:47.577 --> 00:16:48.908 align:middle line:100%,end position:50%,middle\n我常来吗？我有时会来\n\n202\n00:16:49.018 --> 00:16:51.819 align:middle line:100%,end position:50%,middle\n你知道 我偶尔会来\n\n203\n00:16:52.349 --> 00:16:53.450 align:middle line:100%,end position:50%,middle\n你们在这里上学吗？\n\n204\n00:16:53.660 --> 00:16:54.490 align:middle line:100%,end position:50%,middle\n对\n\n205\n00:16:54.790 --> 00:16:58.322 align:middle line:100%,end position:50%,middle\n就是嘛 我想我跟你同班\n\n206\n00:16:58.432 --> 00:16:59.593 align:middle line:100%,end position:50%,middle\n是吗？ 哪一班？\n\n207\n00:17:00.633 --> 00:17:01.604 align:middle line:100%,end position:50%,middle\n历史\n\n208\n00:17:01.704 --> 00:17:02.324 align:middle line:100%,end position:50%,middle\n或许\n\n209\n00:17:02.434 --> 00:17:04.475 align:middle line:100%,end position:50%,middle\n应该没错\n\n210\n00:17:04.475 --> 00:17:08.147 align:middle line:100%,end position:50%,middle\n你可能不记得我 我挺喜欢这里的\n\n211\n00:17:08.147 --> 00:17:11.779 align:middle line:100%,end position:50%,middle\n我在这儿念书不代表我是天才 但我确实很聪明\n\n212\n00:17:12.319 --> 00:17:13.289 align:middle line:100%,end position:50%,middle\n嗨 过得怎么样？你好吗？\n\n213\n00:17:13.289 --> 00:17:13.940 align:middle line:100%,end position:50%,middle\n好 你呢？\n\n214\n00:17:14.120 --> 00:17:16.821 align:middle line:100%,end position:50%,middle\n你说你在哪一班？\n\n215\n00:17:16.821 --> 00:17:18.762 align:middle line:100%,end position:50%,middle\n历史\n\n216\n00:17:18.762 --> 00:17:22.564 align:middle line:100%,end position:50%,middle\n历史？ 那一定是概论课程\n\n217\n00:17:22.664 --> 00:17:23.864 align:middle line:100%,end position:50%,middle\n- 对 是概论课程\n- 没错\n\n218\n00:17:23.965 --> 00:17:26.836 align:middle line:100%,end position:50%,middle\n你应该去上上看 这课不错 真的不错\n\n219\n00:17:27.006 --> 00:17:28.367 align:middle line:100%,end position:50%,middle\n你觉得那堂课怎么样？\n\n220\n00:17:28.467 --> 00:17:33.379 align:middle line:100%,end position:50%,middle\n老实说 我觉得很基础\n\n221\n00:17:33.379 --> 00:17:34.350 align:middle line:100%,end position:50%,middle\n基础\n\n222\n00:17:34.350 --> 00:17:35.950 align:middle line:100%,end position:50%,middle\n肯定是的\n\n223\n00:17:35.950 --> 00:17:38.982 align:middle line:100%,end position:50%,middle\n我记得那堂课了\n\n224\n00:17:39.122 --> 00:17:42.964 align:middle line:100%,end position:50%,middle\n就在课间和午餐之间\n\n225\n00:17:43.264 --> 00:17:45.395 align:middle line:100%,end position:50%,middle\n克拉克 你走开啦\n\n226\n00:17:45.735 --> 00:17:46.706 align:middle line:100%,end position:50%,middle\n放轻松点\n\n227\n00:17:46.806 --> 00:17:47.736 align:middle line:100%,end position:50%,middle\n走开啦\n\n228\n00:17:47.836 --> 00:17:49.427 align:middle line:100%,end position:50%,middle\n我跟我的新朋友很开心\n\n229\n00:17:49.537 --> 00:17:50.878 align:middle line:100%,end position:50%,middle\n有什么问题吗？\n\n230\n00:17:50.878 --> 00:17:52.808 align:middle line:100%,end position:50%,middle\n没问题\n\n231\n00:17:52.808 --> 00:17:56.850 align:middle line:100%,end position:50%,middle\n我只是想请教你市场经济的演变\n\n232\n00:17:56.850 --> 00:17:59.652 align:middle line:100%,end position:50%,middle\n在南方殖民地的发展情况\n\n233\n00:17:59.952 --> 00:18:03.514 align:middle line:100%,end position:50%,middle\n我主张在革命战争前\n\n234\n00:18:04.064 --> 00:18:08.596 align:middle line:100%,end position:50%,middle\n尤其是南方殖民地的经济形态\n\n235\n00:18:08.596 --> 00:18:11.407 align:middle line:100%,end position:50%,middle\n最恰当的描述是\n\n236\n00:18:11.407 --> 00:18:12.638 align:middle line:100%,end position:50%,middle\n- 农耕式前资本主义\n- 让我来说两句\n\n237\n00:18:12.638 --> 00:18:15.790 align:middle line:100%,end position:50%,middle\n那当然是你的论点 你才研一\n\n238\n00:18:15.880 --> 00:18:18.011 align:middle line:100%,end position:50%,middle\n你刚读完马克思主义史学家的书\n可能是皮特·加里森\n\n239\n00:18:18.211 --> 00:18:22.293 align:middle line:100%,end position:50%,middle\n下个月你读到詹姆斯·莱蒙 又会深信他的观点\n\n240\n00:18:22.293 --> 00:18:25.424 align:middle line:100%,end position:50%,middle\n然后你会谈弗吉尼亚州和宾夕法尼亚州的经济\n\n241\n00:18:25.424 --> 00:18:28.636 align:middle line:100%,end position:50%,middle\n早在1740年\n就已具备企业化和资本主义特征\n\n242\n00:18:28.636 --> 00:18:31.937 align:middle line:100%,end position:50%,middle\n这会一直拖到明年\n你又会在这儿背书似的复述戈登·伍德\n\n243\n00:18:31.937 --> 00:18:34.799 align:middle line:100%,end position:50%,middle\n大谈革命前乌托邦\n\n244\n00:18:35.039 --> 00:18:37.740 align:middle line:100%,end position:50%,middle\n和军事动员对资本形成的影响\n\n245\n00:18:38.360 --> 00:18:40.652 align:middle line:100%,end position:50%,middle\n事实上，我不会\n\n246\n00:18:40.782 --> 00:18:44.043 align:middle line:100%,end position:50%,middle\n因为伍德严重低估了…\n\n247\n00:18:44.153 --> 00:18:47.085 align:middle line:100%,end position:50%,middle\n伍德严重低估了社会阶级差异\n造成的影响\n\n248\n00:18:47.425 --> 00:18:49.586 align:middle line:100%,end position:50%,middle\n这些差异源于财富，尤其是遗产\n\n249\n00:18:50.496 --> 00:18:51.927 align:middle line:100%,end position:50%,middle\n这是你从维克斯读到的论点\n\n250\n00:18:52.197 --> 00:18:54.288 align:middle line:100%,end position:50%,middle\n《埃塞克斯县的劳工》98页 对吧？\n\n251\n00:18:54.798 --> 00:18:55.829 align:middle line:100%,end position:50%,middle\n我也读过\n\n252\n00:18:55.969 --> 00:18:57.669 align:middle line:100%,end position:50%,middle\n你要剽窃整本书吗？\n\n253\n00:18:57.769 --> 00:19:00.498 align:middle line:100%,end position:50%,middle\n对这些论点你有个人想法吗？\n\n254\n00:19:01.478 --> 00:19:04.338 align:middle line:100%,end position:50%,middle\n还是你就这点本事？跑到酒吧念一段冷僻文字\n\n255\n00:19:04.448 --> 00:19:07.648 align:middle line:100%,end position:50%,middle\n还假装是自己的观点\n\n256\n00:19:07.648 --> 00:19:11.237 align:middle line:100%,end position:50%,middle\n就为了泡妞、让我朋友难堪吗？\n\n257\n00:19:11.357 --> 00:19:14.717 align:middle line:100%,end position:50%,middle\n你这种人最可悲的是 五十年后\n\n258\n00:19:14.717 --> 00:19:16.187 align:middle line:100%,end position:50%,middle\n你才会开始独立思考\n\n259\n00:19:16.287 --> 00:19:19.226 align:middle line:100%,end position:50%,middle\n生命中有两件事是确定的\n\n260\n00:19:19.226 --> 00:19:21.456 align:middle line:100%,end position:50%,middle\n一是别做这样的事\n\n261\n00:19:21.456 --> 00:19:24.296 align:middle line:100%,end position:50%,middle\n二 你砸了15万美元读书\n\n262\n00:19:24.396 --> 00:19:27.835 align:middle line:100%,end position:50%,middle\n在公共图书馆交1.5美元逾期费就能学到\n\n263\n00:19:29.735 --> 00:19:31.565 align:middle line:100%,end position:50%,middle\n对 但我会有文凭\n\n264\n00:19:32.305 --> 00:19:34.134 align:middle line:100%,end position:50%,middle\n而你只能在免下车餐厅给我孩子卖薯条\n\n265\n00:19:34.274 --> 00:19:36.604 align:middle line:100%,end position:50%,middle\n那时我们正开车去滑雪\n\n266\n00:19:37.804 --> 00:19:41.054 align:middle line:100%,end position:50%,middle\n也许吧 至少我不会人云亦云\n\n267\n00:19:41.054 --> 00:19:45.723 align:middle line:100%,end position:50%,middle\n不爽可以到外面解决\n\n268\n00:19:45.723 --> 00:19:50.103 align:middle line:100%,end position:50%,middle\n不 没事 很酷\n\n269\n00:19:50.103 --> 00:19:51.982 align:middle line:100%,end position:50%,middle\n酷？\n\n270\n00:19:52.062 --> 00:19:53.922 align:middle line:100%,end position:50%,middle\n当然没问题\n\n271\n00:19:54.422 --> 00:19:55.942 align:middle line:100%,end position:50%,middle\n现在喜欢我了吧\n\n272\n00:20:00.091 --> 00:20:01.251 align:middle line:100%,end position:50%,middle\n那小子聪明绝顶\n\n273\n00:20:03.201 --> 00:20:06.431 align:middle line:100%,end position:50%,middle\n才来这儿3分钟\n就碰上个该死的阔少\n\n274\n00:20:08.870 --> 00:20:10.750 align:middle line:100%,end position:50%,middle\n有了\n\n275\n00:20:10.750 --> 00:20:11.540 align:middle line:100%,end position:50%,middle\n- 幸会\n- 她们不错，伙计\n\n276\n00:20:11.540 --> 00:20:16.039 align:middle line:100%,end position:50%,middle\n我本来快搞定她们了 结果查克…\n比利惹恼了其中一个\n\n277\n00:20:16.039 --> 00:20:21.209 align:middle line:100%,end position:50%,middle\n那个丰满的姑娘说我发际线后退\n还说我胖了几磅\n\n278\n00:20:21.309 --> 00:20:22.639 align:middle line:100%,end position:50%,middle\n我就说“去你妈的”\n\n279\n00:20:24.348 --> 00:20:25.708 align:middle line:100%,end position:50%,middle\n我吞了只虫\n\n280\n00:20:29.388 --> 00:20:30.788 align:middle line:100%,end position:50%,middle\n你是个白痴\n\n281\n00:20:31.588 --> 00:20:32.248 align:middle line:100%,end position:50%,middle\n什么？\n\n282\n00:20:32.388 --> 00:20:33.447 align:middle line:100%,end position:50%,middle\n你是个白痴\n\n283\n00:20:33.627 --> 00:20:34.637 align:middle line:100%,end position:50%,middle\n我坐在那边整整45分钟\n\n284\n00:20:34.637 --> 00:20:35.657 align:middle line:100%,end position:50%,middle\n等你过来搭讪\n\n285\n00:20:35.657 --> 00:20:39.197 align:middle line:100%,end position:50%,middle\n但我累了 我得回家了\n\n286\n00:20:39.197 --> 00:20:41.886 align:middle line:100%,end position:50%,middle\n我不能再坐着等你\n\n287\n00:20:42.126 --> 00:20:43.026 align:middle line:100%,end position:50%,middle\n我是威尔\n\n288\n00:20:43.136 --> 00:20:43.966 align:middle line:100%,end position:50%,middle\n斯凯勒\n\n289\n00:20:43.986 --> 00:20:45.986 align:middle line:100%,end position:50%,middle\n- 斯凯勒\n- 对了\n\n290\n00:20:45.986 --> 00:20:49.275 align:middle line:100%,end position:50%,middle\n那个人…迈克尔·波顿的翻版…\n\n291\n00:20:49.465 --> 00:20:51.265 align:middle line:100%,end position:50%,middle\n准确说 他不算我们这伙的\n\n292\n00:20:51.435 --> 00:20:53.235 align:middle line:100%,end position:50%,middle\n- 我知道 我看得出来\n- 那就好\n\n293\n00:20:54.075 --> 00:20:56.675 align:middle line:100%,end position:50%,middle\n我得走了\n\n294\n00:20:56.675 --> 00:21:00.704 align:middle line:100%,end position:50%,middle\n我得早起继续浪费钱读这贵得离谱的学位\n\n295\n00:21:00.814 --> 00:21:02.374 align:middle line:100%,end position:50%,middle\n我不是指你\n\n296\n00:21:02.584 --> 00:21:03.414 align:middle line:100%,end position:50%,middle\n没关系\n\n297\n00:21:03.414 --> 00:21:06.923 align:middle line:100%,end position:50%,middle\n这是我的电话 也许有空可以喝杯咖啡\n\n298\n00:21:06.923 --> 00:21:09.983 align:middle line:100%,end position:50%,middle\n好啊 或许可以一起吃一大堆焦糖糖果\n\n299\n00:21:10.993 --> 00:21:11.713 align:middle line:100%,end position:50%,middle\n什么意思？\n\n300\n00:21:11.823 --> 00:21:14.892 align:middle line:100%,end position:50%,middle\n想想看 这跟喝咖啡一样随意\n\n301\n00:21:14.892 --> 00:21:17.762 align:middle line:100%,end position:50%,middle\n是吗\n\n302\n00:21:17.762 --> 00:21:20.762 align:middle line:100%,end position:50%,middle\n好的\n\n303\n00:21:26.941 --> 00:21:27.741 align:middle line:100%,end position:50%,middle\n兄弟们！\n\n304\n00:21:28.901 --> 00:21:30.001 align:middle line:100%,end position:50%,middle\n- 去你的！\n- 我才去你的\n\n305\n00:21:30.741 --> 00:21:33.230 align:middle line:100%,end position:50%,middle\n那群该死的阔少要去滑雪啦\n\n306\n00:21:33.380 --> 00:21:34.740 align:middle line:100%,end position:50%,middle\n等等\n\n307\n00:21:34.910 --> 00:21:36.570 align:middle line:100%,end position:50%,middle\n我们该把那个老婊子揍一顿\n\n308\n00:21:44.219 --> 00:21:45.909 align:middle line:100%,end position:50%,middle\n你喜欢苹果吗？\n\n309\n00:21:47.489 --> 00:21:48.318 align:middle line:100%,end position:50%,middle\n- 是的\n- 喜欢？\n\n310\n00:21:48.558 --> 00:21:53.198 align:middle line:100%,end position:50%,middle\n我拿到她的电话号码了！\n\n311\n00:21:53.198 --> 00:21:54.798 align:middle line:100%,end position:50%,middle\n这苹果怎么样？\n\n312\n00:22:47.171 --> 00:22:49.131 align:middle line:100%,end position:50%,middle\n来\n\n313\n00:22:53.011 --> 00:22:55.710 align:middle line:100%,end position:50%,middle\n打扰了 这是大楼管理室吗？\n\n314\n00:22:56.780 --> 00:22:58.650 align:middle line:100%,end position:50%,middle\n有何贵干？\n\n315\n00:22:58.850 --> 00:23:01.010 align:middle line:100%,end position:50%,middle\n我要找个在这里打工的学生\n\n316\n00:23:01.120 --> 00:23:02.590 align:middle line:100%,end position:50%,middle\n没学生替我做事\n\n317\n00:23:02.690 --> 00:23:03.849 align:middle line:100%,end position:50%,middle\n请你查一下\n\n318\n00:23:03.989 --> 00:23:06.219 align:middle line:100%,end position:50%,middle\n有个人在我那栋楼做事 大概长这么高\n\n319\n00:23:06.329 --> 00:23:07.949 align:middle line:100%,end position:50%,middle\n你在几号楼？\n\n320\n00:23:08.529 --> 00:23:10.549 align:middle line:100%,end position:50%,middle\n- 二\n- 二号楼\n\n321\n00:23:16.998 --> 00:23:18.658 align:middle line:100%,end position:50%,middle\n如果有东西失窃我该知道\n\n322\n00:23:18.768 --> 00:23:19.748 align:middle line:100%,end position:50%,middle\n不是那样\n\n323\n00:23:19.748 --> 00:23:21.707 align:middle line:100%,end position:50%,middle\n我只是要找他\n\n324\n00:23:21.707 --> 00:23:24.197 align:middle line:100%,end position:50%,middle\n除非你投诉 否则不告诉你\n\n325\n00:23:24.807 --> 00:23:26.137 align:middle line:100%,end position:50%,middle\n这位是兰博教授\n\n326\n00:23:26.347 --> 00:23:27.867 align:middle line:100%,end position:50%,middle\n这位是海斯教授\n\n327\n00:23:28.077 --> 00:23:29.206 align:middle line:100%,end position:50%,middle\n汤姆 拜托\n\n328\n00:23:32.576 --> 00:23:35.376 align:middle line:100%,end position:50%,middle\n这很重要 拜托\n\n329\n00:23:36.116 --> 00:23:37.875 align:middle line:100%,end position:50%,middle\n威尔今天没上班\n\n330\n00:23:38.635 --> 00:23:42.525 align:middle line:100%,end position:50%,middle\n他透过PO找到这份工作 你可以打给他\n\n331\n00:23:42.755 --> 00:23:43.555 align:middle line:100%,end position:50%,middle\nPO？\n\n332\n00:23:43.549 --> 00:23:46.260 align:middle line:0%,start position:50%,middle\n监管就业计划\n\n333\n00:23:43.925 --> 00:23:46.084 align:middle line:100%,end position:50%,middle\n假释官\n\n334\n00:23:50.134 --> 00:23:51.064 align:middle line:100%,end position:50%,middle\n谢谢\n\n335\n00:23:53.833 --> 00:23:54.923 align:middle line:100%,end position:50%,middle\n混蛋\n\n336\n00:23:57.603 --> 00:24:03.372 align:middle line:100%,end position:50%,middle\n法官先生\n这项历史悠久的司法先例可追溯到1789年\n\n337\n00:24:03.472 --> 00:24:06.072 align:middle line:100%,end position:50%,middle\n被告对抗政府人员时可以主张自卫\n\n338\n00:24:06.172 --> 00:24:09.842 align:middle line:100%,end position:50%,middle\n如果此举是为了反抗暴政、捍卫自由\n\n339\n00:24:09.942 --> 00:24:14.421 align:middle line:100%,end position:50%,middle\n法官大人，亨利·沃德·比彻1887年\n在《普利茅斯讲坛箴言》里说…\n\n340\n00:24:14.421 --> 00:24:17.291 align:middle line:100%,end position:50%,middle\n-1887？ 现在20世纪了 -抱歉\n\n341\n00:24:17.291 --> 00:24:18.451 align:middle line:100%,end position:50%,middle\n他在嘲弄法庭\n\n342\n00:24:18.551 --> 00:24:21.920 align:middle line:100%,end position:50%,middle\n我有权为自己辩护，先生\n\n343\n00:24:22.020 --> 00:24:24.720 align:middle line:100%,end position:50%,middle\n美国宪法保障我的自由\n\n344\n00:24:24.720 --> 00:24:25.460 align:middle line:100%,end position:50%,middle\n不用你教我宪法条例\n\n345\n00:24:25.460 --> 00:24:29.259 align:middle line:100%,end position:50%,middle\n自由——也许你忘了——是灵魂呼吸的权利\n\n346\n00:24:29.359 --> 00:24:31.699 align:middle line:100%,end position:50%,middle\n不让人自由呼吸的法律 就是束缚得太紧\n\n347\n00:24:31.799 --> 00:24:33.269 align:middle line:100%,end position:50%,middle\n没有自由 人就会昏厥\n\n348\n00:24:33.369 --> 00:24:34.149 align:middle line:100%,end position:50%,middle\n什么？\n\n349\n00:24:34.149 --> 00:24:35.938 align:middle line:100%,end position:50%,middle\n出处同前 法官先生\n\n350\n00:24:35.938 --> 00:24:39.408 align:middle line:100%,end position:50%,middle\n轮到我 我在这坐了十分钟\n\n351\n00:24:39.408 --> 00:24:43.808 align:middle line:100%,end position:50%,middle\n看着你的罪状 我不敢相信\n\n352\n00:24:43.808 --> 00:24:48.327 align:middle line:100%,end position:50%,middle\n93年6月袭击罪 93年9月袭击罪\n\n353\n00:24:48.377 --> 00:24:52.037 align:middle line:100%,end position:50%,middle\n偷车 94年2月\n\n354\n00:24:52.037 --> 00:24:56.316 align:middle line:100%,end position:50%,middle\n你显然通过援引判例自行辩护\n让案子撤销了\n\n355\n00:24:56.486 --> 00:25:00.626 align:middle line:100%,end position:50%,middle\n“马匹与马车的自由财产权” 1798年判例\n\n356\n00:25:00.626 --> 00:25:04.215 align:middle line:100%,end position:50%,middle\n真可笑 95年1月 扮成警察\n\n357\n00:25:04.465 --> 00:25:08.225 align:middle line:100%,end position:50%,middle\n伤害 盗窃 拒捕 全驳回\n\n358\n00:25:08.665 --> 00:25:11.654 align:middle line:100%,end position:50%,middle\n我知道你住过几个寄养家庭\n\n359\n00:25:11.934 --> 00:25:15.334 align:middle line:100%,end position:50%,middle\n因遭受严重虐待\n州政府把你从其中3家带走\n\n360\n00:25:15.834 --> 00:25:17.743 align:middle line:100%,end position:50%,middle\n别的法官或许会在意\n\n361\n00:25:17.743 --> 00:25:20.403 align:middle line:100%,end position:50%,middle\n但你打警察 就得坐牢\n\n362\n00:25:20.613 --> 00:25:24.353 align:middle line:100%,end position:50%,middle\n驳回撤诉动议，保释金5万美元\n\n363\n00:25:24.353 --> 00:25:26.062 align:middle line:100%,end position:50%,middle\n谢谢\n\n364\n00:25:26.062 --> 00:25:27.692 align:middle line:100%,end position:50%,middle\n起立\n\n365\n00:25:30.082 --> 00:25:30.712 align:middle line:100%,end position:50%,middle\n喂？\n\n366\n00:25:31.022 --> 00:25:32.542 align:middle line:100%,end position:50%,middle\n<i>斯凯勒？</i>\n\n367\n00:25:32.882 --> 00:25:34.441 align:middle line:100%,end position:50%,middle\n<i>我是威尔</i>\n\n368\n00:25:34.651 --> 00:25:35.381 align:middle line:100%,end position:50%,middle\n- 谁？\n<i>- 威尔</i>\n\n369\n00:25:35.491 --> 00:25:39.261 align:middle line:100%,end position:50%,middle\n前两天在酒吧认识的风趣帅哥\n\n370\n00:25:39.261 --> 00:25:42.950 align:middle line:100%,end position:50%,middle\n我不记得遇到过符合你描述的人 我想我会记得\n\n371\n00:25:43.060 --> 00:25:46.590 align:middle line:100%,end position:50%,middle\n好吧，是那个丑陋、讨厌又没牙\n\n372\n00:25:46.730 --> 00:25:48.790 align:middle line:100%,end position:50%,middle\n还喝得烂醉，整夜缠着你的废物\n\n373\n00:25:48.930 --> 00:25:51.959 align:middle line:100%,end position:50%,middle\n威尔！ 我记起来了\n\n374\n00:25:52.939 --> 00:25:55.599 align:middle line:100%,end position:50%,middle\n你好 我还在想你会不会打来\n\n375\n00:25:55.769 --> 00:25:57.039 align:middle line:100%,end position:50%,middle\n我一直在想\n\n376\n00:25:57.039 --> 00:25:58.029 align:middle line:100%,end position:50%,middle\n怎么样？ 宝贝\n\n377\n00:25:58.139 --> 00:25:58.699 align:middle line:100%,end position:50%,middle\n稍等\n\n378\n00:25:58.809 --> 00:26:02.298 align:middle line:100%,end position:50%,middle\n怎样？ 宝贝 想上我吗？\n\n379\n00:26:02.408 --> 00:26:04.608 align:middle line:100%,end position:50%,middle\n赫芙 我记得你 在少年监狱见过 你好吗？\n\n380\n00:26:04.718 --> 00:26:06.268 align:middle line:100%,end position:50%,middle\n干嘛？\n\n381\n00:26:06.268 --> 00:26:08.387 align:middle line:100%,end position:50%,middle\n<i>对不起</i>\n\n382\n00:26:08.387 --> 00:26:11.287 align:middle line:100%,end position:50%,middle\n我在想也许这礼拜可以聚一聚\n\n383\n00:26:11.417 --> 00:26:13.787 align:middle line:100%,end position:50%,middle\n<i>坐在咖啡馆里 吃点焦糖糖果</i>\n\n384\n00:26:13.887 --> 00:26:15.147 align:middle line:100%,end position:50%,middle\n听起来很棒\n\n385\n00:26:15.257 --> 00:26:16.117 align:middle line:100%,end position:50%,middle\n<i>可以吗？</i>\n\n386\n00:26:16.286 --> 00:26:18.056 align:middle line:100%,end position:50%,middle\n可以 你在哪里？\n\n387\n00:26:18.396 --> 00:26:21.126 align:middle line:100%,end position:50%,middle\n其实我这是冒昧猜一下\n\n388\n00:26:21.266 --> 00:26:25.525 align:middle line:100%,end position:50%,middle\n你不会是法律预科生吧？\n\n389\n00:26:29.665 --> 00:26:30.605 align:middle line:100%,end position:50%,middle\n坐\n\n390\n00:26:31.035 --> 00:26:32.835 align:middle line:100%,end position:50%,middle\n谢谢\n\n391\n00:26:32.835 --> 00:26:34.794 align:middle line:100%,end position:50%,middle\n很高兴跟你讲话\n\n392\n00:26:37.214 --> 00:26:38.334 align:middle line:100%,end position:50%,middle\n你他妈的想干嘛？\n\n393\n00:26:39.444 --> 00:26:40.844 align:middle line:100%,end position:50%,middle\n我是杰拉尔德·兰博\n\n394\n00:26:42.313 --> 00:26:44.473 align:middle line:100%,end position:50%,middle\n被你叫滚蛋的那个教授\n\n395\n00:26:46.383 --> 00:26:47.913 align:middle line:100%,end position:50%,middle\n找我干嘛？\n\n396\n00:26:49.583 --> 00:26:50.982 align:middle line:100%,end position:50%,middle\n我跟法官谈过\n\n397\n00:26:51.192 --> 00:26:53.852 align:middle line:100%,end position:50%,middle\n他同意让你在我的监管下获释\n\n398\n00:26:53.852 --> 00:26:55.392 align:middle line:100%,end position:50%,middle\n真的？\n\n399\n00:26:55.392 --> 00:26:56.192 align:middle line:100%,end position:50%,middle\n是的\n\n400\n00:27:01.461 --> 00:27:02.831 align:middle line:100%,end position:50%,middle\n但有两个条件\n\n401\n00:27:02.931 --> 00:27:03.761 align:middle line:100%,end position:50%,middle\n哪两个？\n\n402\n00:27:04.071 --> 00:27:06.191 align:middle line:100%,end position:50%,middle\n第一 你每周要跟我碰面\n\n403\n00:27:06.740 --> 00:27:07.500 align:middle line:100%,end position:50%,middle\n做什么？\n\n404\n00:27:08.200 --> 00:27:10.170 align:middle line:100%,end position:50%,middle\n检查你正在做的证明\n\n405\n00:27:10.340 --> 00:27:18.159 align:middle line:100%,end position:50%,middle\n看你做些更高级的…组合数学\n\n406\n00:27:18.749 --> 00:27:20.149 align:middle line:100%,end position:50%,middle\n有限数学\n\n407\n00:27:22.249 --> 00:27:23.578 align:middle line:100%,end position:50%,middle\n好像很有趣\n\n408\n00:27:25.648 --> 00:27:31.388 align:middle line:100%,end position:50%,middle\n第二 你要看心理医生\n\n409\n00:27:35.157 --> 00:27:37.597 align:middle line:100%,end position:50%,middle\n由我每周负责作评估报告\n\n410\n00:27:38.967 --> 00:27:41.956 align:middle line:100%,end position:50%,middle\n只要你有任何一项条件没做到\n\n411\n00:27:42.096 --> 00:27:43.896 align:middle line:100%,end position:50%,middle\n照样送你回来坐牢\n\n412\n00:27:44.036 --> 00:27:47.406 align:middle line:100%,end position:50%,middle\n好 数学我接受\n但我才不去见什么该死的心理医生\n\n413\n00:27:48.236 --> 00:27:52.195 align:middle line:100%,end position:50%,middle\n这总比蹲牢房好 不是吗？\n\n414\n00:28:55.797 --> 00:28:56.787 align:middle line:100%,end position:50%,middle\n我看过你的书\n\n415\n00:28:56.967 --> 00:28:59.937 align:middle line:100%,end position:50%,middle\n你提到有个病人麦克的问题\n\n416\n00:29:00.107 --> 00:29:02.367 align:middle line:100%,end position:50%,middle\n就像证券经纪人查德遇到的那些问题\n\n417\n00:29:02.467 --> 00:29:05.466 align:middle line:100%,end position:50%,middle\n完全正确 一针见血 说得好 威尔\n\n418\n00:29:05.466 --> 00:29:06.076 align:middle line:100%,end position:50%,middle\n非常好\n\n419\n00:29:06.076 --> 00:29:07.006 align:middle line:100%,end position:50%,middle\n谢谢\n\n420\n00:29:07.206 --> 00:29:10.406 align:middle line:100%,end position:50%,middle\n威尔，这些压力…我不是在评判它们\n\n421\n00:29:10.516 --> 00:29:12.745 align:middle line:100%,end position:50%,middle\n我也不是要给它们贴标签\n\n422\n00:29:12.875 --> 00:29:16.395 align:middle line:100%,end position:50%,middle\n但这些压力正在扼杀你的潜力\n\n423\n00:29:16.395 --> 00:29:21.754 align:middle line:100%,end position:50%,middle\n别再胡闹、耍蠢、哗众取宠\n\n424\n00:29:21.884 --> 00:29:22.754 align:middle line:100%,end position:50%,middle\n你说得对\n\n425\n00:29:25.054 --> 00:29:26.114 align:middle line:100%,end position:50%,middle\n天哪 我知道\n\n426\n00:29:26.404 --> 00:29:30.283 align:middle line:100%,end position:50%,middle\n要摆脱不容易 来 多讲点\n\n427\n00:29:30.363 --> 00:29:32.723 align:middle line:100%,end position:50%,middle\n我有做过一些事\n\n428\n00:29:32.833 --> 00:29:34.593 align:middle line:100%,end position:50%,middle\n哪种事？\n\n429\n00:29:34.803 --> 00:29:38.102 align:middle line:100%,end position:50%,middle\n我做些…你懂的，瞒着别人的事\n\n430\n00:29:38.102 --> 00:29:39.692 align:middle line:100%,end position:50%,middle\n你躲避？\n\n431\n00:29:39.802 --> 00:29:43.202 align:middle line:100%,end position:50%,middle\n不 我是说 我也会去些地方 跟人来往\n\n432\n00:29:43.342 --> 00:29:44.532 align:middle line:100%,end position:50%,middle\n真的？哪种地方？\n\n433\n00:29:44.642 --> 00:29:45.612 align:middle line:100%,end position:50%,middle\n一些酒吧\n\n434\n00:29:45.712 --> 00:29:47.571 align:middle line:100%,end position:50%,middle\n继续 很好 说说是哪种夜店？\n\n435\n00:29:47.681 --> 00:29:49.011 align:middle line:100%,end position:50%,middle\n像是“幻想”\n\n436\n00:29:49.111 --> 00:29:51.451 align:middle line:100%,end position:50%,middle\n“幻想”\n\n437\n00:29:51.451 --> 00:29:52.711 align:middle line:100%,end position:50%,middle\n好 说下去\n\n438\n00:29:53.011 --> 00:29:57.710 align:middle line:100%,end position:50%,middle\n一进去整个人就被音乐包围\n\n439\n00:29:57.820 --> 00:30:00.260 align:middle line:100%,end position:50%,middle\n<i>浩室音乐</i>，就像…砰…\n\n440\n00:30:03.259 --> 00:30:04.619 align:middle line:100%,end position:50%,middle\n你就会开始跳舞…\n\n441\n00:30:08.149 --> 00:30:09.769 align:middle line:100%,end position:50%,middle\n是的\n\n442\n00:30:13.468 --> 00:30:16.158 align:middle line:100%,end position:50%,middle\n隐瞒你是同性恋很难吗？\n\n443\n00:30:16.298 --> 00:30:18.908 align:middle line:100%,end position:50%,middle\n你在说什么？什么？\n\n444\n00:30:18.908 --> 00:30:20.107 align:middle line:100%,end position:50%,middle\n兄弟\n\n445\n00:30:20.107 --> 00:30:21.867 align:middle line:100%,end position:50%,middle\n两秒前你准备扑向我\n\n446\n00:30:21.977 --> 00:30:23.877 align:middle line:100%,end position:50%,middle\n扑？ 你…\n\n447\n00:30:25.077 --> 00:30:27.237 align:middle line:100%,end position:50%,middle\n很抱歉让你失望了 威尔\n\n448\n00:30:27.347 --> 00:30:30.366 align:middle line:100%,end position:50%,middle\n没关系 我不在乎你从后面上\n\n449\n00:30:30.486 --> 00:30:34.046 align:middle line:100%,end position:50%,middle\n从后面上你？ 你在讲什么？\n\n450\n00:30:34.166 --> 00:30:42.025 align:middle line:100%,end position:50%,middle\n困难的定理就像性感的交响曲\n\n451\n00:30:42.025 --> 00:30:44.155 align:middle line:100%,end position:50%,middle\n你找别人 我应付不来\n\n452\n00:30:44.564 --> 00:30:46.494 align:middle line:100%,end position:50%,middle\n谢谢你 亨利\n\n453\n00:30:47.794 --> 00:30:52.933 align:middle line:100%,end position:50%,middle\n嗨，杰里，你知道吗？\n我不能再免费接这种咨询了\n\n454\n00:30:52.933 --> 00:30:54.803 align:middle line:100%,end position:50%,middle\n不值得\n\n455\n00:30:54.933 --> 00:30:55.873 align:middle line:100%,end position:50%,middle\n怎么了？\n\n456\n00:30:56.033 --> 00:30:57.903 align:middle line:100%,end position:50%,middle\n我下星期要上全国电视节目\n\n457\n00:30:57.903 --> 00:30:58.803 align:middle line:100%,end position:50%,middle\n没空告诉你\n\n458\n00:30:58.803 --> 00:31:04.382 align:middle line:100%,end position:50%,middle\n更别提这个胡言乱语的疯子 他肯定是疯了\n\n459\n00:31:04.382 --> 00:31:05.432 align:middle line:100%,end position:50%,middle\n亨利\n\n460\n00:31:06.812 --> 00:31:09.821 align:middle line:100%,end position:50%,middle\n好 你在你床上\n\n461\n00:31:09.821 --> 00:31:13.491 align:middle line:100%,end position:50%,middle\n你几岁？\n\n462\n00:31:14.421 --> 00:31:15.511 align:middle line:100%,end position:50%,middle\n七岁\n\n463\n00:31:16.421 --> 00:31:18.450 align:middle line:100%,end position:50%,middle\n你看到什么？\n\n464\n00:31:20.190 --> 00:31:22.160 align:middle line:100%,end position:50%,middle\n我房里有东西\n\n465\n00:31:22.660 --> 00:31:24.180 align:middle line:100%,end position:50%,middle\n是什么？\n\n466\n00:31:25.700 --> 00:31:29.959 align:middle line:100%,end position:50%,middle\n像是个人影，悬在我上方\n\n467\n00:31:30.599 --> 00:31:32.903 align:middle line:100%,end position:50%,middle\n你在安全的地方 威尔\n\n468\n00:31:34.346 --> 00:31:38.082 align:middle line:100%,end position:50%,middle\n它…它在摸我\n\n469\n00:31:38.152 --> 00:31:40.867 align:middle line:100%,end position:50%,middle\n它在摸你哪里？\n\n470\n00:31:40.867 --> 00:31:42.801 align:middle line:100%,end position:50%,middle\n它在摸我下面\n\n471\n00:31:45.005 --> 00:31:47.309 align:middle line:100%,end position:50%,middle\n我很紧张\n\n472\n00:31:47.649 --> 00:31:49.843 align:middle line:100%,end position:50%,middle\n不必紧张\n\n473\n00:31:50.955 --> 00:31:56.846 align:middle line:100%,end position:50%,middle\n我们跳啊跳 这一切真美\n\n474\n00:31:59.044 --> 00:32:02.589 align:middle line:100%,end position:50%,middle\n<i>因为日落前可以做爱</i>\n\n475\n00:32:04.508 --> 00:32:08.428 align:middle line:100%,end position:50%,middle\n<i>烟火飞舞</i>\n\n476\n00:32:08.512 --> 00:32:11.306 align:middle line:100%,end position:50%,middle\n<i>午后欢乐</i>\n\n477\n00:32:11.390 --> 00:32:13.392 align:middle line:100%,end position:50%,middle\n<i>午后欢乐</i>\n\n478\n00:32:13.475 --> 00:32:14.977 align:middle line:100%,end position:50%,middle\n老天\n\n479\n00:32:18.704 --> 00:32:19.225 align:middle line:100%,end position:50%,middle\n抱歉 瑞克\n\n480\n00:32:19.335 --> 00:32:20.768 align:middle line:100%,end position:50%,middle\n来吧 瑞克\n\n481\n00:32:20.878 --> 00:32:21.930 align:middle line:100%,end position:50%,middle\n我有更重要的事情要做\n\n482\n00:32:21.942 --> 00:32:26.154 align:middle line:100%,end position:50%,middle\n<i>午后欢乐</i>\n一支舞就好了嘛！\n\n483\n00:32:26.518 --> 00:32:28.462 align:middle line:100%,end position:50%,middle\n你把我催眠了\n\n484\n00:32:28.792 --> 00:32:29.894 align:middle line:100%,end position:50%,middle\n看在老天份上 威尔\n\n485\n00:32:30.034 --> 00:32:33.030 align:middle line:100%,end position:50%,middle\n干嘛？ 他走了不能怪我\n\n486\n00:32:33.410 --> 00:32:34.933 align:middle line:100%,end position:50%,middle\n我叫你跟这些人合作\n\n487\n00:32:35.915 --> 00:32:36.526 align:middle line:100%,end position:50%,middle\n看着…\n\n488\n00:32:36.526 --> 00:32:38.259 align:middle line:100%,end position:50%,middle\n我的眼睛\n\n489\n00:32:38.259 --> 00:32:39.091 align:middle line:100%,end position:50%,middle\n出去\n\n490\n00:32:39.361 --> 00:32:41.094 align:middle line:100%,end position:50%,middle\n我不需要治疗\n\n491\n00:32:41.234 --> 00:32:42.216 align:middle line:100%,end position:50%,middle\n够了，出去！\n\n492\n00:32:45.241 --> 00:32:47.435 align:middle line:100%,end position:50%,middle\n我早上打给梅尔·温特劳布 想问问…\n\n493\n00:32:47.546 --> 00:32:48.577 align:middle line:100%,end position:50%,middle\n算了 有什么用？\n\n494\n00:32:49.519 --> 00:32:50.681 align:middle line:100%,end position:50%,middle\n你想怎么做？\n\n495\n00:32:53.787 --> 00:32:57.273 align:middle line:100%,end position:50%,middle\n有个人\n\n496\n00:32:57.273 --> 00:32:58.204 align:middle line:100%,end position:50%,middle\n是谁？\n\n497\n00:32:58.375 --> 00:33:03.253 align:middle line:100%,end position:50%,middle\n他是我大学室友\n\n498\n00:33:03.775 --> 00:33:07.154 align:middle line:100%,end position:50%,middle\n邦克山社区大学\n\n499\n00:33:07.471 --> 00:33:11.238 align:middle line:100%,end position:50%,middle\n信任 对感情关系很重要\n\n500\n00:33:11.378 --> 00:33:13.321 align:middle line:100%,end position:50%,middle\n在临床治疗中也很重要\n\n501\n00:33:13.421 --> 00:33:15.856 align:middle line:100%,end position:50%,middle\n为何信任对于突破患者心防\n\n502\n00:33:16.026 --> 00:33:19.302 align:middle line:100%,end position:50%,middle\n是最重要的关键？\n\n503\n00:33:20.855 --> 00:33:25.373 align:middle line:100%,end position:50%,middle\n莫琳 先别忙着啃东西 专心听课\n\n504\n00:33:25.853 --> 00:33:26.985 align:middle line:100%,end position:50%,middle\n维尼\n\n505\n00:33:27.557 --> 00:33:35.270 align:middle line:100%,end position:50%,middle\n因为信任就是生命\n\n506\n00:33:35.270 --> 00:33:38.907 align:middle line:100%,end position:50%,middle\n很深奥 谢谢你\n\n507\n00:33:39.428 --> 00:33:40.389 align:middle line:100%,end position:50%,middle\n下次去找你弟弟要笔记\n\n508\n00:33:40.499 --> 00:33:41.331 align:middle line:100%,end position:50%,middle\n没有\n\n509\n00:33:41.702 --> 00:33:43.294 align:middle line:100%,end position:50%,middle\n如果病患没有足够的安全感来信任你\n\n510\n00:33:43.405 --> 00:33:45.258 align:middle line:100%,end position:50%,middle\n就不会坦诚相对\n\n511\n00:33:45.258 --> 00:33:47.512 align:middle line:100%,end position:50%,middle\n治疗对他们来说就毫无意义\n\n512\n00:33:47.512 --> 00:33:50.657 align:middle line:100%,end position:50%,middle\n不信任你就不会跟你上床\n\n513\n00:33:50.657 --> 00:33:52.691 align:middle line:100%,end position:50%,middle\n那该是心理医生的最终目的\n\n514\n00:33:52.691 --> 00:33:56.107 align:middle line:100%,end position:50%,middle\n趁脆弱时下手 我的座右铭\n\n515\n00:33:56.107 --> 00:33:59.133 align:middle line:100%,end position:50%,middle\n很好 大家都醒了 欢迎回来\n\n516\n00:34:00.445 --> 00:34:01.437 align:middle line:100%,end position:50%,middle\n你好 肖恩\n\n517\n00:34:03.761 --> 00:34:04.953 align:middle line:100%,end position:50%,middle\n嗨 杰里\n\n518\n00:34:06.395 --> 00:34:11.244 align:middle line:100%,end position:50%,middle\n现在介绍一个大人物给各位\n\n519\n00:34:11.384 --> 00:34:13.047 align:middle line:100%,end position:50%,middle\n杰拉尔德·兰博教授\n\n520\n00:34:13.218 --> 00:34:15.552 align:middle line:100%,end position:50%,middle\n组合数学领域的菲尔兹奖得主\n\n521\n00:34:15.692 --> 00:34:18.226 align:middle line:100%,end position:50%,middle\n有人知道菲尔兹奖是什么吗？\n\n522\n00:34:18.337 --> 00:34:21.332 align:middle line:100%,end position:50%,middle\n了不起 数学界的诺贝尔奖\n\n523\n00:34:21.673 --> 00:34:24.237 align:middle line:100%,end position:50%,middle\n只是它四年才颁一次\n\n524\n00:34:25.189 --> 00:34:26.541 align:middle line:100%,end position:50%,middle\n很伟大\n\n525\n00:34:26.541 --> 00:34:28.294 align:middle line:100%,end position:50%,middle\n是惊人的荣耀 好吧 下课\n\n526\n00:34:28.294 --> 00:34:32.041 align:middle line:100%,end position:50%,middle\n谢谢 礼拜一见\n\n527\n00:34:32.041 --> 00:34:33.333 align:middle line:100%,end position:50%,middle\n下次我们谈弗洛伊德\n\n528\n00:34:33.504 --> 00:34:36.278 align:middle line:100%,end position:50%,middle\n他吸的可卡因足够毒死小马\n谢谢\n\n529\n00:34:38.392 --> 00:34:41.127 align:middle line:100%,end position:50%,middle\n- 你好吗？\n- 真高兴见到你\n\n530\n00:34:41.367 --> 00:34:43.361 align:middle line:100%,end position:50%,middle\n很高兴见到你\n\n531\n00:34:43.471 --> 00:34:46.106 align:middle line:100%,end position:50%,middle\n我有一件你会感兴趣的事\n\n532\n00:34:46.907 --> 00:34:49.181 align:middle line:100%,end position:50%,middle\n干嘛？还要验血验尿吗？怎么了？\n\n533\n00:34:49.782 --> 00:34:51.485 align:middle line:100%,end position:50%,middle\n同学会你怎么不来？\n\n534\n00:34:51.626 --> 00:34:54.391 align:middle line:100%,end position:50%,middle\n我在忙\n\n535\n00:34:55.272 --> 00:34:56.434 align:middle line:100%,end position:50%,middle\n大家很想你\n\n536\n00:34:56.574 --> 00:34:57.566 align:middle line:100%,end position:50%,middle\n真的？\n\n537\n00:34:57.676 --> 00:34:59.580 align:middle line:100%,end position:50%,middle\n我们多久没见了？\n\n538\n00:35:00.551 --> 00:35:02.114 align:middle line:100%,end position:50%,middle\n南茜去世前\n\n539\n00:35:02.224 --> 00:35:03.557 align:middle line:100%,end position:50%,middle\n是 很抱歉\n\n540\n00:35:03.988 --> 00:35:06.432 align:middle line:100%,end position:50%,middle\n我在巴黎开会 都是那该死的会议\n\n541\n00:35:06.532 --> 00:35:08.335 align:middle line:100%,end position:50%,middle\n我收到卡片 很好\n\n542\n00:35:13.885 --> 00:35:15.618 align:middle line:100%,end position:50%,middle\n- 过来\n- 摔得真漂亮\n\n543\n00:35:15.728 --> 00:35:16.750 align:middle line:100%,end position:50%,middle\n嘿\n\n544\n00:35:17.031 --> 00:35:19.295 align:middle line:100%,end position:50%,middle\n怎么样？ 法官有从轻发落吗？\n\n545\n00:35:19.605 --> 00:35:23.632 align:middle line:100%,end position:50%,middle\n我获准缓刑 每周还要接受两次心理咨询\n\n546\n00:35:24.614 --> 00:35:26.588 align:middle line:100%,end position:50%,middle\n开玩笑的 你真会说话\n\n547\n00:35:26.688 --> 00:35:28.211 align:middle line:100%,end position:50%,middle\n摩根！ 屈服吧！\n\n548\n00:35:29.733 --> 00:35:32.388 align:middle line:100%,end position:50%,middle\n放开他 我们会错过球赛的\n\n549\n00:35:32.568 --> 00:35:34.542 align:middle line:100%,end position:50%,middle\n我行程很满 我很忙\n\n550\n00:35:34.642 --> 00:35:37.617 align:middle line:100%,end position:50%,middle\n这孩子不可思议 前所未见\n\n551\n00:35:37.717 --> 00:35:39.881 align:middle line:100%,end position:50%,middle\n是什么让他这么不可思议？\n\n552\n00:35:40.863 --> 00:35:42.356 align:middle line:100%,end position:50%,middle\n听过拉马努金吗？\n\n553\n00:35:42.496 --> 00:35:45.471 align:middle line:100%,end position:50%,middle\n听过…没有\n\n554\n00:35:45.712 --> 00:35:46.643 align:middle line:100%,end position:50%,middle\n他是个男人\n\n555\n00:35:47.485 --> 00:35:50.149 align:middle line:100%,end position:50%,middle\n活在一百多年前 印度人\n\n556\n00:35:50.149 --> 00:35:52.964 align:middle line:100%,end position:50%,middle\n- 额头点饰，不是羽毛\n- 不是羽毛，对\n\n557\n00:35:52.964 --> 00:35:55.699 align:middle line:100%,end position:50%,middle\n他住在茅屋里 没受过教育\n\n558\n00:35:55.699 --> 00:36:00.177 align:middle line:100%,end position:50%,middle\n- 无法接触到任何科学著述\n- 要咖啡吗？\n\n559\n00:36:00.177 --> 00:36:02.451 align:middle line:100%,end position:50%,middle\n- 你呢 先生？\n- 一点就好\n\n560\n00:36:02.451 --> 00:36:05.026 align:middle line:100%,end position:50%,middle\n但他偶然发现一本旧数学课本\n\n561\n00:36:05.026 --> 00:36:09.574 align:middle line:100%,end position:50%,middle\n他从简单的课本中\n推演出困扰数学家多年的理论\n\n562\n00:36:09.674 --> 00:36:12.810 align:middle line:100%,end position:50%,middle\n对，连分数。他写了…\n\n563\n00:36:12.950 --> 00:36:15.685 align:middle line:100%,end position:50%,middle\n- 他寄给剑桥的哈代\n- 对 剑桥 对\n\n564\n00:36:16.727 --> 00:36:19.862 align:middle line:100%,end position:50%,middle\n哈代立刻看出他的作品有多出色\n\n565\n00:36:20.133 --> 00:36:21.575 align:middle line:100%,end position:50%,middle\n把他带到英国\n\n566\n00:36:21.746 --> 00:36:23.679 align:middle line:100%,end position:50%,middle\n然后他们合作多年\n\n567\n00:36:23.879 --> 00:36:26.704 align:middle line:100%,end position:50%,middle\n创造出令人兴奋的数学理论\n\n568\n00:36:26.704 --> 00:36:33.056 align:middle line:100%,end position:50%,middle\n这位拉马努金…他的天才无与伦比 肖恩\n\n569\n00:36:33.306 --> 00:36:35.139 align:middle line:100%,end position:50%,middle\n这孩子就像他一样\n\n570\n00:36:36.612 --> 00:36:39.217 align:middle line:100%,end position:50%,middle\n但他有点防备心\n\n571\n00:36:40.258 --> 00:36:42.292 align:middle line:100%,end position:50%,middle\n我需要有人突破他的心防\n\n572\n00:36:42.292 --> 00:36:45.007 align:middle line:100%,end position:50%,middle\n像是我\n\n573\n00:36:45.007 --> 00:36:46.269 align:middle line:100%,end position:50%,middle\n对 就是你\n\n574\n00:36:46.409 --> 00:36:47.241 align:middle line:100%,end position:50%,middle\n为什么？\n\n575\n00:36:47.341 --> 00:36:49.244 align:middle line:100%,end position:50%,middle\n因为你们有相同背景\n\n576\n00:36:49.355 --> 00:36:50.316 align:middle line:100%,end position:50%,middle\n什么背景？\n\n577\n00:36:50.416 --> 00:36:51.859 align:middle line:100%,end position:50%,middle\n你们来自同一个区\n\n578\n00:36:52.430 --> 00:36:53.392 align:middle line:100%,end position:50%,middle\n他是南区人？\n\n579\n00:36:53.492 --> 00:36:54.654 align:middle line:100%,end position:50%,middle\n是的\n\n580\n00:36:55.165 --> 00:36:58.671 align:middle line:100%,end position:50%,middle\n南区的天才少年\n\n581\n00:36:58.741 --> 00:37:01.115 align:middle line:100%,end position:50%,middle\n你之前找过几个心理医生？\n\n582\n00:37:02.057 --> 00:37:03.019 align:middle line:100%,end position:50%,middle\n五个\n\n583\n00:37:03.019 --> 00:37:07.397 align:middle line:100%,end position:50%,middle\n让我猜 拜瑞 亨利 没找瑞克吧\n\n584\n00:37:07.397 --> 00:37:10.662 align:middle line:100%,end position:50%,middle\n拜托 请跟他碰面 一周一次就好\n\n585\n00:37:10.662 --> 00:37:12.626 align:middle line:100%,end position:50%,middle\n拜托？\n\n586\n00:37:15.922 --> 00:37:18.767 align:middle line:100%,end position:50%,middle\n这就像打牌 别让牌泄底\n\n587\n00:37:19.268 --> 00:37:21.642 align:middle line:100%,end position:50%,middle\n要是他找得到 说不定早就看过你的书了\n\n588\n00:37:21.912 --> 00:37:23.375 align:middle line:100%,end position:50%,middle\n他要找到很难\n\n589\n00:37:24.317 --> 00:37:25.248 align:middle line:100%,end position:50%,middle\n威尔\n\n590\n00:37:26.050 --> 00:37:28.284 align:middle line:100%,end position:50%,middle\n这是肖恩·麦奎尔 威尔·亨廷\n\n591\n00:37:28.394 --> 00:37:29.255 align:middle line:100%,end position:50%,middle\n你好\n\n592\n00:37:34.515 --> 00:37:35.877 align:middle line:100%,end position:50%,middle\n好 开始\n\n593\n00:37:35.977 --> 00:37:36.488 align:middle line:100%,end position:50%,middle\n对 来吧\n\n594\n00:37:36.488 --> 00:37:38.612 align:middle line:100%,end position:50%,middle\n我兴奋极了 让疗愈开始吧\n\n595\n00:37:38.702 --> 00:37:40.986 align:middle line:100%,end position:50%,middle\n请让我们单独谈谈好吗？\n\n596\n00:37:41.227 --> 00:37:42.319 align:middle line:100%,end position:50%,middle\n好 麻烦你了 汤姆\n\n597\n00:37:42.469 --> 00:37:43.661 align:middle line:100%,end position:50%,middle\n你也出去\n\n598\n00:37:44.963 --> 00:37:46.887 align:middle line:100%,end position:50%,middle\n好 当然\n\n599\n00:37:52.356 --> 00:37:53.228 align:middle line:100%,end position:50%,middle\n你好吗？\n\n600\n00:37:56.273 --> 00:37:57.966 align:middle line:100%,end position:50%,middle\n你是南区哪里人？\n\n601\n00:37:58.447 --> 00:38:00.170 align:middle line:100%,end position:50%,middle\n我喜欢你这边的装潢\n\n602\n00:38:00.381 --> 00:38:01.142 align:middle line:100%,end position:50%,middle\n谢谢\n\n603\n00:38:01.483 --> 00:38:03.977 align:middle line:100%,end position:50%,middle\n这些书你都是按零售价买的\n\n604\n00:38:03.977 --> 00:38:08.074 align:middle line:100%,end position:50%,middle\n还是邮购了附赠整套书的\n心理医生套装？\n\n605\n00:38:08.074 --> 00:38:09.236 align:middle line:100%,end position:50%,middle\n你喜欢看书？\n\n606\n00:38:10.278 --> 00:38:11.210 align:middle line:100%,end position:50%,middle\n喜欢\n\n607\n00:38:11.781 --> 00:38:12.903 align:middle line:100%,end position:50%,middle\n这些书你读过吗？\n\n608\n00:38:13.013 --> 00:38:13.985 align:middle line:100%,end position:50%,middle\n不知道\n\n609\n00:38:14.415 --> 00:38:15.908 align:middle line:100%,end position:50%,middle\n那些书呢？\n\n610\n00:38:16.128 --> 00:38:16.960 align:middle line:100%,end position:50%,middle\n大概没有\n\n611\n00:38:17.090 --> 00:38:18.933 align:middle line:100%,end position:50%,middle\n顶层那些呢？ 看过没？\n\n612\n00:38:20.837 --> 00:38:21.829 align:middle line:100%,end position:50%,middle\n看过\n\n613\n00:38:21.979 --> 00:38:24.604 align:middle line:100%,end position:50%,middle\n很好 你有什么感想？\n\n614\n00:38:24.714 --> 00:38:26.307 align:middle line:100%,end position:50%,middle\n我不是他妈的来做读书报告\n\n615\n00:38:26.417 --> 00:38:27.859 align:middle line:100%,end position:50%,middle\n那是你的书 你怎么不读\n\n616\n00:38:27.959 --> 00:38:29.462 align:middle line:100%,end position:50%,middle\n我读过 非读不可\n\n617\n00:38:29.462 --> 00:38:31.836 align:middle line:100%,end position:50%,middle\n一定花了你不少时间\n\n618\n00:38:31.836 --> 00:38:32.898 align:middle line:100%,end position:50%,middle\n是的\n\n619\n00:38:39.720 --> 00:38:44.138 align:middle line:100%,end position:50%,middle\n<i>美国通史 第一册</i>\n\n620\n00:38:55.168 --> 00:38:58.634 align:middle line:100%,end position:50%,middle\n天哪 想看真的历史的话\n\n621\n00:38:58.744 --> 00:39:00.738 align:middle line:100%,end position:50%,middle\n就读霍华德·津恩的《<i>美国人民的历史</i>》\n\n622\n00:39:00.848 --> 00:39:02.681 align:middle line:100%,end position:50%,middle\n那本书会把你震住\n\n623\n00:39:02.821 --> 00:39:04.685 align:middle line:100%,end position:50%,middle\n比乔姆斯基的《<i>制造共识</i>》更好吗？\n\n624\n00:39:04.795 --> 00:39:06.097 align:middle line:100%,end position:50%,middle\n你觉得那是本好书？\n\n625\n00:39:06.197 --> 00:39:09.613 align:middle line:100%,end position:50%,middle\n我搞不懂你们这些人\n\n626\n00:39:09.613 --> 00:39:11.687 align:middle line:100%,end position:50%,middle\n你把钱全花在这些他妈的花哨书上\n\n627\n00:39:11.687 --> 00:39:14.552 align:middle line:100%,end position:50%,middle\n还把自己埋在这些书里 可偏偏都是他妈的烂书\n\n628\n00:39:14.552 --> 00:39:16.425 align:middle line:100%,end position:50%,middle\n什么是他妈的对的书？\n\n629\n00:39:16.796 --> 00:39:18.559 align:middle line:100%,end position:50%,middle\n能让你来劲的\n\n630\n00:39:18.700 --> 00:39:21.274 align:middle line:100%,end position:50%,middle\n我剩的头发不多\n\n631\n00:39:21.274 --> 00:39:23.378 align:middle line:100%,end position:50%,middle\n你不如把烟塞自己屁股里\n\n632\n00:39:23.378 --> 00:39:25.381 align:middle line:100%,end position:50%,middle\n对你的健康有好处\n\n633\n00:39:25.381 --> 00:39:28.797 align:middle line:100%,end position:50%,middle\n我知道 抽烟妨碍我练瑜伽\n\n634\n00:39:28.797 --> 00:39:29.589 align:middle line:100%,end position:50%,middle\n你运动吗？\n\n635\n00:39:30.330 --> 00:39:31.422 align:middle line:100%,end position:50%,middle\n你举重吗？\n\n636\n00:39:31.532 --> 00:39:32.364 align:middle line:100%,end position:50%,middle\n对\n\n637\n00:39:32.634 --> 00:39:33.536 align:middle line:100%,end position:50%,middle\n举重机？\n\n638\n00:39:33.776 --> 00:39:34.678 align:middle line:100%,end position:50%,middle\n不 自由重量\n\n639\n00:39:34.778 --> 00:39:35.610 align:middle line:100%,end position:50%,middle\n真的？\n\n640\n00:39:35.710 --> 00:39:36.511 align:middle line:100%,end position:50%,middle\n自由重量训练，是吗？\n\n641\n00:39:36.611 --> 00:39:38.014 align:middle line:100%,end position:50%,middle\n对 很行\n\n642\n00:39:38.124 --> 00:39:39.056 align:middle line:100%,end position:50%,middle\n你卧推多少？\n\n643\n00:39:39.156 --> 00:39:40.488 align:middle line:100%,end position:50%,middle\n285 你呢？\n\n644\n00:39:42.902 --> 00:39:44.095 align:middle line:100%,end position:50%,middle\n你画的？\n\n645\n00:39:45.207 --> 00:39:46.639 align:middle line:100%,end position:50%,middle\n对 你画画吗？\n\n646\n00:39:47.541 --> 00:39:48.142 align:middle line:100%,end position:50%,middle\n你雕塑吗？\n\n647\n00:39:49.554 --> 00:39:49.985 align:middle line:100%,end position:50%,middle\n不\n\n648\n00:39:50.085 --> 00:39:50.716 align:middle line:100%,end position:50%,middle\n喜欢艺术吗？\n\n649\n00:39:50.816 --> 00:39:52.119 align:middle line:100%,end position:50%,middle\n不\n\n650\n00:39:52.830 --> 00:39:53.882 align:middle line:100%,end position:50%,middle\n喜欢音乐吗？\n\n651\n00:39:55.304 --> 00:39:56.797 align:middle line:100%,end position:50%,middle\n真烂\n\n652\n00:39:57.368 --> 00:39:59.472 align:middle line:100%,end position:50%,middle\n告诉我你觉得怎么样\n\n653\n00:39:59.682 --> 00:40:05.122 align:middle line:100%,end position:50%,middle\n线条风格和印象派混在一起\n让构图乱七八糟\n\n654\n00:40:05.262 --> 00:40:09.199 align:middle line:100%,end position:50%,middle\n这还抄了温斯洛·霍默的画\n只是船上多了个白人划船\n\n655\n00:40:09.540 --> 00:40:11.203 align:middle line:100%,end position:50%,middle\n那是美术入门课时画的\n画得不怎么样\n\n656\n00:40:11.313 --> 00:40:12.785 align:middle line:100%,end position:50%,middle\n我在意的不是那个\n\n657\n00:40:12.886 --> 00:40:13.938 align:middle line:100%,end position:50%,middle\n你在意什么？\n\n658\n00:40:14.048 --> 00:40:14.819 align:middle line:100%,end position:50%,middle\n色彩\n\n659\n00:40:14.919 --> 00:40:16.592 align:middle line:100%,end position:50%,middle\n你知道这幅画最糟的地方是什么吗？\n\n660\n00:40:16.592 --> 00:40:18.666 align:middle line:100%,end position:50%,middle\n按数字填色的\n\n661\n00:40:18.666 --> 00:40:21.230 align:middle line:100%,end position:50%,middle\n以数字上色？ 至少这色彩让我着迷\n\n662\n00:40:21.341 --> 00:40:22.863 align:middle line:100%,end position:50%,middle\n真的这么迷人？\n\n663\n00:40:22.974 --> 00:40:25.949 align:middle line:100%,end position:50%,middle\n当然 我看你离割耳朵不远了\n\n664\n00:40:26.049 --> 00:40:26.880 align:middle line:100%,end position:50%,middle\n真的？\n\n665\n00:40:27.021 --> 00:40:28.043 align:middle line:100%,end position:50%,middle\n没错\n\n666\n00:40:28.193 --> 00:40:30.958 align:middle line:100%,end position:50%,middle\n那我该搬去法国南部 改名叫文森特\n\n667\n00:40:32.100 --> 00:40:34.043 align:middle line:100%,end position:50%,middle\n听过“人在风暴中 有个港口就行”这句话吗？\n\n668\n00:40:34.143 --> 00:40:34.734 align:middle line:100%,end position:50%,middle\n听过\n\n669\n00:40:34.845 --> 00:40:37.219 align:middle line:100%,end position:50%,middle\n也许指的就是你\n\n670\n00:40:37.219 --> 00:40:38.311 align:middle line:100%,end position:50%,middle\n哪方面？\n\n671\n00:40:38.591 --> 00:40:41.216 align:middle line:100%,end position:50%,middle\n也许你正在暴风雨中\n\n672\n00:40:41.216 --> 00:40:41.927 align:middle line:100%,end position:50%,middle\n也许吧\n\n673\n00:40:41.927 --> 00:40:44.462 align:middle line:100%,end position:50%,middle\n天快塌下来，巨浪砸在你的小船上\n\n674\n00:40:44.572 --> 00:40:47.347 align:middle line:100%,end position:50%,middle\n桨就要断了\n\n675\n00:40:47.377 --> 00:40:49.751 align:middle line:100%,end position:50%,middle\n你吓坏了 迫切需要港口\n\n676\n00:40:49.851 --> 00:40:53.999 align:middle line:100%,end position:50%,middle\n也许你会想办法逃出来\n也许这就是你当心理医生的原因\n\n677\n00:40:53.999 --> 00:40:55.732 align:middle line:100%,end position:50%,middle\n答对了 就是这样\n\n678\n00:40:55.972 --> 00:40:58.026 align:middle line:100%,end position:50%,middle\n现在让我做我的工作吧\n先说说你，来吧\n\n679\n00:41:00.149 --> 00:41:01.512 align:middle line:100%,end position:50%,middle\n也许你娶错女人\n\n680\n00:41:01.682 --> 00:41:03.055 align:middle line:100%,end position:50%,middle\n也许你讲话该小心点\n\n681\n00:41:05.499 --> 00:41:07.222 align:middle line:100%,end position:50%,middle\n小心点 好吗？\n\n682\n00:41:16.629 --> 00:41:22.439 align:middle line:100%,end position:50%,middle\n就是这样 对吧？你娶错了女人\n\n683\n00:41:22.740 --> 00:41:23.902 align:middle line:100%,end position:50%,middle\n发生什么事了？\n\n684\n00:41:25.985 --> 00:41:27.388 align:middle line:100%,end position:50%,middle\n她抛弃你了？\n\n685\n00:41:27.518 --> 00:41:29.892 align:middle line:100%,end position:50%,middle\n她是不是搞上别的男人？\n\n686\n00:41:31.766 --> 00:41:35.102 align:middle line:100%,end position:50%,middle\n再对我太太无礼就宰了你\n\n687\n00:41:35.242 --> 00:41:36.875 align:middle line:100%,end position:50%,middle\n我会他妈的宰了你\n\n688\n00:41:37.616 --> 00:41:39.089 align:middle line:100%,end position:50%,middle\n听到没？\n\n689\n00:41:41.323 --> 00:41:42.525 align:middle line:100%,end position:50%,middle\n时间到了\n\n690\n00:41:42.875 --> 00:41:45.219 align:middle line:100%,end position:50%,middle\n是的\n\n691\n00:41:57.752 --> 00:41:59.054 align:middle line:100%,end position:50%,middle\n稍息 两位\n\n692\n00:42:05.916 --> 00:42:06.908 align:middle line:100%,end position:50%,middle\n你没事吧？\n\n693\n00:42:13.269 --> 00:42:16.265 align:middle line:100%,end position:50%,middle\n如果你不再想见他 我了解\n\n694\n00:42:17.076 --> 00:42:19.110 align:middle line:100%,end position:50%,middle\n星期四下午四点\n\n695\n00:42:19.110 --> 00:42:21.644 align:middle line:100%,end position:50%,middle\n一定要他来\n\n696\n00:42:23.147 --> 00:42:27.655 align:middle line:100%,end position:50%,middle\n好 谢谢\n\n697\n00:43:31.668 --> 00:43:35.205 align:middle line:100%,end position:50%,middle\n你戴那副眼镜好可爱\n\n698\n00:43:35.315 --> 00:43:36.407 align:middle line:100%,end position:50%,middle\n多谢你\n\n699\n00:43:36.657 --> 00:43:37.348 align:middle line:100%,end position:50%,middle\n真漂亮\n\n700\n00:43:37.459 --> 00:43:39.432 align:middle line:100%,end position:50%,middle\n我一直想擦深蓝色眼影\n\n701\n00:43:39.963 --> 00:43:41.025 align:middle line:100%,end position:50%,middle\n美极了\n\n702\n00:43:43.660 --> 00:43:47.126 align:middle line:100%,end position:50%,middle\n我在英国长大 念好学校\n\n703\n00:43:47.186 --> 00:43:50.552 align:middle line:100%,end position:50%,middle\n那是一种进步、注重自然\n\n704\n00:43:50.662 --> 00:43:52.515 align:middle line:100%,end position:50%,middle\n又独立自主的私立学校\n\n705\n00:43:52.515 --> 00:43:56.983 align:middle line:100%,end position:50%,middle\n接着去哈佛 希望能上医学院\n\n706\n00:43:57.073 --> 00:43:57.905 align:middle line:100%,end position:50%,middle\n你知道我发现什么？\n\n707\n00:43:58.015 --> 00:44:03.375 align:middle line:100%,end position:50%,middle\n最后我的脑子 会价值25万美元\n\n708\n00:44:03.765 --> 00:44:05.669 align:middle line:100%,end position:50%,middle\n听起来很可怕吧\n\n709\n00:44:07.051 --> 00:44:09.816 align:middle line:100%,end position:50%,middle\n再来一杯“迈泰”鸡尾酒\n\n710\n00:44:09.816 --> 00:44:13.982 align:middle line:100%,end position:50%,middle\n酷 你父母一定很乐于付钱\n\n711\n00:44:14.082 --> 00:44:16.639 align:middle line:100%,end position:50%,middle\n不是 我很乐意付钱 我继承了一笔遗产\n\n712\n00:44:18.308 --> 00:44:21.674 align:middle line:100%,end position:50%,middle\n那么钱都给哈佛吗？\n\n713\n00:44:21.814 --> 00:44:24.741 align:middle line:100%,end position:50%,middle\n不 是斯坦福 六月毕业后我就去那儿\n\n714\n00:44:24.941 --> 00:44:29.007 align:middle line:100%,end position:50%,middle\n所以你只是想利用这个水手啰\n\n715\n00:44:29.117 --> 00:44:32.644 align:middle line:100%,end position:50%,middle\n我本来还想先拿你做解剖课的实验呢 当然\n\n716\n00:44:32.644 --> 00:44:34.272 align:middle line:100%,end position:50%,middle\n这样的话 好吧\n\n717\n00:44:35.681 --> 00:44:37.479 align:middle line:100%,end position:50%,middle\n想看我变魔术吗 斯凯勒？\n\n718\n00:44:37.579 --> 00:44:38.438 align:middle line:100%,end position:50%,middle\n好啊\n\n719\n00:44:38.578 --> 00:44:41.485 align:middle line:100%,end position:50%,middle\n好 保证…\n\n720\n00:44:41.485 --> 00:44:43.813 align:middle line:100%,end position:50%,middle\n好的\n\n721\n00:44:44.382 --> 00:44:45.871 align:middle line:100%,end position:50%,middle\n这是给你的 鲁道夫\n\n722\n00:44:46.080 --> 00:44:47.879 align:middle line:100%,end position:50%,middle\n等等 你需要我的魔杖\n\n723\n00:44:48.108 --> 00:44:49.207 align:middle line:100%,end position:50%,middle\n好 来一口 谢谢 好了\n\n724\n00:44:49.547 --> 00:44:52.484 align:middle line:100%,end position:50%,middle\n我要让这些焦糖全都消失\n\n725\n00:44:52.984 --> 00:44:55.171 align:middle line:100%,end position:50%,middle\n准备好了吗？\n\n726\n00:44:55.581 --> 00:44:58.098 align:middle line:100%,end position:50%,middle\n一 二 三\n\n727\n00:44:58.248 --> 00:45:01.235 align:middle line:100%,end position:50%,middle\n全不见了\n\n728\n00:45:01.375 --> 00:45:03.893 align:middle line:100%,end position:50%,middle\n刚才那是我的…有兔子的话效果会更好\n\n729\n00:45:06.850 --> 00:45:09.577 align:middle line:100%,end position:50%,middle\n我不常约会\n\n730\n00:45:09.677 --> 00:45:12.664 align:middle line:100%,end position:50%,middle\n对我来说真可惜\n\n731\n00:45:14.842 --> 00:45:17.749 align:middle line:100%,end position:50%,middle\n你懂我意思 我知道你在想什么\n\n732\n00:45:17.979 --> 00:45:19.537 align:middle line:100%,end position:50%,middle\n- 我没有\n- 我知道你有\n\n733\n00:45:19.677 --> 00:45:20.936 align:middle line:100%,end position:50%,middle\n真的没有\n\n734\n00:45:21.046 --> 00:45:22.944 align:middle line:100%,end position:50%,middle\n你有 你想要睡前一吻\n\n735\n00:45:23.044 --> 00:45:25.851 align:middle line:100%,end position:50%,middle\n不 我想要睡前一炮\n\n736\n00:45:28.708 --> 00:45:30.706 align:middle line:100%,end position:50%,middle\n我愿意勉强接受一吻\n\n737\n00:45:30.876 --> 00:45:32.535 align:middle line:100%,end position:50%,middle\n你很高尚\n\n738\n00:45:32.644 --> 00:45:33.574 align:middle line:100%,end position:50%,middle\n谢谢\n\n739\n00:45:34.043 --> 00:45:36.671 align:middle line:100%,end position:50%,middle\n不 我真的想要一吻\n\n740\n00:45:38.818 --> 00:45:41.246 align:middle line:100%,end position:50%,middle\n那我们现在就亲一下 把这事解决掉？\n\n741\n00:45:43.114 --> 00:45:43.873 align:middle line:100%,end position:50%,middle\n现在？\n\n742\n00:45:44.043 --> 00:45:47.190 align:middle line:100%,end position:50%,middle\n对 来\n\n743\n00:45:55.482 --> 00:45:58.519 align:middle line:100%,end position:50%,middle\n我好像吃到你的酸黄瓜了\n\n744\n00:46:09.019 --> 00:46:11.486 align:middle line:100%,end position:50%,middle\n又是你？\n\n745\n00:46:13.544 --> 00:46:14.643 align:middle line:100%,end position:50%,middle\n跟我来\n\n746\n00:46:21.526 --> 00:46:24.144 align:middle line:100%,end position:50%,middle\n现在要干嘛？\n\n747\n00:46:24.144 --> 00:46:26.202 align:middle line:100%,end position:50%,middle\n两个男人之间也要来段“行家之选”\n咖啡广告桥段？\n\n748\n00:46:27.061 --> 00:46:29.718 align:middle line:100%,end position:50%,middle\n这里真不错\n\n749\n00:46:29.718 --> 00:46:31.736 align:middle line:100%,end position:50%,middle\n你喜欢天鹅？ 这算恋物癖吗？\n\n750\n00:46:31.846 --> 00:46:34.743 align:middle line:100%,end position:50%,middle\n这是需要花点时间的事吗？\n\n751\n00:46:36.012 --> 00:46:40.008 align:middle line:100%,end position:50%,middle\n我在想你批评我画的事\n\n752\n00:46:41.517 --> 00:46:43.874 align:middle line:100%,end position:50%,middle\n为此想了大半夜\n\n753\n00:46:45.713 --> 00:46:47.651 align:middle line:100%,end position:50%,middle\n突然我想到一件事\n\n754\n00:46:47.651 --> 00:46:52.336 align:middle line:100%,end position:50%,middle\n然后沉沉睡去 从那以后就没再想你\n\n755\n00:46:52.646 --> 00:46:53.735 align:middle line:100%,end position:50%,middle\n你知道我当时想到什么吗？\n\n756\n00:46:54.214 --> 00:46:55.013 align:middle line:100%,end position:50%,middle\n不知道\n\n757\n00:46:55.713 --> 00:46:56.842 align:middle line:100%,end position:50%,middle\n你只是个孩子\n\n758\n00:46:57.751 --> 00:47:00.108 align:middle line:100%,end position:50%,middle\n你根本不晓得你在说什么\n\n759\n00:47:00.218 --> 00:47:01.147 align:middle line:100%,end position:50%,middle\n哎呀 谢谢\n\n760\n00:47:01.277 --> 00:47:03.105 align:middle line:100%,end position:50%,middle\n没关系\n\n761\n00:47:03.105 --> 00:47:05.523 align:middle line:100%,end position:50%,middle\n因为你没离开过波士顿\n\n762\n00:47:07.211 --> 00:47:09.649 align:middle line:100%,end position:50%,middle\n是没有\n\n763\n00:47:09.879 --> 00:47:11.577 align:middle line:100%,end position:50%,middle\n所以如果我问你艺术 你大概会\n\n764\n00:47:11.677 --> 00:47:13.905 align:middle line:100%,end position:50%,middle\n把你看过的每本艺术书里的门道都讲给我听\n\n765\n00:47:15.014 --> 00:47:18.440 align:middle line:100%,end position:50%,middle\n有关米开朗基罗 你知道很多\n\n766\n00:47:18.440 --> 00:47:22.376 align:middle line:100%,end position:50%,middle\n他的毕生创作、政治抱负 还有他和教皇\n\n767\n00:47:22.546 --> 00:47:24.674 align:middle line:100%,end position:50%,middle\n性倾向，各种细节，对吧？\n\n768\n00:47:27.152 --> 00:47:30.638 align:middle line:100%,end position:50%,middle\n但你不知道西斯汀教堂的气味\n\n769\n00:47:33.585 --> 00:47:37.542 align:middle line:100%,end position:50%,middle\n你从没站在那儿观赏美丽的天花板\n\n770\n00:47:40.649 --> 00:47:41.448 align:middle line:100%,end position:50%,middle\n你从没亲眼见过\n\n771\n00:47:43.216 --> 00:47:44.705 align:middle line:100%,end position:50%,middle\n如果我问关于女人的事\n\n772\n00:47:45.044 --> 00:47:47.672 align:middle line:100%,end position:50%,middle\n你大概会给我列一张你喜欢的女人名单\n\n773\n00:47:48.751 --> 00:47:51.078 align:middle line:100%,end position:50%,middle\n你可能上过几次床\n\n774\n00:47:56.613 --> 00:48:00.169 align:middle line:100%,end position:50%,middle\n但你说不出在女人身旁醒来\n\n775\n00:48:00.419 --> 00:48:02.147 align:middle line:100%,end position:50%,middle\n那种幸福的滋味\n\n776\n00:48:05.984 --> 00:48:09.270 align:middle line:100%,end position:50%,middle\n你是个硬气的孩子\n\n777\n00:48:09.270 --> 00:48:13.336 align:middle line:100%,end position:50%,middle\n问战争 你会说莎士比亚的话\n\n778\n00:48:13.446 --> 00:48:15.844 align:middle line:100%,end position:50%,middle\n“再冲一次缺口，亲爱的朋友”\n\n779\n00:48:18.252 --> 00:48:19.870 align:middle line:100%,end position:50%,middle\n但你从没接近过战争\n\n780\n00:48:21.418 --> 00:48:23.716 align:middle line:100%,end position:50%,middle\n从没把好友的头抱在膝盖上\n\n781\n00:48:24.216 --> 00:48:27.702 align:middle line:100%,end position:50%,middle\n看着他喘出最后一口气 望着你求救\n\n782\n00:48:30.450 --> 00:48:33.906 align:middle line:100%,end position:50%,middle\n问爱情 你会引述十四行诗\n\n783\n00:48:35.654 --> 00:48:38.911 align:middle line:100%,end position:50%,middle\n但你从没在一个女人面前彻底卸下防备\n\n784\n00:48:40.050 --> 00:48:42.308 align:middle line:100%,end position:50%,middle\n她能以双眼击倒你\n\n785\n00:48:44.246 --> 00:48:47.373 align:middle line:100%,end position:50%,middle\n感觉上帝让天使为你下凡\n\n786\n00:48:48.881 --> 00:48:51.179 align:middle line:100%,end position:50%,middle\n她能从地狱将你拯救出来\n\n787\n00:48:51.818 --> 00:48:54.176 align:middle line:100%,end position:50%,middle\n你不了解成为她天使的滋味\n\n788\n00:48:55.215 --> 00:48:57.942 align:middle line:100%,end position:50%,middle\n爱她直到永远\n\n789\n00:48:58.352 --> 00:49:02.608 align:middle line:100%,end position:50%,middle\n无论发生什么，哪怕是癌症\n\n790\n00:49:02.608 --> 00:49:07.024 align:middle line:100%,end position:50%,middle\n你无法体会在医院里坐着睡两个月\n一直握着她的手\n\n791\n00:49:07.353 --> 00:49:09.141 align:middle line:100%,end position:50%,middle\n因为医生看到你的眼神就明白\n\n792\n00:49:09.281 --> 00:49:11.749 align:middle line:100%,end position:50%,middle\n会客时间的规定对你无效\n\n793\n00:49:13.987 --> 00:49:15.985 align:middle line:100%,end position:50%,middle\n你不了解真正的失去\n\n794\n00:49:15.985 --> 00:49:21.030 align:middle line:100%,end position:50%,middle\n唯有爱别人胜于自己才能体会\n\n795\n00:49:21.419 --> 00:49:24.346 align:middle line:100%,end position:50%,middle\n我看你从来不敢那么爱一个人\n\n796\n00:49:27.713 --> 00:49:31.879 align:middle line:100%,end position:50%,middle\n我看着你，没看到聪明自信的男人\n\n797\n00:49:34.886 --> 00:49:38.283 align:middle line:100%,end position:50%,middle\n我看到被吓傻的狂妄孩子\n\n798\n00:49:40.051 --> 00:49:42.878 align:middle line:100%,end position:50%,middle\n但你是天才 没人能否认\n\n799\n00:49:43.448 --> 00:49:45.975 align:middle line:100%,end position:50%,middle\n没人能了解你的深度\n\n800\n00:49:47.114 --> 00:49:49.712 align:middle line:100%,end position:50%,middle\n但你看我的画就认定了解我\n\n801\n00:49:49.881 --> 00:49:52.579 align:middle line:100%,end position:50%,middle\n你把我的人生撕裂了\n\n802\n00:49:56.914 --> 00:49:58.573 align:middle line:100%,end position:50%,middle\n你是孤儿 对吧？\n\n803\n00:50:02.739 --> 00:50:06.975 align:middle line:100%,end position:50%,middle\n你觉得我会知道你的日子有多难吗\n\n804\n00:50:07.114 --> 00:50:09.212 align:middle line:100%,end position:50%,middle\n你的感受 你是谁\n\n805\n00:50:09.722 --> 00:50:12.209 align:middle line:100%,end position:50%,middle\n只是因为我看过《<i>雾都孤儿</i>》吗？\n\n806\n00:50:13.118 --> 00:50:15.276 align:middle line:100%,end position:50%,middle\n这就能概括你了吗？\n\n807\n00:50:17.754 --> 00:50:20.571 align:middle line:100%,end position:50%,middle\n我不在乎 因为\n\n808\n00:50:20.571 --> 00:50:25.506 align:middle line:100%,end position:50%,middle\n我无法从你身上学到\n那些书上没有的东西\n\n809\n00:50:27.185 --> 00:50:31.151 align:middle line:100%,end position:50%,middle\n除非你想谈自己 谈你是谁\n\n810\n00:50:32.849 --> 00:50:36.545 align:middle line:100%,end position:50%,middle\n那我就有兴趣了 我愿意加入\n\n811\n00:50:38.853 --> 00:50:41.181 align:middle line:100%,end position:50%,middle\n但你不想那么做 对吗 老弟？\n\n812\n00:50:43.898 --> 00:50:47.345 align:middle line:100%,end position:50%,middle\n你害怕自己会说出些什么\n\n813\n00:50:52.220 --> 00:50:53.848 align:middle line:100%,end position:50%,middle\n轮到你说了 大哥\n\n814\n00:52:01.682 --> 00:52:03.740 align:middle line:100%,end position:50%,middle\n喂？\n\n815\n00:52:03.740 --> 00:52:06.657 align:middle line:100%,end position:50%,middle\n喂？\n\n816\n00:52:06.737 --> 00:52:09.844 align:middle line:100%,end position:50%,middle\n瓦兰帝教授 又是你吗？\n\n817\n00:52:12.531 --> 00:52:14.949 align:middle line:100%,end position:50%,middle\n怪胎\n\n818\n00:52:18.255 --> 00:52:20.983 align:middle line:100%,end position:50%,middle\n天哪 你打给谁？\n\n819\n00:52:21.382 --> 00:52:23.051 align:middle line:100%,end position:50%,middle\n没有 我忘了号码\n\n820\n00:52:23.250 --> 00:52:25.019 align:middle line:100%,end position:50%,middle\n你他妈智障？\n\n821\n00:52:25.119 --> 00:52:26.347 align:middle line:100%,end position:50%,middle\n你冒着雨跑过去，却没带电话号码\n\n822\n00:52:26.487 --> 00:52:29.474 align:middle line:100%,end position:50%,middle\n才不是 那是你妈的900付费热线\n我只是硬币用完了\n\n823\n00:52:29.884 --> 00:52:32.481 align:middle line:100%,end position:50%,middle\n别再拿妈妈开黄腔了 我刚在你妈身上爽过\n\n824\n00:52:34.719 --> 00:52:37.586 align:middle line:100%,end position:50%,middle\n挺好笑，摩根\n那是个5美分硬币，小婊子\n\n825\n00:52:37.856 --> 00:52:39.584 align:middle line:100%,end position:50%,middle\n- 继续跟我作对看看\n- 好了\n\n826\n00:52:39.724 --> 00:52:40.943 align:middle line:100%,end position:50%,middle\n- 等着瞧\n- 好了 摩根\n\n827\n00:52:41.083 --> 00:52:43.990 align:middle line:100%,end position:50%,middle\n再整我啊\n\n828\n00:52:50.124 --> 00:52:51.283 align:middle line:100%,end position:50%,middle\n不准抽烟\n\n829\n00:53:23.781 --> 00:53:26.578 align:middle line:100%,end position:50%,middle\n什么叫没讲话？ 一个钟头\n\n830\n00:53:26.818 --> 00:53:29.615 align:middle line:100%,end position:50%,middle\n他就坐那儿数着秒 等会谈结束\n\n831\n00:53:30.025 --> 00:53:31.423 align:middle line:100%,end position:50%,middle\n让人印象蛮深刻的\n\n832\n00:53:31.583 --> 00:53:32.682 align:middle line:100%,end position:50%,middle\n他为什么要那么做？\n\n833\n00:53:32.922 --> 00:53:35.579 align:middle line:100%,end position:50%,middle\n证明他不想讲就不必讲\n\n834\n00:53:36.698 --> 00:53:40.914 align:middle line:100%,end position:50%,middle\n这是两个老街坊小孩在比瞪眼吗？\n\n835\n00:53:41.024 --> 00:53:44.251 align:middle line:100%,end position:50%,middle\n对 而且我不能先讲话\n\n836\n00:53:44.530 --> 00:53:46.618 align:middle line:100%,end position:50%,middle\n我们知道你的理论 亚历山大\n\n837\n00:53:46.618 --> 00:53:49.176 align:middle line:100%,end position:50%,middle\n但这孩子找出简单的几何图\n\n838\n00:53:49.286 --> 00:53:51.054 align:middle line:100%,end position:50%,middle\n树状结构行不通\n\n839\n00:53:51.154 --> 00:53:53.022 align:middle line:100%,end position:50%,middle\n他把两个顶点连起来了\n\n840\n00:53:53.122 --> 00:53:55.140 align:middle line:100%,end position:50%,middle\n但我算出总数\n\n841\n00:53:55.290 --> 00:53:57.048 align:middle line:100%,end position:50%,middle\n就是这样把各项分组的 亚历山大\n\n842\n00:53:57.158 --> 00:53:59.825 align:middle line:100%,end position:50%,middle\n但是 杰里 如果这样做…\n\n843\n00:53:59.825 --> 00:54:00.525 align:middle line:100%,end position:50%,middle\n看这里\n\n844\n00:54:00.525 --> 00:54:06.149 align:middle line:100%,end position:50%,middle\n我写下来了 这样比较简单\n\n845\n00:54:17.088 --> 00:54:19.016 align:middle line:100%,end position:50%,middle\n有些人就是走运\n\n846\n00:54:19.616 --> 00:54:22.043 align:middle line:100%,end position:50%,middle\n你是很聪明的人\n\n847\n00:54:58.777 --> 00:55:04.412 align:middle line:100%,end position:50%,middle\n我有一次搭飞机 坐在机上\n\n848\n00:55:04.412 --> 00:55:08.418 align:middle line:100%,end position:50%,middle\n机长广播说 我们会在三万五千英尺高空巡航\n\n849\n00:55:08.418 --> 00:55:11.385 align:middle line:100%,end position:50%,middle\n他放下麦克风后忘了关掉\n\n850\n00:55:11.385 --> 00:55:13.823 align:middle line:100%,end position:50%,middle\n他转向副驾驶说\n\n851\n00:55:13.823 --> 00:55:18.528 align:middle line:100%,end position:50%,middle\n我现在最想来个口交 再喝杯咖啡\n\n852\n00:55:18.858 --> 00:55:22.944 align:middle line:100%,end position:50%,middle\n空乘人员冲去跟他说麦克风没关\n\n853\n00:55:23.053 --> 00:55:26.280 align:middle line:100%,end position:50%,middle\n机尾有个人说“别忘了带上咖啡”\n\n854\n00:55:26.320 --> 00:55:29.867 align:middle line:100%,end position:50%,middle\n你搭过飞机？\n\n855\n00:55:30.326 --> 00:55:31.685 align:middle line:100%,end position:50%,middle\n没有 那只是个笑话\n\n856\n00:55:31.825 --> 00:55:33.343 align:middle line:100%,end position:50%,middle\n用第一人称比较好笑\n\n857\n00:55:33.453 --> 00:55:34.682 align:middle line:100%,end position:50%,middle\n没错\n\n858\n00:55:38.079 --> 00:55:40.286 align:middle line:100%,end position:50%,middle\n我做过爱\n\n859\n00:55:40.526 --> 00:55:42.584 align:middle line:100%,end position:50%,middle\n真的？ 很好\n\n860\n00:55:42.694 --> 00:55:44.682 align:middle line:100%,end position:50%,middle\n我很厉害\n\n861\n00:55:44.792 --> 00:55:45.411 align:middle line:100%,end position:50%,middle\n很厉害？\n\n862\n00:55:45.521 --> 00:55:47.579 align:middle line:100%,end position:50%,middle\n对 我上礼拜有约会\n\n863\n00:55:47.579 --> 00:55:48.888 align:middle line:100%,end position:50%,middle\n怎么样？\n\n864\n00:55:48.888 --> 00:55:49.917 align:middle line:100%,end position:50%,middle\n很好\n\n865\n00:55:50.986 --> 00:55:52.085 align:middle line:100%,end position:50%,middle\n要再约会吗？\n\n866\n00:55:52.425 --> 00:55:53.044 align:middle line:100%,end position:50%,middle\n不知道\n\n867\n00:55:53.154 --> 00:55:53.783 align:middle line:100%,end position:50%,middle\n为什么？\n\n868\n00:55:54.023 --> 00:55:55.012 align:middle line:100%,end position:50%,middle\n我没打给她\n\n869\n00:55:55.122 --> 00:55:56.491 align:middle line:100%,end position:50%,middle\n天哪 你真是个外行\n\n870\n00:55:56.590 --> 00:55:58.149 align:middle line:100%,end position:50%,middle\n- 我知道我在干嘛\n- 真的吗？\n\n871\n00:55:58.259 --> 00:56:01.915 align:middle line:100%,end position:50%,middle\n放心 我知道我在干嘛\n\n872\n00:56:02.555 --> 00:56:07.789 align:middle line:100%,end position:50%,middle\n这女孩很漂亮 聪明风趣\n\n873\n00:56:07.789 --> 00:56:09.158 align:middle line:100%,end position:50%,middle\n她跟我以前认识的女生不一样\n\n874\n00:56:09.158 --> 00:56:11.586 align:middle line:100%,end position:50%,middle\n那就打给她 罗密欧\n\n875\n00:56:11.586 --> 00:56:13.074 align:middle line:100%,end position:50%,middle\n让自己发现她没那么聪明吗？\n\n876\n00:56:13.074 --> 00:56:14.623 align:middle line:100%,end position:50%,middle\n发现她其实很无聊吗？\n\n877\n00:56:14.623 --> 00:56:17.790 align:middle line:100%,end position:50%,middle\n这女孩现在很完美\n\n878\n00:56:17.790 --> 00:56:19.028 align:middle line:100%,end position:50%,middle\n我不想破坏\n\n879\n00:56:19.028 --> 00:56:22.905 align:middle line:100%,end position:50%,middle\n或许是你不想破坏你自己的完美\n\n880\n00:56:25.022 --> 00:56:26.991 align:middle line:100%,end position:50%,middle\n我觉得那是极好的哲学\n\n881\n00:56:26.991 --> 00:56:32.865 align:middle line:100%,end position:50%,middle\n这样可以一辈子不认识任何人\n\n882\n00:56:35.522 --> 00:56:37.161 align:middle line:100%,end position:50%,middle\n我太太一紧张就放屁\n\n883\n00:56:37.161 --> 00:56:40.158 align:middle line:100%,end position:50%,middle\n她有各种奇妙的小特质\n\n884\n00:56:40.158 --> 00:56:42.345 align:middle line:100%,end position:50%,middle\n你知道 她睡觉会放屁\n\n885\n00:56:42.955 --> 00:56:45.822 align:middle line:100%,end position:50%,middle\n就是想跟你分享一下\n\n886\n00:56:45.822 --> 00:56:48.531 align:middle line:100%,end position:50%,middle\n有天晚上大声到把狗吵醒\n\n887\n00:56:52.700 --> 00:56:54.999 align:middle line:100%,end position:50%,middle\n她醒来说 “是你吗？” 我说 “是”\n\n888\n00:56:54.999 --> 00:56:57.628 align:middle line:100%,end position:50%,middle\n我不忍心告诉她 天哪\n\n889\n00:56:57.728 --> 00:56:59.217 align:middle line:100%,end position:50%,middle\n她把自己吵醒了？\n\n890\n00:56:59.337 --> 00:57:00.557 align:middle line:100%,end position:50%,middle\n是的\n\n891\n00:57:04.925 --> 00:57:09.344 align:middle line:100%,end position:50%,middle\n天哪 可是威尔 她已经去世两年了\n\n892\n00:57:09.344 --> 00:57:10.134 align:middle line:100%,end position:50%,middle\n而那是我记得的事\n\n893\n00:57:10.134 --> 00:57:13.423 align:middle line:100%,end position:50%,middle\n像那样的小事很奇妙\n\n894\n00:57:13.423 --> 00:57:17.431 align:middle line:100%,end position:50%,middle\n那是我最想念的事\n\n895\n00:57:17.431 --> 00:57:23.059 align:middle line:100%,end position:50%,middle\n只有我知道的这些小怪癖\n正是它们让她成为我的妻子\n\n896\n00:57:23.139 --> 00:57:26.518 align:middle line:100%,end position:50%,middle\n她也摸透了我 知道我所有的小怪癖\n\n897\n00:57:26.518 --> 00:57:30.417 align:middle line:100%,end position:50%,middle\n人们称之为不完美\n\n898\n00:57:30.417 --> 00:57:33.856 align:middle line:100%,end position:50%,middle\n其实不然 那才是好东西\n\n899\n00:57:34.025 --> 00:57:37.044 align:middle line:100%,end position:50%,middle\n能选择让谁进入我们的世界\n\n900\n00:57:38.654 --> 00:57:40.653 align:middle line:100%,end position:50%,middle\n你并不完美 老弟\n\n901\n00:57:40.653 --> 00:57:43.322 align:middle line:100%,end position:50%,middle\n我不吊你胃口\n\n902\n00:57:43.362 --> 00:57:46.891 align:middle line:100%,end position:50%,middle\n你认识的女生也不完美\n\n903\n00:57:47.061 --> 00:57:49.790 align:middle line:100%,end position:50%,middle\n问题是你们是否是彼此的完美伴侣\n\n904\n00:57:50.900 --> 00:57:53.769 align:middle line:100%,end position:50%,middle\n亲密关系就是这么回事\n\n905\n00:57:55.438 --> 00:57:57.128 align:middle line:100%,end position:50%,middle\n你可以知道全世界的事 老弟\n\n906\n00:57:57.308 --> 00:57:59.797 align:middle line:100%,end position:50%,middle\n想知道这一点，唯一办法就是试试\n\n907\n00:58:00.476 --> 00:58:02.736 align:middle line:100%,end position:50%,middle\n你肯定没法从我这个老混蛋这儿\n学到这一点\n\n908\n00:58:03.305 --> 00:58:05.675 align:middle line:100%,end position:50%,middle\n就算我知道 也不会告诉你这种小混蛋\n\n909\n00:58:06.754 --> 00:58:08.714 align:middle line:100%,end position:50%,middle\n为什么？\n\n910\n00:58:09.283 --> 00:58:12.302 align:middle line:100%,end position:50%,middle\n你其他事都告诉我了 天哪\n\n911\n00:58:13.012 --> 00:58:15.481 align:middle line:100%,end position:50%,middle\n你的话比任何心理医生都多\n\n912\n00:58:15.621 --> 00:58:17.481 align:middle line:100%,end position:50%,middle\n我教的是这玩意儿 可我没说过我会做\n\n913\n00:58:24.558 --> 00:58:27.347 align:middle line:100%,end position:50%,middle\n那么 你想过再婚吗？\n\n914\n00:58:27.347 --> 00:58:29.896 align:middle line:100%,end position:50%,middle\n我太太死了\n\n915\n00:58:30.326 --> 00:58:32.256 align:middle line:100%,end position:50%,middle\n所以才叫“再婚”\n\n916\n00:58:32.425 --> 00:58:33.455 align:middle line:100%,end position:50%,middle\n她死了\n\n917\n00:58:35.734 --> 00:58:39.063 align:middle line:100%,end position:50%,middle\n我想那是极好的哲学\n\n918\n00:58:39.063 --> 00:58:43.942 align:middle line:100%,end position:50%,middle\n这样可以一辈子不认识任何人\n\n919\n00:58:46.771 --> 00:58:47.930 align:middle line:100%,end position:50%,middle\n时间到了\n\n920\n00:59:03.385 --> 00:59:04.275 align:middle line:100%,end position:50%,middle\n别关\n\n921\n00:59:05.314 --> 00:59:06.114 align:middle line:100%,end position:50%,middle\n谢谢\n\n922\n00:59:19.977 --> 00:59:23.856 align:middle line:100%,end position:50%,middle\n<i>和你在一起，我很快乐</i>\n\n923\n00:59:23.939 --> 00:59:27.943 align:middle line:100%,end position:50%,middle\n<i>我知道自己就要爱上你</i>\n\n924\n00:59:28.026 --> 00:59:30.279 align:middle line:100%,end position:50%,middle\n是的\n\n925\n00:59:31.530 --> 00:59:34.741 align:middle line:100%,end position:50%,middle\n<i>我会爱他一辈子</i>\n\n926\n00:59:36.618 --> 00:59:38.704 align:middle line:100%,end position:50%,middle\nG小七和弦\n所有和弦中最悲伤的\n\n927\n00:59:41.373 --> 00:59:42.457 align:middle line:100%,end position:50%,middle\n- 你好\n- 你好\n\n928\n00:59:43.292 --> 00:59:48.463 align:middle line:100%,end position:50%,middle\n- 你去哪儿了？\n- 对不起，我…最近实在太忙了\n\n929\n00:59:48.547 --> 00:59:49.840 align:middle line:100%,end position:50%,middle\n我也是\n\n930\n00:59:50.424 --> 00:59:54.428 align:middle line:100%,end position:50%,middle\n嗯，我…我以为你会打来\n\n931\n00:59:56.587 --> 00:59:57.606 align:middle line:100%,end position:50%,middle\n我是说\n\n932\n00:59:58.486 --> 00:59:59.716 align:middle line:100%,end position:50%,middle\n- 我们相处愉快\n- 的确如此\n\n933\n00:59:59.856 --> 01:00:04.584 align:middle line:100%,end position:50%,middle\n对不起我搞砸了\n\n934\n01:00:04.754 --> 01:00:06.833 align:middle line:100%,end position:50%,middle\n不 没关系\n\n935\n01:00:06.833 --> 01:00:12.391 align:middle line:100%,end position:50%,middle\n你会不会再让我试一遍\n\n936\n01:00:12.491 --> 01:00:14.251 align:middle line:100%,end position:50%,middle\n让我再约你出去\n\n937\n01:00:14.790 --> 01:00:15.890 align:middle line:100%,end position:50%,middle\n不行\n\n938\n01:00:17.230 --> 01:00:17.789 align:middle line:100%,end position:50%,middle\n好吧\n\n939\n01:00:17.899 --> 01:00:21.198 align:middle line:100%,end position:50%,middle\n不 我不是说永远都不行\n\n940\n01:00:21.298 --> 01:00:23.128 align:middle line:100%,end position:50%,middle\n现在不行\n\n941\n01:00:23.298 --> 01:00:26.236 align:middle line:100%,end position:50%,middle\n我得给埃博加明的质子谱做归属\n\n942\n01:00:26.466 --> 01:00:29.995 align:middle line:100%,end position:50%,middle\n听起来有趣 其实很无聊\n\n943\n01:00:30.095 --> 01:00:33.204 align:middle line:100%,end position:50%,middle\n- 好吧\n- 或许改天吧\n\n944\n01:00:33.304 --> 01:00:34.464 align:middle line:100%,end position:50%,middle\n那明天呢？\n\n945\n01:00:35.743 --> 01:00:36.903 align:middle line:100%,end position:50%,middle\n好啊\n\n946\n01:00:37.073 --> 01:00:38.722 align:middle line:100%,end position:50%,middle\n- 好的\n- 好的\n\n947\n01:00:38.822 --> 01:00:42.021 align:middle line:100%,end position:50%,middle\n- 再见\n- 再见\n\n948\n01:00:53.697 --> 01:00:56.916 align:middle line:100%,end position:50%,middle\n你在这儿干嘛？\n\n949\n01:00:57.126 --> 01:00:58.655 align:middle line:100%,end position:50%,middle\n我等不到明天了\n\n950\n01:00:58.655 --> 01:01:01.704 align:middle line:100%,end position:50%,middle\n你从哪儿弄到这个？\n\n951\n01:01:01.704 --> 01:01:03.924 align:middle line:100%,end position:50%,middle\n我只好跟你班上的一个人上床\n\n952\n01:01:04.024 --> 01:01:08.362 align:middle line:100%,end position:50%,middle\n希望是那个穿凉鞋、口臭很重的人\n\n953\n01:01:09.962 --> 01:01:11.191 align:middle line:100%,end position:50%,middle\n走 去找乐子\n\n954\n01:01:11.331 --> 01:01:13.630 align:middle line:100%,end position:50%,middle\n不行 我得学会这个\n\n955\n01:01:13.930 --> 01:01:16.459 align:middle line:100%,end position:50%,middle\n你不会明天就要开刀吧？\n\n956\n01:01:16.669 --> 01:01:17.599 align:middle line:100%,end position:50%,middle\n不是\n\n957\n01:01:17.739 --> 01:01:18.379 align:middle line:100%,end position:50%,middle\n走吧\n\n958\n01:01:22.427 --> 01:01:25.886 align:middle line:100%,end position:50%,middle\n我的天！我的狗赢了！\n\n959\n01:01:25.906 --> 01:01:29.945 align:middle line:100%,end position:50%,middle\n加油 米丝蒂！快跑 快看！加油！\n\n960\n01:01:29.945 --> 01:01:33.603 align:middle line:100%,end position:50%,middle\n看，它跑起来了！米丝蒂，快跑！加油！\n\n961\n01:01:35.433 --> 01:01:38.412 align:middle line:100%,end position:50%,middle\n我们赢了\n\n962\n01:01:38.412 --> 01:01:40.041 align:middle line:100%,end position:50%,middle\n它大获全胜\n\n963\n01:01:41.521 --> 01:01:43.980 align:middle line:100%,end position:50%,middle\n你在这边长大的吗？\n\n964\n01:01:44.090 --> 01:01:45.639 align:middle line:100%,end position:50%,middle\n不远 南波士顿\n\n965\n01:01:49.028 --> 01:01:50.558 align:middle line:100%,end position:50%,middle\n我还沉浸在赢了的喜悦里\n\n966\n01:01:50.698 --> 01:01:52.997 align:middle line:100%,end position:50%,middle\n看你乐成这样\n\n967\n01:01:54.316 --> 01:01:56.486 align:middle line:100%,end position:50%,middle\n那感觉怎么样？\n\n968\n01:01:56.486 --> 01:02:00.194 align:middle line:100%,end position:50%,middle\n很正常 没什么特别\n\n969\n01:02:00.194 --> 01:02:03.453 align:middle line:100%,end position:50%,middle\n你有很多兄弟姐妹吗？\n\n970\n01:02:03.453 --> 01:02:06.812 align:middle line:100%,end position:50%,middle\n- 我有很多兄弟姐妹吗？\n- 我就是这么问的\n\n971\n01:02:07.212 --> 01:02:08.701 align:middle line:100%,end position:50%,middle\n爱尔兰裔天主教徒 你说呢？\n\n972\n01:02:09.041 --> 01:02:14.379 align:middle line:100%,end position:50%,middle\n对 几个？\n\n973\n01:02:14.379 --> 01:02:16.179 align:middle line:100%,end position:50%,middle\n告诉你你也不信\n\n974\n01:02:17.418 --> 01:02:21.007 align:middle line:100%,end position:50%,middle\n为什么？ 说啊 五个？\n\n975\n01:02:21.357 --> 01:02:24.386 align:middle line:100%,end position:50%,middle\n七个？ 八个？ 几个？\n\n976\n01:02:24.386 --> 01:02:26.225 align:middle line:100%,end position:50%,middle\n我有十二个哥哥\n\n977\n01:02:26.225 --> 01:02:27.555 align:middle line:100%,end position:50%,middle\n你才没有！\n\n978\n01:02:27.655 --> 01:02:29.554 align:middle line:100%,end position:50%,middle\n不，我发誓！我就是幸运的第13个\n\n979\n01:02:29.554 --> 01:02:31.594 align:middle line:100%,end position:50%,middle\n你知道他们的名字吗？\n\n980\n01:02:31.594 --> 01:02:34.223 align:middle line:100%,end position:50%,middle\n当然知道 他们是我哥哥\n\n981\n01:02:34.223 --> 01:02:36.392 align:middle line:100%,end position:50%,middle\n叫什么名字？\n\n982\n01:02:36.392 --> 01:02:38.161 align:middle line:100%,end position:50%,middle\n马奇 瑞奇 丹尼 泰瑞\n\n983\n01:02:38.161 --> 01:02:39.391 align:middle line:100%,end position:50%,middle\n麦奇 大卫 提米 汤米\n\n984\n01:02:39.501 --> 01:02:40.850 align:middle line:100%,end position:50%,middle\n乔伊、罗比、约翰尼和布莱恩\n\n985\n01:02:40.850 --> 01:02:43.040 align:middle line:100%,end position:50%,middle\n再说一遍\n\n986\n01:02:43.040 --> 01:02:44.529 align:middle line:100%,end position:50%,middle\n马奇 瑞奇 丹尼 泰瑞\n\n987\n01:02:44.639 --> 01:02:45.899 align:middle line:100%,end position:50%,middle\n麦奇 大卫 提米 汤米\n\n988\n01:02:46.009 --> 01:02:47.478 align:middle line:100%,end position:50%,middle\n乔伊、罗比、约翰尼和布莱恩\n\n989\n01:02:47.478 --> 01:02:50.597 align:middle line:100%,end position:50%,middle\n还有小威\n\n990\n01:02:50.707 --> 01:02:51.197 align:middle line:100%,end position:50%,middle\n小威？\n\n991\n01:02:51.307 --> 01:02:52.706 align:middle line:100%,end position:50%,middle\n威尔\n\n992\n01:02:53.106 --> 01:02:56.045 align:middle line:100%,end position:50%,middle\n你常和他们见面吗？\n\n993\n01:02:56.045 --> 01:02:57.025 align:middle line:100%,end position:50%,middle\n他们都住南区\n\n994\n01:02:57.025 --> 01:02:59.074 align:middle line:100%,end position:50%,middle\n我跟其中三个住\n\n995\n01:02:59.074 --> 01:02:59.694 align:middle line:100%,end position:50%,middle\n是吗？\n\n996\n01:02:59.694 --> 01:03:00.684 align:middle line:100%,end position:50%,middle\n我好想见他们\n\n997\n01:03:01.243 --> 01:03:03.773 align:middle line:100%,end position:50%,middle\n好 就去见他们\n\n998\n01:03:03.823 --> 01:03:06.242 align:middle line:100%,end position:50%,middle\n我昨晚读过你的书\n\n999\n01:03:06.242 --> 01:03:08.831 align:middle line:100%,end position:50%,middle\n原来是你\n\n1000\n01:03:09.391 --> 01:03:10.950 align:middle line:100%,end position:50%,middle\n你还为退伍军人做心理咨询吗？\n\n1001\n01:03:10.950 --> 01:03:12.550 align:middle line:100%,end position:50%,middle\n没有\n\n1002\n01:03:12.659 --> 01:03:13.179 align:middle line:100%,end position:50%,middle\n为什么？\n\n1003\n01:03:13.289 --> 01:03:15.279 align:middle line:100%,end position:50%,middle\n我太太生病时就没做了\n\n1004\n01:03:17.038 --> 01:03:19.497 align:middle line:100%,end position:50%,middle\n你有没有想过若没遇见你太太\n\n1005\n01:03:19.497 --> 01:03:22.486 align:middle line:100%,end position:50%,middle\n你的生活会怎样？\n\n1006\n01:03:22.626 --> 01:03:24.675 align:middle line:100%,end position:50%,middle\n什么？你是问我没了她会不会更好？\n\n1007\n01:03:24.675 --> 01:03:26.995 align:middle line:100%,end position:50%,middle\n不 我没说比较好\n\n1008\n01:03:27.095 --> 01:03:28.024 align:middle line:100%,end position:50%,middle\n我没那意思\n\n1009\n01:03:28.134 --> 01:03:29.994 align:middle line:100%,end position:50%,middle\n没关系 很重要的问题\n\n1010\n01:03:31.333 --> 01:03:33.262 align:middle line:100%,end position:50%,middle\n因为你也会遇上不顺的时候\n\n1011\n01:03:33.262 --> 01:03:35.642 align:middle line:100%,end position:50%,middle\n但这会让你重新看见那些原本没留意到的美好\n\n1012\n01:03:35.642 --> 01:03:38.261 align:middle line:100%,end position:50%,middle\n你不后悔认识你太太吗？\n\n1013\n01:03:38.261 --> 01:03:40.970 align:middle line:100%,end position:50%,middle\n因为我现在的痛苦？\n\n1014\n01:03:41.510 --> 01:03:42.669 align:middle line:100%,end position:50%,middle\n有 我也有遗憾 威尔\n\n1015\n01:03:42.779 --> 01:03:45.838 align:middle line:100%,end position:50%,middle\n但我不后悔跟她共度的每一天\n\n1016\n01:03:50.227 --> 01:03:53.685 align:middle line:100%,end position:50%,middle\n你几时知道她是理想对象？\n\n1017\n01:03:53.685 --> 01:03:56.405 align:middle line:100%,end position:50%,middle\n1975年10月21日\n\n1018\n01:03:56.405 --> 01:03:58.654 align:middle line:100%,end position:50%,middle\n天哪 你他妈的记得日期？\n\n1019\n01:03:58.922 --> 01:04:03.760 align:middle line:100%,end position:50%,middle\n对，那是世界大赛第六场\n红袜队史上最重要的一场\n\n1020\n01:04:03.844 --> 01:04:08.849 align:middle line:100%,end position:50%,middle\n- 没错\n- 我和朋友露宿街头一整夜买票\n\n1021\n01:04:08.910 --> 01:04:10.390 align:middle line:100%,end position:50%,middle\n你有票？\n\n1022\n01:04:10.390 --> 01:04:11.649 align:middle line:100%,end position:50%,middle\n对 比赛当天\n\n1023\n01:04:11.759 --> 01:04:13.998 align:middle line:100%,end position:50%,middle\n我们坐在酒吧等球赛开始\n\n1024\n01:04:13.998 --> 01:04:16.038 align:middle line:100%,end position:50%,middle\n有个女孩走进来…\n\n1025\n01:04:16.038 --> 01:04:17.967 align:middle line:100%,end position:50%,middle\n那是场很棒的球赛\n\n1026\n01:04:17.967 --> 01:04:19.457 align:middle line:100%,end position:50%,middle\n八局下半 卡波把比分追平\n\n1027\n01:04:19.457 --> 01:04:20.916 align:middle line:100%,end position:50%,middle\n六比六平手\n\n1028\n01:04:20.916 --> 01:04:21.586 align:middle line:100%,end position:50%,middle\n打到第12局下半局\n\n1029\n01:04:21.586 --> 01:04:25.585 align:middle line:100%,end position:50%,middle\n“矮冬瓜”卡尔顿·菲斯克上场\n\n1030\n01:04:25.585 --> 01:04:27.674 align:middle line:100%,end position:50%,middle\n他站上本垒 姿势很怪\n\n1031\n01:04:27.674 --> 01:04:31.423 align:middle line:100%,end position:50%,middle\n打击出去！\n\n1032\n01:04:31.423 --> 01:04:34.052 align:middle line:100%,end position:50%,middle\n左外野高飞球！\n\n1033\n01:04:34.292 --> 01:04:36.801 align:middle line:100%,end position:50%,middle\n三万五千人站起来对球吼\n\n1034\n01:04:36.801 --> 01:04:39.350 align:middle line:100%,end position:50%,middle\n菲斯克像发了疯似地挥手说\n\n1035\n01:04:39.350 --> 01:04:42.769 align:middle line:100%,end position:50%,middle\n“飞过去！ 飞过去！ 飞过去！”\n\n1036\n01:04:42.929 --> 01:04:45.898 align:middle line:100%,end position:50%,middle\n接着球击中了界外杆 菲斯克高兴疯了\n\n1037\n01:04:45.898 --> 01:04:49.536 align:middle line:100%,end position:50%,middle\n三万五千名球迷冲到场上\n\n1038\n01:04:49.536 --> 01:04:54.045 align:middle line:100%,end position:50%,middle\n他他妈一路推开人群 大喊“让开！让开！”\n\n1039\n01:04:54.045 --> 01:04:56.504 align:middle line:100%,end position:50%,middle\n我真不敢相信你有票！\n\n1040\n01:04:56.674 --> 01:04:57.773 align:middle line:100%,end position:50%,middle\n你有冲到场上吗？\n\n1041\n01:04:57.773 --> 01:04:59.713 align:middle line:100%,end position:50%,middle\n我没冲到场上 我不在场\n\n1042\n01:05:00.013 --> 01:05:01.372 align:middle line:100%,end position:50%,middle\n什么？\n\n1043\n01:05:01.512 --> 01:05:03.841 align:middle line:100%,end position:50%,middle\n我跟我未来的老婆在喝酒\n\n1044\n01:05:03.951 --> 01:05:05.611 align:middle line:100%,end position:50%,middle\n你错过菲斯克的<i>本垒打</i>？\n\n1045\n01:05:05.751 --> 01:05:06.371 align:middle line:100%,end position:50%,middle\n对\n\n1046\n01:05:06.480 --> 01:05:08.180 align:middle line:100%,end position:50%,middle\n跟一个不认识的女人喝酒？\n\n1047\n01:05:08.280 --> 01:05:10.679 align:middle line:100%,end position:50%,middle\n对 你该看看她 令人惊艳\n\n1048\n01:05:10.819 --> 01:05:11.809 align:middle line:100%,end position:50%,middle\n我才不管他妈的…\n\n1049\n01:05:11.919 --> 01:05:13.078 align:middle line:100%,end position:50%,middle\n她让整个屋子亮起来\n\n1050\n01:05:13.188 --> 01:05:15.587 align:middle line:100%,end position:50%,middle\n- 哪怕特洛伊的海伦来，我也不在乎\n- 哦，特洛伊的海伦！\n\n1051\n01:05:15.687 --> 01:05:19.696 align:middle line:100%,end position:50%,middle\n那可是第六场！天哪 你的那些朋友呢？\n\n1052\n01:05:19.696 --> 01:05:20.956 align:middle line:100%,end position:50%,middle\n- 就这么放过你？\n- 他们没办法\n\n1053\n01:05:21.056 --> 01:05:22.525 align:middle line:100%,end position:50%,middle\n你跟他们怎么说？\n\n1054\n01:05:22.795 --> 01:05:24.414 align:middle line:100%,end position:50%,middle\n我把票滑过去说\n\n1055\n01:05:24.414 --> 01:05:27.503 align:middle line:100%,end position:50%,middle\n抱歉 我要去找一个女孩\n\n1056\n01:05:27.623 --> 01:05:29.753 align:middle line:100%,end position:50%,middle\n- 我要去找一个女孩？\n- 对！\n\n1057\n01:05:29.763 --> 01:05:30.662 align:middle line:100%,end position:50%,middle\n你那么说？\n\n1058\n01:05:31.402 --> 01:05:32.362 align:middle line:100%,end position:50%,middle\n他们就放过你了？\n\n1059\n01:05:32.532 --> 01:05:34.091 align:middle line:100%,end position:50%,middle\n对 他们看得出我是认真的\n\n1060\n01:05:34.091 --> 01:05:36.200 align:middle line:100%,end position:50%,middle\n你耍我吧？\n\n1061\n01:05:36.200 --> 01:05:37.930 align:middle line:100%,end position:50%,middle\n我没耍你\n\n1062\n01:05:37.930 --> 01:05:40.839 align:middle line:100%,end position:50%,middle\n所以我现在不会念叨\n20年前在酒吧看见的一个女孩\n\n1063\n01:05:40.939 --> 01:05:43.178 align:middle line:100%,end position:50%,middle\n一直后悔当年没过去和她说话\n\n1064\n01:05:43.178 --> 01:05:46.427 align:middle line:100%,end position:50%,middle\n我不后悔跟南茜结婚的18年\n\n1065\n01:05:46.427 --> 01:05:49.636 align:middle line:100%,end position:50%,middle\n不后悔在她生病后那六年放弃心理咨询\n\n1066\n01:05:49.746 --> 01:05:52.405 align:middle line:100%,end position:50%,middle\n不后悔那最后几年守着重病的她\n\n1067\n01:05:53.354 --> 01:05:56.064 align:middle line:100%,end position:50%,middle\n更不会后悔错过球赛\n\n1068\n01:05:56.064 --> 01:05:58.773 align:middle line:100%,end position:50%,middle\n只是有点遗憾\n\n1069\n01:06:06.150 --> 01:06:08.909 align:middle line:100%,end position:50%,middle\n看到那场球赛还是不错的\n\n1070\n01:06:08.909 --> 01:06:11.488 align:middle line:100%,end position:50%,middle\n我不晓得矮冬瓜会打出<i>本垒打</i>\n\n1071\n01:06:13.528 --> 01:06:20.705 align:middle line:100%,end position:50%,middle\n我在球场上很有用 我很高\n\n1072\n01:06:21.195 --> 01:06:22.325 align:middle line:100%,end position:50%,middle\n你没那么高\n\n1073\n01:06:22.434 --> 01:06:23.334 align:middle line:100%,end position:50%,middle\n我会扣篮\n\n1074\n01:06:25.204 --> 01:06:29.872 align:middle line:100%,end position:50%,middle\n我能打NBA吗？\n\n1075\n01:06:30.142 --> 01:06:32.261 align:middle line:100%,end position:50%,middle\n“答案相当肯定。”哼\n\n1076\n01:06:36.140 --> 01:06:38.129 align:middle line:100%,end position:50%,middle\n为什么老是待在这边？\n\n1077\n01:06:38.589 --> 01:06:41.468 align:middle line:100%,end position:50%,middle\n因为比我家好\n\n1078\n01:06:41.578 --> 01:06:43.707 align:middle line:100%,end position:50%,middle\n但我从没去过你家\n\n1079\n01:06:43.977 --> 01:06:45.277 align:middle line:100%,end position:50%,middle\n我知道\n\n1080\n01:06:46.316 --> 01:06:48.675 align:middle line:100%,end position:50%,middle\n我什么时候能见到你朋友和哥哥？\n\n1081\n01:06:48.675 --> 01:06:52.144 align:middle line:100%,end position:50%,middle\n他们不常来这里\n\n1082\n01:06:52.414 --> 01:06:54.434 align:middle line:100%,end position:50%,middle\n我可以到南波士顿\n\n1083\n01:06:54.434 --> 01:06:58.652 align:middle line:100%,end position:50%,middle\n有点远\n\n1084\n01:06:58.652 --> 01:07:02.151 align:middle line:100%,end position:50%,middle\n你是在向他们隐瞒我\n还是在向我隐瞒他们？\n\n1085\n01:07:02.521 --> 01:07:03.820 align:middle line:100%,end position:50%,middle\n好 我们去\n\n1086\n01:07:03.990 --> 01:07:04.820 align:middle line:100%,end position:50%,middle\n几时？\n\n1087\n01:07:04.820 --> 01:07:07.279 align:middle line:100%,end position:50%,middle\n不知道 下周吧\n\n1088\n01:07:07.279 --> 01:07:13.557 align:middle line:100%,end position:50%,middle\n如果我说在见到你朋友前 不再跟你上床呢？\n\n1089\n01:07:18.605 --> 01:07:21.734 align:middle line:100%,end position:50%,middle\n清晨四点半 他们应该醒了\n\n1090\n01:07:22.164 --> 01:07:25.493 align:middle line:100%,end position:50%,middle\n天哪 男人真无耻\n\n1091\n01:07:25.493 --> 01:07:29.512 align:middle line:100%,end position:50%,middle\n你们男人要是不听小弟弟指挥 就会替它办事\n\n1092\n01:07:29.512 --> 01:07:33.470 align:middle line:100%,end position:50%,middle\n当然 我代表我的小弟弟 向你预支一下？\n\n1093\n01:07:33.580 --> 01:07:35.569 align:middle line:100%,end position:50%,middle\n不知道 我问问\n\n1094\n01:07:36.749 --> 01:07:38.149 align:middle line:100%,end position:50%,middle\n前景不妙\n\n1095\n01:07:38.249 --> 01:07:39.218 align:middle line:100%,end position:50%,middle\n<i>- 什么？</i>\n- 干！\n\n1096\n01:07:39.318 --> 01:07:40.908 align:middle line:100%,end position:50%,middle\n查克 没事 继续睡\n\n1097\n01:07:41.018 --> 01:07:45.096 align:middle line:100%,end position:50%,middle\n“前景”？上次它还告诉你能打NBA呢\n\n1098\n01:07:45.096 --> 01:07:49.175 align:middle line:100%,end position:50%,middle\n没错 所以你最好开始买季票\n\n1099\n01:07:49.225 --> 01:07:54.103 align:middle line:100%,end position:50%,middle\n我正打算买 我很高 我喜欢穿短裤\n\n1100\n01:07:54.103 --> 01:07:56.562 align:middle line:100%,end position:50%,middle\n勾手投篮 勾手投篮 扣篮 扣篮\n\n1101\n01:07:56.732 --> 01:07:57.782 align:middle line:100%,end position:50%,middle\n你没那么高\n\n1102\n01:07:57.962 --> 01:08:02.310 align:middle line:100%,end position:50%,middle\n我确实高 也许我擅长投三分球\n\n1103\n01:08:02.700 --> 01:08:03.960 align:middle line:100%,end position:50%,middle\n我就很会打“<i>本垒打</i>”\n\n1104\n01:08:04.689 --> 01:08:08.898 align:middle line:100%,end position:50%,middle\n别把不同运动的比喻混在一起\n\n1105\n01:08:10.174 --> 01:08:11.383 align:middle line:100%,end position:50%,middle\n我的肾！\n\n1106\n01:08:20.494 --> 01:08:23.843 align:middle line:100%,end position:50%,middle\n妖精的老二在猴子屁眼里\n\n1107\n01:08:23.843 --> 01:08:27.442 align:middle line:100%,end position:50%,middle\n摩根跑出来说 我不介意 我不介意\n\n1108\n01:08:30.151 --> 01:08:33.809 align:middle line:100%,end position:50%,middle\n干 你竟挑我们烂醉时带她来\n\n1109\n01:08:33.919 --> 01:08:36.149 align:middle line:100%,end position:50%,middle\n我们很难得一起喝酒\n\n1110\n01:08:36.259 --> 01:08:40.007 align:middle line:100%,end position:50%,middle\n我叔叔马帝一喝酒就会连醉六到八个月\n\n1111\n01:08:40.007 --> 01:08:42.746 align:middle line:100%,end position:50%,middle\n我讲过他开车被拦下的事没？\n\n1112\n01:08:42.776 --> 01:08:45.216 align:middle line:100%,end position:50%,middle\n我跟你们讲\n\n1113\n01:08:45.216 --> 01:08:47.725 align:middle line:100%,end position:50%,middle\n你们应该知道\n\n1114\n01:08:47.725 --> 01:08:51.194 align:middle line:100%,end position:50%,middle\n我们每次来这儿 他总会再讲一个故事\n\n1115\n01:08:51.194 --> 01:08:53.003 align:middle line:100%,end position:50%,middle\n这个我们早就听过了\n\n1116\n01:08:53.003 --> 01:08:55.262 align:middle line:100%,end position:50%,middle\n还是说吧 快讲\n\n1117\n01:08:56.732 --> 01:09:00.360 align:middle line:100%,end position:50%,middle\n我会讲 多谢 换我发言\n\n1118\n01:09:02.040 --> 01:09:04.439 align:middle line:100%,end position:50%,middle\n我叔叔开车回家\n\n1119\n01:09:04.439 --> 01:09:06.238 align:middle line:100%,end position:50%,middle\n他当时醉得神志不清\n\n1120\n01:09:06.238 --> 01:09:09.187 align:middle line:100%,end position:50%,middle\n他醉得一塌糊涂\n\n1121\n01:09:09.187 --> 01:09:13.646 align:middle line:100%,end position:50%,middle\n州警把他拦下 我叔叔这下惨了\n\n1122\n01:09:13.746 --> 01:09:15.675 align:middle line:100%,end position:50%,middle\n州警要他下车走直线\n\n1123\n01:09:15.775 --> 01:09:17.744 align:middle line:100%,end position:50%,middle\n他一下车就吐了\n\n1124\n01:09:17.844 --> 01:09:19.644 align:middle line:100%,end position:50%,middle\n州警确信他的血液酒精浓度超标\n\n1125\n01:09:19.984 --> 01:09:23.612 align:middle line:100%,end position:50%,middle\n正要把他戴上手铐送去坐牢\n\n1126\n01:09:23.752 --> 01:09:27.121 align:middle line:100%,end position:50%,middle\n突然五十码外一声他妈的巨响\n\n1127\n01:09:27.751 --> 01:09:30.241 align:middle line:100%,end position:50%,middle\n州警吓一大跳 转身\n\n1128\n01:09:30.491 --> 01:09:31.220 align:middle line:100%,end position:50%,middle\n他中枪了？\n\n1129\n01:09:31.690 --> 01:09:33.620 align:middle line:100%,end position:50%,middle\n不 是…\n\n1130\n01:09:33.730 --> 01:09:34.250 align:middle line:100%,end position:50%,middle\n你听过这故事了\n\n1131\n01:09:34.250 --> 01:09:36.170 align:middle line:100%,end position:50%,middle\n得了 摩根\n\n1132\n01:09:36.260 --> 01:09:39.669 align:middle line:100%,end position:50%,middle\n是别人的车撞到树 出事了\n\n1133\n01:09:41.390 --> 01:09:43.015 align:middle line:100%,end position:50%,middle\n- 总之…\n- 他怎么可能听见…\n\n1134\n01:09:43.100 --> 01:09:45.685 align:middle line:100%,end position:50%,middle\n闭嘴！\n我要扭断你脖子！\n\n1135\n01:09:45.769 --> 01:09:48.856 align:middle line:100%,end position:50%,middle\n- 闭嘴\n- 他跟你说过这故事了\n\n1136\n01:09:49.108 --> 01:09:51.407 align:middle line:100%,end position:50%,middle\n州警跟我叔叔说“待在这儿 别动”\n\n1137\n01:09:51.607 --> 01:09:54.477 align:middle line:100%,end position:50%,middle\n就跑去处理另一起事故\n\n1138\n01:09:55.876 --> 01:09:59.476 align:middle line:100%,end position:50%,middle\n躺在尿和呕吐物中几分钟后\n\n1139\n01:09:59.846 --> 01:10:01.725 align:middle line:100%,end position:50%,middle\n我叔叔才想到 他在那儿干嘛\n\n1140\n01:10:01.725 --> 01:10:04.515 align:middle line:100%,end position:50%,middle\n于是站起来开车回家\n\n1141\n01:10:04.615 --> 01:10:07.455 align:middle line:100%,end position:50%,middle\n隔天早上我叔叔还昏迷不醒\n\n1142\n01:10:07.555 --> 01:10:09.684 align:middle line:100%,end position:50%,middle\n他听到敲门声\n\n1143\n01:10:09.794 --> 01:10:12.084 align:middle line:100%,end position:50%,middle\n下楼拉开门说“什么事”\n\n1144\n01:10:12.194 --> 01:10:14.783 align:middle line:100%,end position:50%,middle\n是拦下他的州警\n\n1145\n01:10:15.023 --> 01:10:17.763 align:middle line:100%,end position:50%,middle\n州警说“我操 什么事？ 你明知故问”\n\n1146\n01:10:17.763 --> 01:10:20.792 align:middle line:100%,end position:50%,middle\n“我昨晚拦下你 你逃走了”\n\n1147\n01:10:20.902 --> 01:10:23.062 align:middle line:100%,end position:50%,middle\n叔叔说“我这辈子没见过你”\n\n1148\n01:10:23.172 --> 01:10:26.132 align:middle line:100%,end position:50%,middle\n“我整晚都跟孩子在家 我根本不知道你是谁”\n\n1149\n01:10:26.271 --> 01:10:28.791 align:middle line:100%,end position:50%,middle\n州警说“你知道我是谁 让我进你车库”\n\n1150\n01:10:29.301 --> 01:10:30.361 align:middle line:100%,end position:50%,middle\n我叔叔说“什么？”\n\n1151\n01:10:30.471 --> 01:10:31.941 align:middle line:100%,end position:50%,middle\n“你听见了 让我进你的车库”\n\n1152\n01:10:32.041 --> 01:10:34.380 align:middle line:100%,end position:50%,middle\n我叔叔说“好吧，行”\n就带他去车库打开门\n\n1153\n01:10:34.380 --> 01:10:39.639 align:middle line:100%,end position:50%,middle\n警车就在我叔叔的车库里\n\n1154\n01:10:39.639 --> 01:10:44.878 align:middle line:100%,end position:50%,middle\n他醉到他妈的开错车回家了\n\n1155\n01:10:45.188 --> 01:10:48.648 align:middle line:100%,end position:50%,middle\n最屌的是那个州警\n\n1156\n01:10:48.648 --> 01:10:51.107 align:middle line:100%,end position:50%,middle\n他太尴尬了 什么也没做\n\n1157\n01:10:51.107 --> 01:10:54.487 align:middle line:100%,end position:50%,middle\n他整晚开着我叔叔的Chevelle\n到处找这栋房子\n\n1158\n01:10:54.487 --> 01:10:58.566 align:middle line:100%,end position:50%,middle\n你的故事重点是什么？\n\n1159\n01:10:58.796 --> 01:11:00.856 align:middle line:100%,end position:50%,middle\n他逃过一劫，这就是重点\n\n1160\n01:11:01.036 --> 01:11:02.996 align:middle line:100%,end position:50%,middle\n- 问题是…\n- 少来了！\n\n1161\n01:11:03.106 --> 01:11:03.965 align:middle line:100%,end position:50%,middle\n停下！\n\n1162\n01:11:04.065 --> 01:11:06.165 align:middle line:100%,end position:50%,middle\n- 我只是想问清楚一件事\n- 你在让他难堪\n\n1163\n01:11:06.995 --> 01:11:09.494 align:middle line:100%,end position:50%,middle\n- 这根本说不通\n- 说得通\n\n1164\n01:11:09.504 --> 01:11:11.624 align:middle line:100%,end position:50%,middle\n你听故事就别一直问问题\n\n1165\n01:11:11.624 --> 01:11:14.954 align:middle line:100%,end position:50%,middle\n摩根 看这个故事你懂不懂\n\n1166\n01:11:14.954 --> 01:11:18.943 align:middle line:100%,end position:50%,middle\n好 一对老夫妻在床上\n\n1167\n01:11:18.943 --> 01:11:19.833 align:middle line:100%,end position:50%,middle\n玛丽和帕迪\n\n1168\n01:11:19.833 --> 01:11:25.382 align:middle line:100%,end position:50%,middle\n结婚50周年那天他们醒来\n\n1169\n01:11:25.852 --> 01:11:28.821 align:middle line:100%,end position:50%,middle\n玛丽深情地望着帕迪说\n\n1170\n01:11:28.991 --> 01:11:32.721 align:middle line:100%,end position:50%,middle\n“天啊，帕迪，你真帅，我爱你”\n\n1171\n01:11:32.721 --> 01:11:35.350 align:middle line:100%,end position:50%,middle\n我要送你一件礼物\n\n1172\n01:11:35.830 --> 01:11:38.600 align:middle line:100%,end position:50%,middle\n你心里想要什么 我都会给你\n\n1173\n01:11:38.600 --> 01:11:40.619 align:middle line:100%,end position:50%,middle\n你想要什么？\n\n1174\n01:11:40.799 --> 01:11:45.329 align:middle line:100%,end position:50%,middle\n帕迪说“天啊，玛丽，你真贴心”\n\n1175\n01:11:45.539 --> 01:11:49.798 align:middle line:100%,end position:50%,middle\n这50年来一直少了一样东西\n\n1176\n01:11:50.578 --> 01:11:55.277 align:middle line:100%,end position:50%,middle\n我想请你帮我口交 就想要这个\n\n1177\n01:11:55.277 --> 01:11:57.937 align:middle line:100%,end position:50%,middle\n玛丽说好\n\n1178\n01:11:58.217 --> 01:11:59.806 align:middle line:100%,end position:50%,middle\n她把假牙拿掉\n\n1179\n01:11:59.916 --> 01:12:02.346 align:middle line:100%,end position:50%,middle\n放进杯子里 然后帮他吹\n\n1180\n01:12:02.746 --> 01:12:06.545 align:middle line:100%,end position:50%,middle\n之后帕迪说“天啊\n这就是我一直缺的”\n\n1181\n01:12:06.755 --> 01:12:10.345 align:middle line:100%,end position:50%,middle\n那真是此生最美妙、最震撼的事\n\n1182\n01:12:10.695 --> 01:12:12.094 align:middle line:100%,end position:50%,middle\n玛丽 你真美 我爱你\n\n1183\n01:12:13.094 --> 01:12:15.284 align:middle line:100%,end position:50%,middle\n我能为你做什么吗？\n\n1184\n01:12:16.124 --> 01:12:20.533 align:middle line:100%,end position:50%,middle\n玛丽抬头看他说 “亲一下”\n\n1185\n01:12:20.833 --> 01:12:22.853 align:middle line:100%,end position:50%,middle\n我的天\n\n1186\n01:12:22.933 --> 01:12:25.372 align:middle line:100%,end position:50%,middle\n真恶心\n\n1187\n01:12:25.372 --> 01:12:26.432 align:middle line:100%,end position:50%,middle\n不恶 我听过更恶心的\n\n1188\n01:12:30.731 --> 01:12:33.711 align:middle line:100%,end position:50%,middle\n滚开 操！\n\n1189\n01:12:33.711 --> 01:12:34.941 align:middle line:100%,end position:50%,middle\n好 再见\n\n1190\n01:12:35.111 --> 01:12:36.510 align:middle line:100%,end position:50%,middle\n保重 比利\n\n1191\n01:12:38.110 --> 01:12:42.739 align:middle line:100%,end position:50%,middle\n斯凯勒 谢谢你过来 你改变了我对哈佛人的看法\n\n1192\n01:12:42.849 --> 01:12:46.239 align:middle line:100%,end position:50%,middle\n别急着下定论 不是所有哈佛人都像我这样\n\n1193\n01:12:46.239 --> 01:12:49.148 align:middle line:100%,end position:50%,middle\n我相信 很高兴认识你\n\n1194\n01:12:49.258 --> 01:12:51.348 align:middle line:100%,end position:50%,middle\n小心点 慢慢往后退\n\n1195\n01:12:52.028 --> 01:12:53.258 align:middle line:100%,end position:50%,middle\n得了吧 兄弟\n\n1196\n01:12:54.257 --> 01:12:58.367 align:middle line:100%,end position:50%,middle\n我不知道你要干嘛 老兄 你这是要送我们回去\n\n1197\n01:12:58.367 --> 01:13:00.097 align:middle line:100%,end position:50%,middle\n你他妈觉得我像什么人？\n\n1198\n01:13:00.366 --> 01:13:02.136 align:middle line:100%,end position:50%,middle\n你自己走吧 混蛋 车给威尔\n\n1199\n01:13:02.136 --> 01:13:05.526 align:middle line:100%,end position:50%,middle\n好 谢了 傻瓜 我很感激\n\n1200\n01:13:05.806 --> 01:13:08.705 align:middle line:100%,end position:50%,middle\n干嘛这么正经\n\n1201\n01:13:08.805 --> 01:13:10.325 align:middle line:100%,end position:50%,middle\n你还是要先送我回家\n\n1202\n01:13:10.875 --> 01:13:12.275 align:middle line:100%,end position:50%,middle\n这样很不顺路\n\n1203\n01:13:12.744 --> 01:13:15.354 align:middle line:100%,end position:50%,middle\n就因为今晚不用睡你那间小宫殿\n\n1204\n01:13:15.354 --> 01:13:17.514 align:middle line:100%,end position:50%,middle\n别以为自己多威风\n\n1205\n01:13:17.684 --> 01:13:19.583 align:middle line:100%,end position:50%,middle\n等一下 你说要去看你家\n\n1206\n01:13:19.883 --> 01:13:20.673 align:middle line:100%,end position:50%,middle\n今晚不行\n\n1207\n01:13:20.853 --> 01:13:22.943 align:middle line:100%,end position:50%,middle\n今晚不行 哪一晚都不行\n\n1208\n01:13:22.943 --> 01:13:26.482 align:middle line:100%,end position:50%,middle\n他知道你一看到他那破地方 就会立刻把他甩了\n\n1209\n01:13:26.892 --> 01:13:28.482 align:middle line:100%,end position:50%,middle\n但我想见你哥哥\n\n1210\n01:13:28.992 --> 01:13:30.552 align:middle line:100%,end position:50%,middle\n不 改天吧\n\n1211\n01:13:31.491 --> 01:13:32.421 align:middle line:100%,end position:50%,middle\n好吧\n\n1212\n01:13:35.361 --> 01:13:36.381 align:middle line:100%,end position:50%,middle\n我需要钥匙\n\n1213\n01:13:37.410 --> 01:13:41.410 align:middle line:100%,end position:50%,middle\n空乘一听见就飞快冲过走道\n\n1214\n01:13:41.670 --> 01:13:44.139 align:middle line:100%,end position:50%,middle\n我说“别忘了咖啡”\n\n1215\n01:13:45.069 --> 01:13:46.999 align:middle line:100%,end position:50%,middle\n狗屁！ 你没那么说\n\n1216\n01:13:46.999 --> 01:13:49.568 align:middle line:100%,end position:50%,middle\n拜托 那是笑话嘛\n\n1217\n01:13:49.678 --> 01:13:51.508 align:middle line:100%,end position:50%,middle\n我认识真的碰到这事的人\n\n1218\n01:13:51.608 --> 01:13:52.078 align:middle line:100%,end position:50%,middle\n只是个笑话\n\n1219\n01:13:52.178 --> 01:13:53.168 align:middle line:100%,end position:50%,middle\n杰里\n\n1220\n01:13:53.278 --> 01:13:54.108 align:middle line:100%,end position:50%,middle\n这边很难找吗？\n\n1221\n01:13:54.208 --> 01:13:55.178 align:middle line:100%,end position:50%,middle\n不会 我打车来的\n\n1222\n01:13:55.548 --> 01:13:58.737 align:middle line:100%,end position:50%,middle\n提米 这是杰里 大学同学\n\n1223\n01:13:59.617 --> 01:14:00.917 align:middle line:100%,end position:50%,middle\n你好 幸会\n\n1224\n01:14:01.587 --> 01:14:02.486 align:middle line:100%,end position:50%,middle\n幸会\n\n1225\n01:14:02.616 --> 01:14:03.546 align:middle line:100%,end position:50%,middle\n请你喝杯啤酒吧\n\n1226\n01:14:03.756 --> 01:14:05.916 align:middle line:100%,end position:50%,middle\n不 沛绿雅\n\n1227\n01:14:06.386 --> 01:14:07.786 align:middle line:100%,end position:50%,middle\n那是法文的苏打水\n\n1228\n01:14:08.425 --> 01:14:09.585 align:middle line:100%,end position:50%,middle\n苏打水 好\n\n1229\n01:14:10.525 --> 01:14:11.685 align:middle line:100%,end position:50%,middle\n还有几个三明治\n\n1230\n01:14:11.795 --> 01:14:12.225 align:middle line:100%,end position:50%,middle\n好\n\n1231\n01:14:12.325 --> 01:14:13.295 align:middle line:100%,end position:50%,middle\n算在我账上\n\n1232\n01:14:13.425 --> 01:14:15.054 align:middle line:100%,end position:50%,middle\n你到底打不打算还账？\n\n1233\n01:14:15.424 --> 01:14:17.404 align:middle line:100%,end position:50%,middle\n要 我这边有中奖彩票\n\n1234\n01:14:17.404 --> 01:14:18.864 align:middle line:100%,end position:50%,middle\n奖金多少？\n\n1235\n01:14:18.864 --> 01:14:19.454 align:middle line:100%,end position:50%,middle\n一千两百万\n\n1236\n01:14:19.564 --> 01:14:20.623 align:middle line:100%,end position:50%,middle\n我看不够付\n\n1237\n01:14:20.733 --> 01:14:22.893 align:middle line:100%,end position:50%,middle\n够付你的变性手术了\n\n1238\n01:14:27.542 --> 01:14:28.372 align:middle line:100%,end position:50%,middle\n坚果？\n\n1239\n01:14:28.572 --> 01:14:29.702 align:middle line:100%,end position:50%,middle\n不 谢谢\n\n1240\n01:14:33.981 --> 01:14:36.711 align:middle line:100%,end position:50%,middle\n你想谈威尔\n\n1241\n01:14:36.791 --> 01:14:38.681 align:middle line:100%,end position:50%,middle\n好像很顺利\n\n1242\n01:14:38.681 --> 01:14:39.540 align:middle line:100%,end position:50%,middle\n我想是的\n\n1243\n01:14:42.450 --> 01:14:44.250 align:middle line:100%,end position:50%,middle\n你跟他谈过未来没？\n\n1244\n01:14:45.219 --> 01:14:48.679 align:middle line:100%,end position:50%,middle\n没谈到 还在往事中打转\n\n1245\n01:14:48.959 --> 01:14:50.049 align:middle line:100%,end position:50%,middle\n该开始谈了\n\n1246\n01:14:50.189 --> 01:14:52.518 align:middle line:100%,end position:50%,middle\n许多工作都急着找他\n\n1247\n01:14:52.628 --> 01:14:53.598 align:middle line:100%,end position:50%,middle\n哪种工作？\n\n1248\n01:14:54.198 --> 01:14:56.658 align:middle line:100%,end position:50%,middle\n前沿数学研究智库\n\n1249\n01:14:56.768 --> 01:14:59.427 align:middle line:100%,end position:50%,middle\n威尔的头脑能发挥的地方\n\n1250\n01:15:00.067 --> 01:15:04.766 align:middle line:100%,end position:50%,middle\n那真好 但他还没准备好\n\n1251\n01:15:09.076 --> 01:15:11.405 align:middle line:100%,end position:50%,middle\n我想你不明白\n\n1252\n01:15:11.405 --> 01:15:14.115 align:middle line:100%,end position:50%,middle\n我不明白什么？\n\n1253\n01:15:14.215 --> 01:15:15.375 align:middle line:100%,end position:50%,middle\n来了\n\n1254\n01:15:16.074 --> 01:15:17.454 align:middle line:100%,end position:50%,middle\n谢谢你\n\n1255\n01:15:17.454 --> 01:15:19.914 align:middle line:100%,end position:50%,middle\n免得你们手指黏糊糊\n\n1256\n01:15:19.914 --> 01:15:23.143 align:middle line:100%,end position:50%,middle\n提米 能帮个忙吗？\n\n1257\n01:15:23.323 --> 01:15:24.613 align:middle line:100%,end position:50%,middle\n帮我们分出赌局的输赢\n\n1258\n01:15:26.693 --> 01:15:28.052 align:middle line:100%,end position:50%,middle\n听过乔纳斯·索尔克吗？\n\n1259\n01:15:29.052 --> 01:15:29.922 align:middle line:100%,end position:50%,middle\n当然 他治愈了小儿麻痹症\n\n1260\n01:15:29.922 --> 01:15:32.552 align:middle line:100%,end position:50%,middle\n听过爱因斯坦吗？\n\n1261\n01:15:34.841 --> 01:15:38.141 align:middle line:100%,end position:50%,middle\n杰拉尔德·兰博呢？听过吗？\n\n1262\n01:15:38.141 --> 01:15:40.600 align:middle line:100%,end position:50%,middle\n没有\n\n1263\n01:15:40.600 --> 01:15:41.860 align:middle line:100%,end position:50%,middle\n谢谢\n\n1264\n01:15:42.370 --> 01:15:43.460 align:middle line:100%,end position:50%,middle\n谁赌赢了？\n\n1265\n01:15:43.600 --> 01:15:44.730 align:middle line:100%,end position:50%,middle\n我赢了\n\n1266\n01:15:45.980 --> 01:15:50.359 align:middle line:100%,end position:50%,middle\n这不是我的事\n\n1267\n01:15:50.439 --> 01:15:53.598 align:middle line:100%,end position:50%,middle\n我跟这年轻人比不算什么\n\n1268\n01:15:56.818 --> 01:15:58.777 align:middle line:100%,end position:50%,middle\n你听过杰拉尔德·兰博吗？\n\n1269\n01:15:58.777 --> 01:16:03.877 align:middle line:100%,end position:50%,middle\n1905年有数百名教授\n因研究宇宙而享誉世界\n\n1270\n01:16:03.987 --> 01:16:08.286 align:middle line:100%,end position:50%,middle\n却是一位26岁的瑞士专利局办事员\n\n1271\n01:16:08.556 --> 01:16:11.215 align:middle line:100%,end position:50%,middle\n在闲暇时研究物理，改变了世界\n\n1272\n01:16:11.325 --> 01:16:12.835 align:middle line:100%,end position:50%,middle\n你能想象爱因斯坦放弃物理\n\n1273\n01:16:12.835 --> 01:16:15.465 align:middle line:100%,end position:50%,middle\n只为每晚在维也纳\n和朋友喝得烂醉吗？\n\n1274\n01:16:15.465 --> 01:16:18.084 align:middle line:100%,end position:50%,middle\n我们都会失去一些东西\n\n1275\n01:16:18.124 --> 01:16:20.214 align:middle line:100%,end position:50%,middle\n而提米绝不会听过他\n\n1276\n01:16:20.214 --> 01:16:22.704 align:middle line:100%,end position:50%,middle\n非常戏剧化\n\n1277\n01:16:22.704 --> 01:16:23.344 align:middle line:100%,end position:50%,middle\n不是\n\n1278\n01:16:23.344 --> 01:16:25.973 align:middle line:100%,end position:50%,middle\n这孩子有天赋\n\n1279\n01:16:26.373 --> 01:16:28.633 align:middle line:100%,end position:50%,middle\n他只是没方向 我们该给他\n\n1280\n01:16:28.633 --> 01:16:32.572 align:middle line:100%,end position:50%,middle\n在60年代曾有一个\n\n1281\n01:16:32.572 --> 01:16:33.972 align:middle line:100%,end position:50%,middle\n密歇根大学毕业的年轻人\n\n1282\n01:16:33.972 --> 01:16:37.441 align:middle line:100%,end position:50%,middle\n他的数学很出色\n\n1283\n01:16:37.581 --> 01:16:39.811 align:middle line:100%,end position:50%,middle\n特别是有界调和函数\n\n1284\n01:16:40.121 --> 01:16:42.680 align:middle line:100%,end position:50%,middle\n后来他到伯克利任助理教授\n展现出惊人的潜力\n\n1285\n01:16:42.780 --> 01:16:46.120 align:middle line:100%,end position:50%,middle\n后来他搬到蒙大拿\n把竞争对手都炸飞了\n\n1286\n01:16:46.420 --> 01:16:47.950 align:middle line:100%,end position:50%,middle\n好 他是谁？\n\n1287\n01:16:48.059 --> 01:16:48.949 align:middle line:100%,end position:50%,middle\n泰德卡辛斯基\n\n1288\n01:16:48.949 --> 01:16:51.019 align:middle line:100%,end position:50%,middle\n没听过\n\n1289\n01:16:51.129 --> 01:16:52.059 align:middle line:100%,end position:50%,middle\n提米\n\n1290\n01:16:52.229 --> 01:16:54.628 align:middle line:100%,end position:50%,middle\n谁是泰德卡辛斯基？\n\n1291\n01:16:54.628 --> 01:16:55.788 align:middle line:100%,end position:50%,middle\n大学炸弹客\n\n1292\n01:16:57.578 --> 01:17:02.667 align:middle line:100%,end position:50%,middle\n那就是我说的 他需要方向\n\n1293\n01:17:02.767 --> 01:17:05.397 align:middle line:100%,end position:50%,middle\n他能为世界作贡献\n我们能帮他做到\n\n1294\n01:17:05.507 --> 01:17:07.336 align:middle line:100%,end position:50%,middle\n方向是一回事 操纵是另一回事\n\n1295\n01:17:07.336 --> 01:17:09.506 align:middle line:100%,end position:50%,middle\n我们得让他自己找到方向\n\n1296\n01:17:09.506 --> 01:17:11.976 align:middle line:100%,end position:50%,middle\n肖恩 我不是每晚坐在家里\n\n1297\n01:17:11.976 --> 01:17:15.005 align:middle line:100%,end position:50%,middle\n捻着胡子，策划摧毁这孩子的人生！\n\n1298\n01:17:15.115 --> 01:17:17.555 align:middle line:100%,end position:50%,middle\n我18岁就会做高等数学\n\n1299\n01:17:17.555 --> 01:17:20.134 align:middle line:100%,end position:50%,middle\n我还是花了20多年\n才做出配得上菲尔兹奖的成果\n\n1300\n01:17:20.134 --> 01:17:22.604 align:middle line:100%,end position:50%,middle\n也许他不想照你的想法去做\n\n1301\n01:17:22.604 --> 01:17:25.543 align:middle line:100%,end position:50%,middle\n人生不只是一个他妈的菲尔兹奖\n\n1302\n01:17:25.883 --> 01:17:29.753 align:middle line:100%,end position:50%,middle\n这太重要了，不能只顾个人争胜\n\n1303\n01:17:29.863 --> 01:17:32.092 align:middle line:100%,end position:50%,middle\n等等 我们谈的是这孩子\n\n1304\n01:17:32.192 --> 01:17:34.922 align:middle line:100%,end position:50%,middle\n为何不给他时间想清楚要什么？\n\n1305\n01:17:35.062 --> 01:17:38.071 align:middle line:100%,end position:50%,middle\n好理论 肖恩 它对你可真有奇效 是吧？\n\n1306\n01:17:38.071 --> 01:17:41.261 align:middle line:100%,end position:50%,middle\n对 你这自负的混蛋！\n\n1307\n01:17:42.531 --> 01:17:43.760 align:middle line:100%,end position:50%,middle\n我很遗憾\n\n1308\n01:17:44.070 --> 01:17:47.710 align:middle line:100%,end position:50%,middle\n真后悔今天来这儿\n我只是出于礼貌\n\n1309\n01:17:47.710 --> 01:17:48.570 align:middle line:100%,end position:50%,middle\n我想让你参与这件事\n\n1310\n01:17:48.670 --> 01:17:49.699 align:middle line:100%,end position:50%,middle\n我很高兴能够参与\n\n1311\n01:17:49.939 --> 01:17:52.709 align:middle line:100%,end position:50%,middle\n他现在正在麦尼尔面试\n是我安排的\n\n1312\n01:17:53.609 --> 01:17:58.168 align:middle line:100%,end position:50%,middle\n威尔 我不清楚你的意思\n\n1313\n01:17:58.278 --> 01:18:00.178 align:middle line:100%,end position:50%,middle\n我们已经给你提供了一个职位\n\n1314\n01:18:00.288 --> 01:18:02.877 align:middle line:100%,end position:50%,middle\n各位 这城里没人会不收聘用预付金就干活\n\n1315\n01:18:02.987 --> 01:18:06.077 align:middle line:100%,end position:50%,middle\n你们认为找得到 祝你好运\n\n1316\n01:18:06.287 --> 01:18:09.446 align:middle line:100%,end position:50%,middle\n但我想大家都清楚\n没人能像我一样出色地代理你\n\n1317\n01:18:09.656 --> 01:18:12.646 align:middle line:100%,end position:50%,middle\n威尔 我们开出的年薪是八万四千美元\n\n1318\n01:18:12.646 --> 01:18:17.665 align:middle line:100%,end position:50%,middle\n预付聘用金 预付聘用金\n\n1319\n01:18:17.795 --> 01:18:20.464 align:middle line:100%,end position:50%,middle\n你是要我们现在给你现金？\n\n1320\n01:18:20.564 --> 01:18:23.664 align:middle line:100%,end position:50%,middle\n放轻松 我没那么说\n\n1321\n01:18:24.704 --> 01:18:29.743 align:middle line:100%,end position:50%,middle\n据说你们的处境\n\n1322\n01:18:29.743 --> 01:18:36.282 align:middle line:100%,end position:50%,middle\n只要我现在口袋里有两百块 就能一起改善\n\n1323\n01:18:36.412 --> 01:18:41.411 align:middle line:100%,end position:50%,middle\n我恐怕拿不出…拉里？\n\n1324\n01:18:41.821 --> 01:18:44.681 align:middle line:100%,end position:50%,middle\n我有73块\n\n1325\n01:18:44.851 --> 01:18:45.750 align:middle line:100%,end position:50%,middle\n你收支票吗？\n\n1326\n01:18:45.750 --> 01:18:50.510 align:middle line:100%,end position:50%,middle\n你们这种举止相当可疑\n\n1327\n01:18:50.830 --> 01:18:52.019 align:middle line:100%,end position:50%,middle\n对 你们\n\n1328\n01:18:53.159 --> 01:18:56.009 align:middle line:100%,end position:50%,middle\n我不知道你们的声誉怎样\n\n1329\n01:18:56.009 --> 01:19:01.388 align:middle line:100%,end position:50%,middle\n但你们今天耍的这些花招 我肯定会查个清楚\n\n1330\n01:19:01.428 --> 01:19:06.357 align:middle line:100%,end position:50%,middle\n往后任何业务往来\n\n1331\n01:19:06.837 --> 01:19:09.327 align:middle line:100%,end position:50%,middle\n请找我刚才提到的律师谈\n\n1332\n01:19:10.646 --> 01:19:12.566 align:middle line:100%,end position:50%,middle\n再见\n\n1333\n01:19:12.566 --> 01:19:16.935 align:middle line:100%,end position:50%,middle\n在那天到来前\n把耳朵贴在磨刀石上好好干吧\n\n1334\n01:19:30.993 --> 01:19:32.123 align:middle line:100%,end position:50%,middle\n怎么样了？\n\n1335\n01:19:32.323 --> 01:19:33.293 align:middle line:100%,end position:50%,middle\n很好\n\n1336\n01:19:34.792 --> 01:19:36.712 align:middle line:100%,end position:50%,middle\n好\n\n1337\n01:19:38.102 --> 01:19:38.862 align:middle line:100%,end position:50%,middle\n要帮忙吗？\n\n1338\n01:19:38.962 --> 01:19:39.902 align:middle line:100%,end position:50%,middle\n不要！\n\n1339\n01:19:40.461 --> 01:19:43.761 align:middle line:100%,end position:50%,middle\n给我看一下 我们要去练球场\n\n1340\n01:19:43.901 --> 01:19:49.640 align:middle line:100%,end position:50%,middle\n我学会这个是很重要的\n\n1341\n01:19:49.980 --> 01:19:51.570 align:middle line:100%,end position:50%,middle\n真的很重要\n\n1342\n01:19:52.040 --> 01:19:53.339 align:middle line:100%,end position:50%,middle\n对我而言\n\n1343\n01:19:53.449 --> 01:19:55.109 align:middle line:100%,end position:50%,middle\n好吧\n\n1344\n01:19:56.049 --> 01:19:57.709 align:middle line:100%,end position:50%,middle\n那就在这边待一整天\n\n1345\n01:19:57.819 --> 01:19:59.278 align:middle line:100%,end position:50%,middle\n有何不可\n\n1346\n01:20:01.148 --> 01:20:03.548 align:middle line:100%,end position:50%,middle\n好 多管闲事先生\n\n1347\n01:20:04.818 --> 01:20:07.847 align:middle line:100%,end position:50%,middle\n既然你打算烦我\n\n1348\n01:20:09.727 --> 01:20:10.917 align:middle line:100%,end position:50%,middle\n让我问你一个问题\n\n1349\n01:20:11.326 --> 01:20:12.346 align:middle line:100%,end position:50%,middle\n好\n\n1350\n01:20:13.056 --> 01:20:15.966 align:middle line:100%,end position:50%,middle\n你有影像记忆力吗？\n\n1351\n01:20:17.296 --> 01:20:19.495 align:middle line:100%,end position:50%,middle\n不知道 我就是记得\n\n1352\n01:20:19.595 --> 01:20:23.165 align:middle line:100%,end position:50%,middle\n就像你怎么记住自己电话号码？\n就是能记住\n\n1353\n01:20:23.205 --> 01:20:24.934 align:middle line:100%,end position:50%,middle\n你念过有机化学吗？\n\n1354\n01:20:25.204 --> 01:20:26.264 align:middle line:100%,end position:50%,middle\n一点点\n\n1355\n01:20:26.434 --> 01:20:27.774 align:middle line:100%,end position:50%,middle\n为了好玩？\n\n1356\n01:20:28.204 --> 01:20:29.004 align:middle line:100%,end position:50%,middle\n对 为了找乐趣\n\n1357\n01:20:29.104 --> 01:20:34.423 align:middle line:100%,end position:50%,middle\n念有机化学会有趣 你疯啦\n\n1358\n01:20:34.743 --> 01:20:37.142 align:middle line:100%,end position:50%,middle\n你精神失常吗？\n\n1359\n01:20:37.382 --> 01:20:38.872 align:middle line:100%,end position:50%,middle\n没人会为了好玩念化学\n\n1360\n01:20:38.982 --> 01:20:42.051 align:middle line:100%,end position:50%,middle\n尤其对你这种人而言根本没必要\n\n1361\n01:20:42.151 --> 01:20:42.911 align:middle line:100%,end position:50%,middle\n我这种人？\n\n1362\n01:20:43.021 --> 01:20:48.560 align:middle line:100%,end position:50%,middle\n时间分配给练球场和酒吧的人\n\n1363\n01:20:48.690 --> 01:20:50.680 align:middle line:100%,end position:50%,middle\n人家不会说那是必要的\n\n1364\n01:20:53.460 --> 01:20:56.189 align:middle line:100%,end position:50%,middle\n哈佛有很聪明的人\n\n1365\n01:20:56.359 --> 01:20:58.859 align:middle line:100%,end position:50%,middle\n但他们都得付出努力才能学会\n\n1366\n01:21:00.438 --> 01:21:05.428 align:middle line:100%,end position:50%,middle\n你却简单地做到了 我不懂\n\n1367\n01:21:05.568 --> 01:21:08.127 align:middle line:100%,end position:50%,middle\n我不懂你的大脑怎么运作\n\n1368\n01:21:08.237 --> 01:21:09.767 align:middle line:100%,end position:50%,middle\n你弹钢琴吗？\n\n1369\n01:21:09.877 --> 01:21:10.417 align:middle line:100%,end position:50%,middle\n别转移话题\n\n1370\n01:21:10.417 --> 01:21:12.587 align:middle line:100%,end position:50%,middle\n我跟你解释嘛 你会弹吗？\n\n1371\n01:21:12.587 --> 01:21:14.376 align:middle line:100%,end position:50%,middle\n一点点\n\n1372\n01:21:14.376 --> 01:21:17.506 align:middle line:100%,end position:50%,middle\n好 你看着钢琴就看到莫扎特\n\n1373\n01:21:17.616 --> 01:21:18.746 align:middle line:100%,end position:50%,middle\n我只看得出《筷子》\n\n1374\n01:21:18.846 --> 01:21:22.655 align:middle line:100%,end position:50%,middle\n好 贝多芬 他一看到钢琴\n\n1375\n01:21:22.655 --> 01:21:24.765 align:middle line:100%,end position:50%,middle\n很自然地就会弹\n\n1376\n01:21:24.765 --> 01:21:26.894 align:middle line:100%,end position:50%,middle\n你是说你会弹琴？\n\n1377\n01:21:26.894 --> 01:21:28.414 align:middle line:100%,end position:50%,middle\n根本不会 望着钢琴\n\n1378\n01:21:28.524 --> 01:21:31.054 align:middle line:100%,end position:50%,middle\n我只看到琴键、3个踏板和木箱\n\n1379\n01:21:31.054 --> 01:21:35.893 align:middle line:100%,end position:50%,middle\n但贝多芬和莫扎特看一眼就懂 自然而然就会弹\n\n1380\n01:21:36.333 --> 01:21:38.992 align:middle line:100%,end position:50%,middle\n我画不了画 大概也没本事把球打出芬威球场\n\n1381\n01:21:39.102 --> 01:21:41.932 align:middle line:100%,end position:50%,middle\n我也不会弹琴\n\n1382\n01:21:41.932 --> 01:21:44.561 align:middle line:100%,end position:50%,middle\n但你不到一小时就能做完我的有机化学作业\n\n1383\n01:21:45.601 --> 01:21:49.631 align:middle line:100%,end position:50%,middle\n对 我是说 碰到那类事我总能得心应手\n\n1384\n01:21:52.740 --> 01:21:54.450 align:middle line:100%,end position:50%,middle\n我只能解释到这样\n\n1385\n01:21:54.450 --> 01:21:58.459 align:middle line:100%,end position:50%,middle\n来 我有话告诉你\n\n1386\n01:21:58.919 --> 01:22:00.109 align:middle line:100%,end position:50%,middle\n我跟你讲一件事\n\n1387\n01:22:18.233 --> 01:22:19.663 align:middle line:100%,end position:50%,middle\n不公平\n\n1388\n01:22:19.893 --> 01:22:21.692 align:middle line:100%,end position:50%,middle\n什么不公平？\n\n1389\n01:22:22.902 --> 01:22:24.831 align:middle line:100%,end position:50%,middle\n我在这边四年了\n\n1390\n01:22:25.431 --> 01:22:27.831 align:middle line:100%,end position:50%,middle\n现在才发现你\n\n1391\n01:22:29.140 --> 01:22:31.599 align:middle line:100%,end position:50%,middle\n起码你还是发现我啦\n\n1392\n01:22:43.886 --> 01:22:45.006 align:middle line:100%,end position:50%,middle\n你醒着吗？\n\n1393\n01:22:45.815 --> 01:22:46.975 align:middle line:100%,end position:50%,middle\n睡了\n\n1394\n01:22:48.814 --> 01:22:50.284 align:middle line:100%,end position:50%,middle\n你没睡\n\n1395\n01:22:53.823 --> 01:22:56.292 align:middle line:100%,end position:50%,middle\n跟我一起去加州\n\n1396\n01:22:58.692 --> 01:23:00.061 align:middle line:100%,end position:50%,middle\n什么？\n\n1397\n01:23:02.630 --> 01:23:05.390 align:middle line:100%,end position:50%,middle\n我要你跟我去加州\n\n1398\n01:23:10.368 --> 01:23:12.098 align:middle line:100%,end position:50%,middle\n你确定吗？\n\n1399\n01:23:12.538 --> 01:23:13.767 align:middle line:100%,end position:50%,middle\n确定\n\n1400\n01:23:15.307 --> 01:23:16.856 align:middle line:100%,end position:50%,middle\n你怎么知道？\n\n1401\n01:23:18.436 --> 01:23:19.705 align:middle line:100%,end position:50%,middle\n不晓得\n\n1402\n01:23:20.905 --> 01:23:22.395 align:middle line:100%,end position:50%,middle\n我就是知道\n\n1403\n01:23:22.605 --> 01:23:24.304 align:middle line:100%,end position:50%,middle\n但你怎么会知道？\n\n1404\n01:23:25.444 --> 01:23:28.183 align:middle line:100%,end position:50%,middle\n我知道 因为我感觉到\n\n1405\n01:23:28.183 --> 01:23:32.752 align:middle line:100%,end position:50%,middle\n你说的是很严肃的事\n\n1406\n01:23:32.752 --> 01:23:35.051 align:middle line:100%,end position:50%,middle\n下周到了加州\n\n1407\n01:23:35.221 --> 01:23:38.390 align:middle line:100%,end position:50%,middle\n你可能会发现不喜欢我的地方\n\n1408\n01:23:38.390 --> 01:23:41.319 align:middle line:100%,end position:50%,middle\n你会希望你没说过这些话\n\n1409\n01:23:41.459 --> 01:23:43.748 align:middle line:100%,end position:50%,middle\n但这是无法收回的事\n\n1410\n01:23:43.858 --> 01:23:46.328 align:middle line:100%,end position:50%,middle\n于是我跟不爱我的人困在加州\n\n1411\n01:23:46.428 --> 01:23:48.487 align:middle line:100%,end position:50%,middle\n她却希望一切能收回\n\n1412\n01:23:48.727 --> 01:23:50.856 align:middle line:100%,end position:50%,middle\n什么？ 什么是收回？\n\n1413\n01:23:51.626 --> 01:23:53.526 align:middle line:100%,end position:50%,middle\n我不想收回\n\n1414\n01:23:54.065 --> 01:23:56.625 align:middle line:100%,end position:50%,middle\n我只要你跟我去加州\n\n1415\n01:23:57.734 --> 01:23:59.894 align:middle line:100%,end position:50%,middle\n我不能去加州\n\n1416\n01:24:02.123 --> 01:24:04.083 align:middle line:100%,end position:50%,middle\n为什么？\n\n1417\n01:24:04.083 --> 01:24:08.251 align:middle line:100%,end position:50%,middle\n一是因为我在这边有工作\n\n1418\n01:24:08.711 --> 01:24:10.401 align:middle line:100%,end position:50%,middle\n二是因为我住这边\n\n1419\n01:24:11.720 --> 01:24:16.219 align:middle line:100%,end position:50%,middle\n你不爱我就该告诉我\n\n1420\n01:24:16.249 --> 01:24:17.439 align:middle line:100%,end position:50%,middle\n我没说不爱你\n\n1421\n01:24:18.648 --> 01:24:23.477 align:middle line:100%,end position:50%,middle\n那为什么不去？ 你怕什么？\n\n1422\n01:24:23.477 --> 01:24:26.086 align:middle line:100%,end position:50%,middle\n我怕什么？\n\n1423\n01:24:26.086 --> 01:24:28.285 align:middle line:100%,end position:50%,middle\n你不怕什么？\n\n1424\n01:24:29.525 --> 01:24:32.354 align:middle line:100%,end position:50%,middle\n你住在安全的小世界里 没有人挑战你\n\n1425\n01:24:32.354 --> 01:24:36.323 align:middle line:100%,end position:50%,middle\n别跟我说我的世界是什么样！\n\n1426\n01:24:36.423 --> 01:24:38.263 align:middle line:100%,end position:50%,middle\n你只想和城另一头的我玩玩\n\n1427\n01:24:38.363 --> 01:24:40.162 align:middle line:100%,end position:50%,middle\n然后到斯坦福\n\n1428\n01:24:40.162 --> 01:24:43.401 align:middle line:100%,end position:50%,middle\n你会嫁给一个有钱的混蛋 你父母也会满意\n\n1429\n01:24:43.401 --> 01:24:48.240 align:middle line:100%,end position:50%,middle\n然后跟其他信托基金宝宝坐着聊天\n说自己也去贫民窟体验过\n\n1430\n01:24:48.240 --> 01:24:50.969 align:middle line:100%,end position:50%,middle\n你为什么要这么说？\n\n1431\n01:24:50.969 --> 01:24:53.808 align:middle line:100%,end position:50%,middle\n你为何这么在乎钱？\n\n1432\n01:24:54.218 --> 01:24:56.737 align:middle line:100%,end position:50%,middle\n我十三岁丧父 继承家产\n\n1433\n01:24:57.747 --> 01:25:01.986 align:middle line:100%,end position:50%,middle\n你不觉得我每天醒来\n都希望能把这笔钱还回去吗？\n\n1434\n01:25:02.825 --> 01:25:05.685 align:middle line:100%,end position:50%,middle\n我会立刻把钱还回去\n\n1435\n01:25:05.685 --> 01:25:07.154 align:middle line:100%,end position:50%,middle\n只要能让我再陪他一天\n\n1436\n01:25:07.154 --> 01:25:10.923 align:middle line:100%,end position:50%,middle\n但我不能 那是我的人生 我面对它\n\n1437\n01:25:10.923 --> 01:25:14.262 align:middle line:100%,end position:50%,middle\n别把你的害怕推到我身上\n\n1438\n01:25:14.262 --> 01:25:17.001 align:middle line:100%,end position:50%,middle\n我怕？ 我他妈的怕什么？\n\n1439\n01:25:17.001 --> 01:25:19.461 align:middle line:100%,end position:50%,middle\n你怕我 怕我不会回应你的爱\n\n1440\n01:25:19.461 --> 01:25:21.830 align:middle line:100%,end position:50%,middle\n你知道吗？ 我也怕\n\n1441\n01:25:21.830 --> 01:25:25.399 align:middle line:100%,end position:50%,middle\n但我想试试看 起码我诚实\n\n1442\n01:25:25.399 --> 01:25:26.528 align:middle line:100%,end position:50%,middle\n难道我对你不诚实？\n\n1443\n01:25:26.638 --> 01:25:28.268 align:middle line:100%,end position:50%,middle\n不 你的十二个哥哥呢？\n\n1444\n01:25:31.237 --> 01:25:33.177 align:middle line:100%,end position:50%,middle\n你不能走 不准离开\n\n1445\n01:25:33.177 --> 01:25:36.546 align:middle line:100%,end position:50%,middle\n你想知道什么？ 我没十二个哥哥？\n\n1446\n01:25:36.546 --> 01:25:37.605 align:middle line:100%,end position:50%,middle\n我是个他妈的孤儿？\n\n1447\n01:25:37.715 --> 01:25:39.045 align:middle line:100%,end position:50%,middle\n- 你不会想听的\n- 我并不晓得\n\n1448\n01:25:39.045 --> 01:25:42.814 align:middle line:100%,end position:50%,middle\n你不想听我小时候被人拿烟头烫\n\n1449\n01:25:42.814 --> 01:25:44.353 align:middle line:100%,end position:50%,middle\n我不晓得\n\n1450\n01:25:44.353 --> 01:25:46.403 align:middle line:100%,end position:50%,middle\n那不是手术 那混蛋刺伤我\n\n1451\n01:25:46.513 --> 01:25:48.382 align:middle line:100%,end position:50%,middle\n你不会想听这种事！\n\n1452\n01:25:48.482 --> 01:25:50.591 align:middle line:100%,end position:50%,middle\n别跟我说你想知道！\n\n1453\n01:25:50.591 --> 01:25:51.561 align:middle line:100%,end position:50%,middle\n我想听 因为我想帮你\n\n1454\n01:25:51.561 --> 01:25:54.060 align:middle line:100%,end position:50%,middle\n帮我？ 什么鬼东西？\n\n1455\n01:25:54.060 --> 01:25:57.190 align:middle line:100%,end position:50%,middle\n我背上写着“快来救我”吗？\n\n1456\n01:25:57.190 --> 01:25:58.419 align:middle line:100%,end position:50%,middle\n我像要人救的样子吗？\n\n1457\n01:25:58.529 --> 01:25:59.689 align:middle line:100%,end position:50%,middle\n我想跟你在一起…我爱你\n\n1458\n01:25:59.689 --> 01:26:01.498 align:middle line:100%,end position:50%,middle\n别耍我\n\n1459\n01:26:01.498 --> 01:26:05.397 align:middle line:100%,end position:50%,middle\n别他妈的耍我\n\n1460\n01:26:05.797 --> 01:26:08.866 align:middle line:100%,end position:50%,middle\n我爱你\n\n1461\n01:26:08.866 --> 01:26:13.775 align:middle line:100%,end position:50%,middle\n我要听你说你不爱我\n\n1462\n01:26:13.775 --> 01:26:21.013 align:middle line:100%,end position:50%,middle\n那么我就不再打电话给你\n\n1463\n01:26:21.013 --> 01:26:25.671 align:middle line:100%,end position:50%,middle\n不再出现在你的生命里\n\n1464\n01:26:29.500 --> 01:26:32.259 align:middle line:100%,end position:50%,middle\n我不爱你\n\n1465\n01:27:13.307 --> 01:27:15.677 align:middle line:100%,end position:50%,middle\n很多人都无从得知自己的天赋\n\n1466\n01:27:16.816 --> 01:27:19.715 align:middle line:100%,end position:50%,middle\n因为找不到相信他们的老师\n\n1467\n01:27:19.715 --> 01:27:23.514 align:middle line:100%,end position:50%,middle\n于是他们深信自己很笨\n\n1468\n01:27:23.514 --> 01:27:26.454 align:middle line:100%,end position:50%,middle\n希望你能感激他所做的\n\n1469\n01:27:26.454 --> 01:27:29.823 align:middle line:100%,end position:50%,middle\n因为我看到他多喜欢帮你\n\n1470\n01:27:29.823 --> 01:27:33.421 align:middle line:100%,end position:50%,middle\n而不是跟你站在对立面\n\n1471\n01:27:36.091 --> 01:27:38.830 align:middle line:100%,end position:50%,middle\n你好 威尔\n\n1472\n01:27:38.830 --> 01:27:41.129 align:middle line:100%,end position:50%,middle\n汤姆 拿点咖啡来\n\n1473\n01:27:41.129 --> 01:27:43.599 align:middle line:100%,end position:50%,middle\n好\n\n1474\n01:27:46.668 --> 01:27:47.867 align:middle line:100%,end position:50%,middle\n好 我看看\n\n1475\n01:27:54.445 --> 01:27:58.444 align:middle line:100%,end position:50%,middle\n很好 正确\n\n1476\n01:27:59.274 --> 01:28:01.843 align:middle line:100%,end position:50%,middle\n你用了麦克劳林级数\n\n1477\n01:28:01.843 --> 01:28:05.452 align:middle line:100%,end position:50%,middle\n我不知道叫什么\n\n1478\n01:28:05.882 --> 01:28:07.442 align:middle line:100%,end position:50%,middle\n这样不对\n\n1479\n01:28:10.751 --> 01:28:12.650 align:middle line:100%,end position:50%,middle\n这会很难堪\n\n1480\n01:28:16.719 --> 01:28:17.849 align:middle line:100%,end position:50%,middle\n你是否想过…\n\n1481\n01:28:17.959 --> 01:28:19.258 align:middle line:100%,end position:50%,middle\n我确信是对的\n\n1482\n01:28:19.388 --> 01:28:21.657 align:middle line:100%,end position:50%,middle\n我们以后能不能在肖恩的办公室做？\n\n1483\n01:28:21.657 --> 01:28:25.616 align:middle line:100%,end position:50%,middle\n我得放下工作过来 通勤实在折磨人\n\n1484\n01:28:25.766 --> 01:28:29.065 align:middle line:100%,end position:50%,middle\n好 可不可能\n\n1485\n01:28:29.065 --> 01:28:35.303 align:middle line:100%,end position:50%,middle\n它是对的 带回家吧\n\n1486\n01:28:37.943 --> 01:28:40.392 align:middle line:100%,end position:50%,middle\n麦尼尔的面谈怎么了？\n\n1487\n01:28:40.872 --> 01:28:42.341 align:middle line:100%,end position:50%,middle\n我去不了 我有约会\n\n1488\n01:28:42.441 --> 01:28:45.031 align:middle line:100%,end position:50%,middle\n所以我派我的谈判代表去\n\n1489\n01:28:48.880 --> 01:28:52.618 align:middle line:100%,end position:50%,middle\n你自己的时间爱干嘛随你\n\n1490\n01:28:52.618 --> 01:28:55.748 align:middle line:100%,end position:50%,middle\n但我安排的会谈\n\n1491\n01:28:55.748 --> 01:28:58.017 align:middle line:100%,end position:50%,middle\n你没出现会让我丢脸\n\n1492\n01:28:58.257 --> 01:28:59.776 align:middle line:100%,end position:50%,middle\n好 那就别安排了\n\n1493\n01:28:59.886 --> 01:29:02.955 align:middle line:100%,end position:50%,middle\n我不会 我会取消\n\n1494\n01:29:02.955 --> 01:29:06.254 align:middle line:100%,end position:50%,middle\n我会亲自给你工作\n我只是想让你看看外面有什么机会\n\n1495\n01:29:06.254 --> 01:29:10.553 align:middle line:100%,end position:50%,middle\n也许我不想一辈子 跟别人解释这些鬼东西\n\n1496\n01:29:17.551 --> 01:29:20.140 align:middle line:100%,end position:50%,middle\n但你可以表示感激吧\n\n1497\n01:29:20.520 --> 01:29:23.639 align:middle line:100%,end position:50%,middle\n感激？ 你知道这多容易吗？\n\n1498\n01:29:23.819 --> 01:29:27.318 align:middle line:100%,end position:50%,middle\n你他妈知道这对我有多容易吗？简直是个笑话\n\n1499\n01:29:27.318 --> 01:29:29.418 align:middle line:100%,end position:50%,middle\n我很遗憾你不会解 真的\n\n1500\n01:29:29.418 --> 01:29:35.766 align:middle line:100%,end position:50%,middle\n我就不用他妈坐这儿看你摸索 然后把题做砸了\n\n1501\n01:29:38.865 --> 01:29:41.594 align:middle line:100%,end position:50%,middle\n这样你就会有更多的时间喝醉？\n\n1502\n01:29:42.094 --> 01:29:47.522 align:middle line:100%,end position:50%,middle\n没错 这浪费我的时间\n\n1503\n01:30:00.909 --> 01:30:03.748 align:middle line:100%,end position:50%,middle\n你说得对\n\n1504\n01:30:05.147 --> 01:30:09.386 align:middle line:100%,end position:50%,middle\n这道证明我做不出来\n\n1505\n01:30:09.386 --> 01:30:10.666 align:middle line:100%,end position:50%,middle\n但你做得到 / 说到这一点\n\n1506\n01:30:10.666 --> 01:30:15.964 align:middle line:100%,end position:50%,middle\n全世界只有少数人能分清你我\n\n1507\n01:30:15.974 --> 01:30:17.694 align:middle line:100%,end position:50%,middle\n我是其中之一\n\n1508\n01:30:17.694 --> 01:30:18.453 align:middle line:100%,end position:50%,middle\n我很遗憾\n\n1509\n01:30:18.553 --> 01:30:21.423 align:middle line:100%,end position:50%,middle\n我也是\n\n1510\n01:30:21.493 --> 01:30:24.082 align:middle line:100%,end position:50%,middle\n我常希望没遇到你\n\n1511\n01:30:26.931 --> 01:30:29.350 align:middle line:100%,end position:50%,middle\n这样我夜里就能睡得着\n\n1512\n01:30:29.350 --> 01:30:35.268 align:middle line:100%,end position:50%,middle\n不用惦记有个像你这样的人\n\n1513\n01:30:40.737 --> 01:30:46.115 align:middle line:100%,end position:50%,middle\n我不必看你糟蹋天赋\n\n1514\n01:30:51.414 --> 01:30:53.783 align:middle line:100%,end position:50%,middle\n比利 等等\n\n1515\n01:30:53.783 --> 01:30:54.873 align:middle line:100%,end position:50%,middle\n听到没？\n\n1516\n01:30:57.052 --> 01:30:59.451 align:middle line:100%,end position:50%,middle\n摩根！\n\n1517\n01:30:59.451 --> 01:31:01.611 align:middle line:100%,end position:50%,middle\n如果你还敢在我妈房里看色情片\n\n1518\n01:31:01.721 --> 01:31:03.550 align:middle line:100%,end position:50%,middle\n我就揍扁你\n\n1519\n01:31:20.165 --> 01:31:23.364 align:middle line:100%,end position:50%,middle\n怎么了？\n\n1520\n01:31:23.364 --> 01:31:27.903 align:middle line:100%,end position:50%,middle\n要打手枪在你家里打 脏死了\n\n1521\n01:31:27.903 --> 01:31:30.942 align:middle line:100%,end position:50%,middle\n我家没录像机\n\n1522\n01:31:31.542 --> 01:31:34.911 align:middle line:100%,end position:50%,middle\n过来 别在我的手套上弄\n\n1523\n01:31:34.911 --> 01:31:35.851 align:middle line:100%,end position:50%,middle\n我没用手套\n\n1524\n01:31:37.350 --> 01:31:41.519 align:middle line:100%,end position:50%,middle\n那是我打少年棒球时的手套\n\n1525\n01:31:41.519 --> 01:31:42.779 align:middle line:100%,end position:50%,middle\n你要我怎么做？\n\n1526\n01:31:44.488 --> 01:31:48.857 align:middle line:100%,end position:50%,middle\n你怎么搞的？ 操棒球手套啊？\n\n1527\n01:31:48.857 --> 01:31:52.996 align:middle line:100%,end position:50%,middle\n我没有 我用它清干净\n\n1528\n01:31:53.116 --> 01:31:55.895 align:middle line:100%,end position:50%,middle\n别在我妈房里打手枪了\n\n1529\n01:31:55.895 --> 01:31:58.094 align:middle line:100%,end position:50%,middle\n这屋里还有别台录像机吗？\n\n1530\n01:31:58.094 --> 01:31:59.494 align:middle line:100%,end position:50%,middle\n真可悲\n\n1531\n01:32:01.093 --> 01:32:05.832 align:middle line:100%,end position:50%,middle\n我为什么该为美国国家安全局工作？\n\n1532\n01:32:05.832 --> 01:32:09.071 align:middle line:100%,end position:50%,middle\n你将研究尖端科技\n\n1533\n01:32:09.071 --> 01:32:12.000 align:middle line:100%,end position:50%,middle\n接触别处看不到的科技\n\n1534\n01:32:12.000 --> 01:32:15.109 align:middle line:100%,end position:50%,middle\n因为都已列为机密\n\n1535\n01:32:15.109 --> 01:32:19.008 align:middle line:100%,end position:50%,middle\n超弦理论 混沌理论 高等算法\n\n1536\n01:32:19.008 --> 01:32:21.977 align:middle line:100%,end position:50%,middle\n破译密码\n\n1537\n01:32:21.977 --> 01:32:25.076 align:middle line:100%,end position:50%,middle\n那是其中一个层面\n\n1538\n01:32:25.076 --> 01:32:26.916 align:middle line:100%,end position:50%,middle\n得了 那就是你们做的事\n\n1539\n01:32:26.916 --> 01:32:29.985 align:middle line:100%,end position:50%,middle\n你们处理八成的情报工作\n\n1540\n01:32:29.985 --> 01:32:32.584 align:middle line:100%,end position:50%,middle\n是中情局的七倍大\n\n1541\n01:32:32.584 --> 01:32:38.952 align:middle line:100%,end position:50%,middle\n我们不喜欢自夸 但你说对了\n\n1542\n01:32:38.952 --> 01:32:43.451 align:middle line:100%,end position:50%,middle\n问题不是\n“为什么要为国家安全局工作？”\n\n1543\n01:32:43.561 --> 01:32:48.410 align:middle line:100%,end position:50%,middle\n而是“你为何不做？”\n\n1544\n01:32:48.430 --> 01:32:50.659 align:middle line:100%,end position:50%,middle\n我为何不为国家安全局工作？\n\n1545\n01:32:51.569 --> 01:32:53.828 align:middle line:100%,end position:50%,middle\n很难的问题\n\n1546\n01:32:53.828 --> 01:32:56.457 align:middle line:100%,end position:50%,middle\n让我想想 假设我在国家安全局工作\n\n1547\n01:32:56.457 --> 01:33:00.246 align:middle line:100%,end position:50%,middle\n某个人在我桌上放了个密码\n其他人都破解不了的密码\n\n1548\n01:33:00.246 --> 01:33:02.336 align:middle line:100%,end position:50%,middle\n或许我来试试看 我就破解了这个密码\n\n1549\n01:33:02.336 --> 01:33:04.475 align:middle line:100%,end position:50%,middle\n我很高兴 因为我做得很好\n\n1550\n01:33:04.475 --> 01:33:05.405 align:middle line:100%,end position:50%,middle\n但也许那个密码\n\n1551\n01:33:05.505 --> 01:33:08.134 align:middle line:100%,end position:50%,middle\n是北非或中东某支叛军的位置\n\n1552\n01:33:08.244 --> 01:33:10.543 align:middle line:100%,end position:50%,middle\n有了这个位置 他们就轰炸叛军所在的村落\n\n1553\n01:33:10.543 --> 01:33:15.982 align:middle line:100%,end position:50%,middle\n一千五百个跟我无冤无仇\n素昧平生的人就被杀了\n\n1554\n01:33:15.982 --> 01:33:19.151 align:middle line:100%,end position:50%,middle\n接着政客说“派海军陆战队去控制当地”\n\n1555\n01:33:19.151 --> 01:33:20.580 align:middle line:100%,end position:50%,middle\n因为他们根本不管别人死活\n\n1556\n01:33:20.580 --> 01:33:23.849 align:middle line:100%,end position:50%,middle\n死的不是他们的孩子\n\n1557\n01:33:23.849 --> 01:33:25.789 align:middle line:100%,end position:50%,middle\n当年征兵也轮不到他们\n因为他们在国民警卫队\n\n1558\n01:33:25.889 --> 01:33:28.758 align:middle line:100%,end position:50%,middle\n屁股挨弹片的，会是南区的某个孩子\n\n1559\n01:33:28.758 --> 01:33:31.197 align:middle line:100%,end position:50%,middle\n他回到家乡一看 以前工作的工厂\n\n1560\n01:33:31.197 --> 01:33:33.597 align:middle line:100%,end position:50%,middle\n搬到了他刚打完仗回来的那个国家\n\n1561\n01:33:33.597 --> 01:33:35.996 align:middle line:100%,end position:50%,middle\n那个害他屁股中弹的敌人 得到了他以前的工作\n\n1562\n01:33:35.996 --> 01:33:38.735 align:middle line:100%,end position:50%,middle\n因为他一天只拿15美分\n还不用休息上厕所\n\n1563\n01:33:38.735 --> 01:33:41.304 align:middle line:100%,end position:50%,middle\n同时 他了解到他去那里的唯一理由\n\n1564\n01:33:41.304 --> 01:33:44.473 align:middle line:100%,end position:50%,middle\n就是去建立一个政府\n愿意用好价钱卖石油给我们\n\n1565\n01:33:44.473 --> 01:33:46.973 align:middle line:100%,end position:50%,middle\n当然 石油公司利用那里的小规模冲突\n\n1566\n01:33:46.973 --> 01:33:50.132 align:middle line:100%,end position:50%,middle\n借机哄抬国内油价 对他们来说倒是额外的好处\n\n1567\n01:33:50.242 --> 01:33:52.831 align:middle line:100%,end position:50%,middle\n但2.5美元一加仑的油 却对我朋友没帮助\n\n1568\n01:33:52.941 --> 01:33:55.340 align:middle line:100%,end position:50%,middle\n当然 他们慢吞吞地运油回来\n\n1569\n01:33:55.340 --> 01:33:57.809 align:middle line:100%,end position:50%,middle\n或许还请了一个酗酒船长\n\n1570\n01:33:57.809 --> 01:34:00.579 align:middle line:100%,end position:50%,middle\n爱喝马丁尼\n还爱开船在冰山间来回穿行\n\n1571\n01:34:00.579 --> 01:34:02.778 align:middle line:100%,end position:50%,middle\n不久他撞上冰山 原油外漏\n\n1572\n01:34:02.778 --> 01:34:05.947 align:middle line:100%,end position:50%,middle\n杀死北大西洋所有海洋生物\n\n1573\n01:34:05.947 --> 01:34:08.316 align:middle line:100%,end position:50%,middle\n现在我的朋友失业了 付不起开车的油钱\n\n1574\n01:34:08.316 --> 01:34:10.456 align:middle line:100%,end position:50%,middle\n只好走路去面谈 很难受\n\n1575\n01:34:10.456 --> 01:34:13.125 align:middle line:100%,end position:50%,middle\n因为屁股里的弹片让他患上慢性痔疮\n\n1576\n01:34:13.125 --> 01:34:15.524 align:middle line:100%,end position:50%,middle\n同时 他也饿着肚子 因为每次想吃东西\n\n1577\n01:34:15.524 --> 01:34:20.693 align:middle line:100%,end position:50%,middle\n唯一的特价套餐，是北大西洋小鳕鱼\n配Quaker State机油\n\n1578\n01:34:20.693 --> 01:34:22.692 align:middle line:100%,end position:50%,middle\n所以 我会怎么想？\n\n1579\n01:34:22.692 --> 01:34:24.292 align:middle line:100%,end position:50%,middle\n我还在等更好的机会\n\n1580\n01:34:26.331 --> 01:34:29.230 align:middle line:100%,end position:50%,middle\n我想 算了 既然都这样 不如干脆开枪打死我朋友\n\n1581\n01:34:29.730 --> 01:34:32.599 align:middle line:100%,end position:50%,middle\n把他的工作给死对头 再抬高油价\n\n1582\n01:34:32.699 --> 01:34:34.259 align:middle line:100%,end position:50%,middle\n轰炸村庄 打死小海豹\n\n1583\n01:34:34.369 --> 01:34:37.068 align:middle line:100%,end position:50%,middle\n吸食大麻 加入国民警卫队\n\n1584\n01:34:37.068 --> 01:34:39.377 align:middle line:100%,end position:50%,middle\n我还可因此被选为总统\n\n1585\n01:34:39.377 --> 01:34:42.107 align:middle line:100%,end position:50%,middle\n你感觉孤单吗？\n\n1586\n01:34:42.107 --> 01:34:42.976 align:middle line:100%,end position:50%,middle\n什么？\n\n1587\n01:34:43.976 --> 01:34:45.506 align:middle line:100%,end position:50%,middle\n你有灵魂伴侣吗？\n\n1588\n01:34:46.646 --> 01:34:49.347 align:middle line:100%,end position:50%,middle\n我有…？ 说清楚点\n\n1589\n01:34:49.347 --> 01:34:52.117 align:middle line:100%,end position:50%,middle\n能够挑战你的人\n\n1590\n01:34:52.357 --> 01:34:53.477 align:middle line:100%,end position:50%,middle\n我有查克\n\n1591\n01:34:53.687 --> 01:34:56.587 align:middle line:100%,end position:50%,middle\n不 查克是你的家人\n他会为你躺在车水马龙的路上\n\n1592\n01:34:57.257 --> 01:35:03.028 align:middle line:100%,end position:50%,middle\n我说的是能让你敞开心扉、触动你灵魂的人\n\n1593\n01:35:03.028 --> 01:35:04.188 align:middle line:100%,end position:50%,middle\n我有…\n\n1594\n01:35:04.298 --> 01:35:05.098 align:middle line:100%,end position:50%,middle\n谁？\n\n1595\n01:35:06.439 --> 01:35:07.739 align:middle line:100%,end position:50%,middle\n有很多\n\n1596\n01:35:07.739 --> 01:35:08.929 align:middle line:100%,end position:50%,middle\n说出来\n\n1597\n01:35:09.309 --> 01:35:11.009 align:middle line:100%,end position:50%,middle\n莎士比亚、尼采、弗罗斯特\n\n1598\n01:35:11.009 --> 01:35:12.569 align:middle line:100%,end position:50%,middle\n奥康纳 康德 亚历山大·蒲柏 洛克\n\n1599\n01:35:12.679 --> 01:35:14.779 align:middle line:100%,end position:50%,middle\n很棒 他们都死了\n\n1600\n01:35:14.779 --> 01:35:16.310 align:middle line:100%,end position:50%,middle\n对我而言 他们没死\n\n1601\n01:35:16.310 --> 01:35:18.140 align:middle line:100%,end position:50%,middle\n你和他们可没多少对话\n\n1602\n01:35:19.250 --> 01:35:20.910 align:middle line:100%,end position:50%,middle\n你不能回应他们\n\n1603\n01:35:21.350 --> 01:35:23.951 align:middle line:100%,end position:50%,middle\n除非备好强效嗅盐和一把枪\n\n1604\n01:35:23.951 --> 01:35:25.981 align:middle line:100%,end position:50%,middle\n对 那就是我所说的\n\n1605\n01:35:26.741 --> 01:35:29.631 align:middle line:100%,end position:50%,middle\n在这样的世界里 你永远不会有那种关系\n\n1606\n01:35:29.631 --> 01:35:31.931 align:middle line:100%,end position:50%,middle\n你总害怕先迈出第一步\n\n1607\n01:35:31.931 --> 01:35:35.802 align:middle line:100%,end position:50%,middle\n因为你眼里只看得到十英里外那些糟糕结果\n\n1608\n01:35:35.802 --> 01:35:37.302 align:middle line:100%,end position:50%,middle\n你要站教授那边？\n\n1609\n01:35:37.302 --> 01:35:38.362 align:middle line:100%,end position:50%,middle\n别跟我扯这套 没有\n\n1610\n01:35:38.472 --> 01:35:39.602 align:middle line:100%,end position:50%,middle\n我不想做那个工作\n\n1611\n01:35:39.742 --> 01:35:42.043 align:middle line:100%,end position:50%,middle\n这和工作无关\n我不在乎你是不是为政府工作\n\n1612\n01:35:42.043 --> 01:35:46.013 align:middle line:100%,end position:50%,middle\n但你能随心所欲 不受束缚\n\n1613\n01:35:46.613 --> 01:35:49.843 align:middle line:100%,end position:50%,middle\n你热爱什么？ 想要什么？\n\n1614\n01:35:50.313 --> 01:35:52.654 align:middle line:100%,end position:50%,middle\n有人一辈子砌砖\n\n1615\n01:35:52.654 --> 01:35:55.524 align:middle line:100%,end position:50%,middle\n为了让孩子拥有像你现在的机会\n\n1616\n01:35:55.524 --> 01:35:56.584 align:middle line:100%,end position:50%,middle\n我可没要求这机会\n\n1617\n01:35:56.754 --> 01:35:58.354 align:middle line:100%,end position:50%,middle\n不 你生来就有\n\n1618\n01:35:58.464 --> 01:36:00.555 align:middle line:100%,end position:50%,middle\n别逃避说你没要求\n\n1619\n01:36:00.725 --> 01:36:03.755 align:middle line:100%,end position:50%,middle\n什么叫逃避？ 砌砖哪里不对？\n\n1620\n01:36:03.895 --> 01:36:04.595 align:middle line:100%,end position:50%,middle\n没有\n\n1621\n01:36:04.705 --> 01:36:06.665 align:middle line:100%,end position:50%,middle\n这没什么不对\n我盖的是别人的家\n\n1622\n01:36:06.765 --> 01:36:09.576 align:middle line:100%,end position:50%,middle\n对 我爸砌砖 好吗？\n\n1623\n01:36:09.576 --> 01:36:11.576 align:middle line:100%,end position:50%,middle\n他拼命干活让我受教育\n\n1624\n01:36:11.576 --> 01:36:13.076 align:middle line:100%,end position:50%,middle\n没错 那是可敬的行业\n\n1625\n01:36:13.076 --> 01:36:15.776 align:middle line:100%,end position:50%,middle\n修车哪不对？\n\n1626\n01:36:15.776 --> 01:36:17.887 align:middle line:100%,end position:50%,middle\n我让人能上班 这是很光荣的事\n\n1627\n01:36:17.887 --> 01:36:19.387 align:middle line:100%,end position:50%,middle\n是的 是很光荣\n\n1628\n01:36:19.387 --> 01:36:21.787 align:middle line:100%,end position:50%,middle\n坐40分钟火车去做清洁也很光荣\n\n1629\n01:36:22.115 --> 01:36:24.701 align:middle line:100%,end position:50%,middle\n让大学生早上来时地板干干净净\n\n1630\n01:36:24.785 --> 01:36:26.620 align:middle line:100%,end position:50%,middle\n垃圾桶也空了\n这才是真正的工作\n\n1631\n01:36:26.628 --> 01:36:27.178 align:middle line:100%,end position:50%,middle\n对\n\n1632\n01:36:27.288 --> 01:36:28.728 align:middle line:100%,end position:50%,middle\n对 是很可敬\n\n1633\n01:36:29.028 --> 01:36:32.998 align:middle line:100%,end position:50%,middle\n相信你是为了这份荣耀才做的\n\n1634\n01:36:32.998 --> 01:36:34.898 align:middle line:100%,end position:50%,middle\n我只是有个小问题\n\n1635\n01:36:34.898 --> 01:36:38.799 align:middle line:100%,end position:50%,middle\n你到哪里都能做清洁工\n\n1636\n01:36:38.909 --> 01:36:41.769 align:middle line:100%,end position:50%,middle\n为何去全球最顶尖的理工学院工作？\n\n1637\n01:36:42.209 --> 01:36:44.770 align:middle line:100%,end position:50%,middle\n你为什么夜里偷偷替别人解方程\n\n1638\n01:36:44.880 --> 01:36:51.390 align:middle line:100%,end position:50%,middle\n世上只有一两个人能解的方程 还撒谎否认？\n\n1639\n01:36:51.390 --> 01:36:53.881 align:middle line:100%,end position:50%,middle\n我看不到其中的荣耀\n\n1640\n01:36:57.061 --> 01:37:00.431 align:middle line:100%,end position:50%,middle\n你真正想做什么？\n\n1641\n01:37:03.662 --> 01:37:05.132 align:middle line:100%,end position:50%,middle\n我想当牧羊人\n\n1642\n01:37:05.332 --> 01:37:06.802 align:middle line:100%,end position:50%,middle\n真的？\n\n1643\n01:37:06.802 --> 01:37:11.113 align:middle line:100%,end position:50%,middle\n我想搬到纳舒厄买块地放羊\n\n1644\n01:37:11.113 --> 01:37:13.013 align:middle line:100%,end position:50%,middle\n也许你该那么做\n\n1645\n01:37:13.013 --> 01:37:13.743 align:middle line:100%,end position:50%,middle\n什么？\n\n1646\n01:37:14.113 --> 01:37:17.143 align:middle line:100%,end position:50%,middle\n要自慰回家弄条湿毛巾搞\n\n1647\n01:37:17.143 --> 01:37:17.773 align:middle line:100%,end position:50%,middle\n你在赶我？\n\n1648\n01:37:17.883 --> 01:37:18.573 align:middle line:100%,end position:50%,middle\n对 出去\n\n1649\n01:37:18.683 --> 01:37:20.924 align:middle line:100%,end position:50%,middle\n不 时间还没到\n\n1650\n01:37:20.924 --> 01:37:21.644 align:middle line:100%,end position:50%,middle\n- 到了\n- 我不走，不\n\n1651\n01:37:21.754 --> 01:37:23.984 align:middle line:100%,end position:50%,middle\n你不回答我问题 浪费我时间\n\n1652\n01:37:24.084 --> 01:37:25.754 align:middle line:100%,end position:50%,middle\n我以为我们是朋友\n\n1653\n01:37:25.754 --> 01:37:26.724 align:middle line:100%,end position:50%,middle\n游戏时间结束了\n\n1654\n01:37:26.824 --> 01:37:27.684 align:middle line:100%,end position:50%,middle\n你为什么赶我走？\n\n1655\n01:37:27.794 --> 01:37:31.095 align:middle line:100%,end position:50%,middle\n你想教我人生大道理？\n\n1656\n01:37:31.095 --> 01:37:33.065 align:middle line:100%,end position:50%,middle\n看看你这副颓废样子\n\n1657\n01:37:33.235 --> 01:37:34.735 align:middle line:100%,end position:50%,middle\n是什么让你过下去？\n\n1658\n01:37:34.735 --> 01:37:35.635 align:middle line:100%,end position:50%,middle\n跟你合作\n\n1659\n01:37:35.765 --> 01:37:36.705 align:middle line:100%,end position:50%,middle\n你的灵魂伴侣在哪？\n\n1660\n01:37:36.805 --> 01:37:38.706 align:middle line:100%,end position:50%,middle\n你要谈灵魂伴侣 她在哪？\n\n1661\n01:37:38.836 --> 01:37:39.396 align:middle line:100%,end position:50%,middle\n死了\n\n1662\n01:37:39.506 --> 01:37:40.636 align:middle line:100%,end position:50%,middle\n对 她已经他妈的死了\n\n1663\n01:37:40.776 --> 01:37:43.676 align:middle line:100%,end position:50%,middle\n她死了 你就兑现筹码收手走人？\n\n1664\n01:37:43.676 --> 01:37:45.116 align:middle line:100%,end position:50%,middle\n起码我玩过一把\n\n1665\n01:37:45.116 --> 01:37:47.777 align:middle line:100%,end position:50%,middle\n那你输了 输得很惨\n\n1666\n01:37:47.887 --> 01:37:51.357 align:middle line:100%,end position:50%,middle\n有些人输掉那么大一把 还有胆量再押一次\n\n1667\n01:37:51.357 --> 01:37:55.198 align:middle line:100%,end position:50%,middle\n看着我 你想要什么？\n\n1668\n01:38:01.328 --> 01:38:03.228 align:middle line:100%,end position:50%,middle\n你和你那些屁话\n\n1669\n01:38:03.228 --> 01:38:06.069 align:middle line:100%,end position:50%,middle\n每个人你都有狗屁答案\n\n1670\n01:38:06.169 --> 01:38:09.659 align:middle line:100%,end position:50%,middle\n却答不出来这么简单的问题\n\n1671\n01:38:10.219 --> 01:38:14.180 align:middle line:100%,end position:50%,middle\n因为你不知道\n\n1672\n01:38:15.050 --> 01:38:18.060 align:middle line:100%,end position:50%,middle\n再见 小小牧羊女\n\n1673\n01:38:19.350 --> 01:38:20.480 align:middle line:100%,end position:50%,middle\n去你的\n\n1674\n01:38:20.520 --> 01:38:21.020 align:middle line:100%,end position:50%,middle\n你是牧羊人\n\n1675\n01:38:27.221 --> 01:38:30.241 align:middle line:100%,end position:50%,middle\n牧羊人 白人小混蛋\n\n1676\n01:38:32.932 --> 01:38:37.702 align:middle line:100%,end position:50%,middle\n趁你还没走打电话给你\n\n1677\n01:38:37.702 --> 01:38:41.073 align:middle line:100%,end position:50%,middle\n<i>我最近参加了好几场工作面试</i>\n\n1678\n01:38:41.073 --> 01:38:42.913 align:middle line:100%,end position:50%,middle\n<i>我不会只当建筑工人</i>\n\n1679\n01:38:42.913 --> 01:38:46.593 align:middle line:100%,end position:50%,middle\n你知道我并不在乎\n\n1680\n01:38:47.243 --> 01:38:49.974 align:middle line:100%,end position:50%,middle\n是的\n\n1681\n01:38:52.424 --> 01:38:53.584 align:middle line:100%,end position:50%,middle\n我爱你\n\n1682\n01:38:59.065 --> 01:39:00.025 align:middle line:100%,end position:50%,middle\n威尔？\n\n1683\n01:39:01.445 --> 01:39:04.275 align:middle line:100%,end position:50%,middle\n你保重\n\n1684\n01:39:08.236 --> 01:39:09.266 align:middle line:100%,end position:50%,middle\n再见\n\n1685\n01:39:41.690 --> 01:39:48.113 align:middle line:100%,end position:50%,middle\n（目的地 旧金山 最后登机）\n\n1686\n01:40:16.083 --> 01:40:17.043 align:middle line:100%,end position:50%,middle\n威尔 快点！威尔！\n\n1687\n01:40:19.154 --> 01:40:22.054 align:middle line:100%,end position:50%,middle\n威尔，好了，我们完工了！\n\n1688\n01:40:22.054 --> 01:40:24.144 align:middle line:100%,end position:50%,middle\n我在你办公室 那孩子没来\n\n1689\n01:40:26.125 --> 01:40:28.795 align:middle line:100%,end position:50%,middle\n现在是五点十分\n\n1690\n01:40:28.795 --> 01:40:30.765 align:middle line:100%,end position:50%,middle\n已经迟到一小时十分了\n\n1691\n01:40:33.995 --> 01:40:37.606 align:middle line:100%,end position:50%,middle\n他不出现我就提交报告\n\n1692\n01:40:37.606 --> 01:40:40.166 align:middle line:100%,end position:50%,middle\n他去坐牢我也不会愧疚的\n\n1693\n01:40:44.077 --> 01:40:47.977 align:middle line:100%,end position:50%,middle\n好 就这样\n\n1694\n01:40:49.147 --> 01:40:50.017 align:middle line:100%,end position:50%,middle\n还好吧？\n\n1695\n01:40:52.557 --> 01:40:55.318 align:middle line:100%,end position:50%,middle\n谢谢\n\n1696\n01:40:57.988 --> 01:41:01.909 align:middle line:100%,end position:50%,middle\n真爽\n\n1697\n01:41:04.969 --> 01:41:07.499 align:middle line:100%,end position:50%,middle\n你女朋友怎么样了？\n\n1698\n01:41:07.499 --> 01:41:10.309 align:middle line:100%,end position:50%,middle\n她走了\n\n1699\n01:41:10.309 --> 01:41:12.710 align:middle line:100%,end position:50%,middle\n走？ 走去哪里？\n\n1700\n01:41:12.710 --> 01:41:17.080 align:middle line:100%,end position:50%,middle\n医学院 加州的医学院\n\n1701\n01:41:17.080 --> 01:41:18.070 align:middle line:100%,end position:50%,middle\n真的？\n\n1702\n01:41:18.480 --> 01:41:19.451 align:middle line:100%,end position:50%,middle\n什么时候的事？\n\n1703\n01:41:19.621 --> 01:41:21.021 align:middle line:100%,end position:50%,middle\n一礼拜前\n\n1704\n01:41:25.891 --> 01:41:26.721 align:middle line:100%,end position:50%,middle\n真不好受啊\n\n1705\n01:41:26.961 --> 01:41:27.861 align:middle line:100%,end position:50%,middle\n对\n\n1706\n01:41:30.632 --> 01:41:34.672 align:middle line:100%,end position:50%,middle\n那些会谈几时搞完？\n\n1707\n01:41:34.672 --> 01:41:36.362 align:middle line:100%,end position:50%,middle\n我想等我满21岁后的那周\n\n1708\n01:41:36.502 --> 01:41:39.273 align:middle line:100%,end position:50%,middle\n是吗？ 他们要给你工作吗？\n\n1709\n01:41:39.273 --> 01:41:43.643 align:middle line:100%,end position:50%,middle\n接下来50年都要坐屋里做长除法\n\n1710\n01:41:43.643 --> 01:41:47.144 align:middle line:100%,end position:50%,middle\n可能会攒不少钱\n\n1711\n01:41:47.144 --> 01:41:49.014 align:middle line:100%,end position:50%,middle\n我会成为他妈的实验室老鼠\n\n1712\n01:41:49.014 --> 01:41:53.254 align:middle line:100%,end position:50%,middle\n总比这鬼工作好 离开这里\n\n1713\n01:41:53.254 --> 01:41:56.535 align:middle line:100%,end position:50%,middle\n干嘛走？ 我这辈子都要住这儿\n\n1714\n01:41:56.905 --> 01:41:59.325 align:middle line:100%,end position:50%,middle\n我们当邻居 我们会当爸爸\n\n1715\n01:41:59.325 --> 01:42:04.726 align:middle line:100%,end position:50%,middle\n带他们一起去Foley球场\n打少年棒球联赛\n\n1716\n01:42:05.606 --> 01:42:09.006 align:middle line:100%,end position:50%,middle\n你是我的死党 所以别误会\n\n1717\n01:42:09.006 --> 01:42:12.657 align:middle line:100%,end position:50%,middle\n但20年后你如果还住在这儿\n\n1718\n01:42:12.747 --> 01:42:15.367 align:middle line:100%,end position:50%,middle\n到我家看爱国者队比赛\n还在干建筑\n\n1719\n01:42:15.477 --> 01:42:17.677 align:middle line:100%,end position:50%,middle\n我会他妈的杀了你\n\n1720\n01:42:17.677 --> 01:42:20.347 align:middle line:100%,end position:50%,middle\n那不是恐吓 我会宰了你\n\n1721\n01:42:20.347 --> 01:42:22.458 align:middle line:100%,end position:50%,middle\n你在胡扯什么？\n\n1722\n01:42:22.458 --> 01:42:25.028 align:middle line:100%,end position:50%,middle\n你拥有我们没有的天赋\n\n1723\n01:42:25.028 --> 01:42:26.748 align:middle line:100%,end position:50%,middle\n拜托 为何大家都这么说？\n\n1724\n01:42:26.858 --> 01:42:29.518 align:middle line:100%,end position:50%,middle\n我非得为了自己去做这做那吗？\n我不想做又怎样？\n\n1725\n01:42:29.628 --> 01:42:33.929 align:middle line:100%,end position:50%,middle\n不不不 去你的 你不欠自己什么\n\n1726\n01:42:33.929 --> 01:42:36.239 align:middle line:100%,end position:50%,middle\n你欠我的\n\n1727\n01:42:36.239 --> 01:42:38.939 align:middle line:100%,end position:50%,middle\n因为我明天醒来五十岁了\n\n1728\n01:42:38.939 --> 01:42:43.880 align:middle line:100%,end position:50%,middle\n还在干这种事 无所谓\n\n1729\n01:42:43.880 --> 01:42:46.610 align:middle line:100%,end position:50%,middle\n我是说 你握着一张中奖彩票\n\n1730\n01:42:46.610 --> 01:42:51.241 align:middle line:100%,end position:50%,middle\n你胆小得像个娘们 不敢兑现 这狗屁不通\n\n1731\n01:42:52.521 --> 01:42:55.421 align:middle line:100%,end position:50%,middle\n我会不惜一切交换你所拥有的\n\n1732\n01:42:55.421 --> 01:42:58.392 align:middle line:100%,end position:50%,middle\n其他这些人也是\n\n1733\n01:42:58.392 --> 01:43:01.162 align:middle line:100%,end position:50%,middle\n你再待20年是侮辱我们\n\n1734\n01:43:01.162 --> 01:43:04.262 align:middle line:100%,end position:50%,middle\n窝在这里是浪费你时间\n\n1735\n01:43:04.262 --> 01:43:05.292 align:middle line:100%,end position:50%,middle\n你又不知道\n\n1736\n01:43:05.402 --> 01:43:06.023 align:middle line:100%,end position:50%,middle\n我不知道？\n\n1737\n01:43:06.133 --> 01:43:06.933 align:middle line:100%,end position:50%,middle\n你不懂\n\n1738\n01:43:07.033 --> 01:43:09.533 align:middle line:100%,end position:50%,middle\n哦，我不知道？\n让我告诉你我知道什么\n\n1739\n01:43:10.073 --> 01:43:12.773 align:middle line:100%,end position:50%,middle\n我每天到你家接你\n\n1740\n01:43:13.373 --> 01:43:17.484 align:middle line:100%,end position:50%,middle\n我们出去喝酒笑闹 那很棒\n\n1741\n01:43:17.484 --> 01:43:20.254 align:middle line:100%,end position:50%,middle\n你知道我一天中\n最棒的时刻是什么吗？\n\n1742\n01:43:20.254 --> 01:43:21.684 align:middle line:100%,end position:50%,middle\n只有十秒\n\n1743\n01:43:21.684 --> 01:43:24.215 align:middle line:100%,end position:50%,middle\n从我把车停在路边 到走到你家门口\n\n1744\n01:43:24.695 --> 01:43:29.565 align:middle line:100%,end position:50%,middle\n每次我敲门都希望你不在了\n\n1745\n01:43:29.565 --> 01:43:32.265 align:middle line:100%,end position:50%,middle\n不说再见 什么都没有\n\n1746\n01:43:32.265 --> 01:43:33.786 align:middle line:100%,end position:50%,middle\n就这么走了\n\n1747\n01:43:33.866 --> 01:43:38.206 align:middle line:100%,end position:50%,middle\n我懂得不多 但我很清楚\n\n1748\n01:43:49.747 --> 01:43:52.818 align:middle line:100%,end position:50%,middle\n真是乱来 我让你参与\n\n1749\n01:43:52.818 --> 01:43:56.058 align:middle line:100%,end position:50%,middle\n是要你帮这孩子 不是赶走他\n\n1750\n01:43:56.058 --> 01:43:57.528 align:middle line:100%,end position:50%,middle\n我知道怎么应付他\n\n1751\n01:43:57.628 --> 01:43:58.588 align:middle line:100%,end position:50%,middle\n我不管你跟他有什么默契\n\n1752\n01:43:58.698 --> 01:44:00.699 align:middle line:100%,end position:50%,middle\n我甚至不在乎你们拿我开玩笑\n\n1753\n01:44:00.699 --> 01:44:03.269 align:middle line:100%,end position:50%,middle\n但你敢破坏我的事看看\n\n1754\n01:44:03.269 --> 01:44:03.819 align:middle line:100%,end position:50%,middle\n破坏？\n\n1755\n01:44:03.929 --> 01:44:06.569 align:middle line:100%,end position:50%,middle\n这孩子目前很脆弱\n\n1756\n01:44:06.569 --> 01:44:08.810 align:middle line:100%,end position:50%,middle\n我了解他很脆弱 好吗？\n\n1757\n01:44:08.810 --> 01:44:09.640 align:middle line:100%,end position:50%,middle\n他还有些问题\n\n1758\n01:44:09.740 --> 01:44:10.940 align:middle line:100%,end position:50%,middle\n他有什么问题？\n\n1759\n01:44:10.940 --> 01:44:13.570 align:middle line:100%,end position:50%,middle\n他在牢里当清洁工会更好吗？\n\n1760\n01:44:13.710 --> 01:44:16.270 align:middle line:100%,end position:50%,middle\n跟一群弱智猩猩混在一起会比较好吗？\n\n1761\n01:44:16.380 --> 01:44:18.121 align:middle line:100%,end position:50%,middle\n你想他为什么那么做？\n\n1762\n01:44:18.121 --> 01:44:20.381 align:middle line:100%,end position:50%,middle\n你晓得为什么吗？\n\n1763\n01:44:20.521 --> 01:44:21.581 align:middle line:100%,end position:50%,middle\n他能应付问题\n\n1764\n01:44:21.691 --> 01:44:24.021 align:middle line:100%,end position:50%,middle\n应付工作 显然也应付你了\n\n1765\n01:44:24.121 --> 01:44:24.851 align:middle line:100%,end position:50%,middle\n听我说\n\n1766\n01:44:24.961 --> 01:44:28.192 align:middle line:100%,end position:50%,middle\n他为何躲避？ 为何不信任人？\n\n1767\n01:44:28.192 --> 01:44:30.192 align:middle line:100%,end position:50%,middle\n因为他一开始\n\n1768\n01:44:30.192 --> 01:44:31.852 align:middle line:100%,end position:50%,middle\n就被本该最爱他的人抛弃了\n\n1769\n01:44:31.962 --> 01:44:33.162 align:middle line:100%,end position:50%,middle\n别跟我讲弗洛伊德的屁话\n\n1770\n01:44:33.262 --> 01:44:36.233 align:middle line:100%,end position:50%,middle\n他为什么跟你所谓的智障混？\n\n1771\n01:44:36.233 --> 01:44:38.773 align:middle line:100%,end position:50%,middle\n因为如果他叫他们扁你\n\n1772\n01:44:38.773 --> 01:44:41.863 align:middle line:100%,end position:50%,middle\n他们会拿球棒把你打倒 这就叫义气\n\n1773\n01:44:41.973 --> 01:44:43.033 align:middle line:100%,end position:50%,middle\n是喔 很感人\n\n1774\n01:44:43.143 --> 01:44:44.114 align:middle line:100%,end position:50%,middle\n他应付谁了？\n\n1775\n01:44:44.214 --> 01:44:47.514 align:middle line:100%,end position:50%,middle\n他在别人离开之前先赶人走\n\n1776\n01:44:47.514 --> 01:44:49.344 align:middle line:100%,end position:50%,middle\n这是防御机制，好吗？\n\n1777\n01:44:49.584 --> 01:44:52.455 align:middle line:100%,end position:50%,middle\n他因此孤独了20年\n\n1778\n01:44:52.455 --> 01:44:55.095 align:middle line:100%,end position:50%,middle\n你现在逼他 事情会重演\n\n1779\n01:44:55.095 --> 01:44:57.655 align:middle line:100%,end position:50%,middle\n我不会让他重蹈覆辙\n\n1780\n01:44:57.655 --> 01:44:58.765 align:middle line:100%,end position:50%,middle\n别那么做\n\n1781\n01:44:58.765 --> 01:44:59.455 align:middle line:100%,end position:50%,middle\n什么？\n\n1782\n01:44:59.565 --> 01:45:04.236 align:middle line:100%,end position:50%,middle\n别让他认为放弃或失败没关系\n\n1783\n01:45:04.236 --> 01:45:05.166 align:middle line:100%,end position:50%,middle\n绝对有关系！\n\n1784\n01:45:05.166 --> 01:45:08.906 align:middle line:100%,end position:50%,middle\n如果你因为我的成功而对我感到愤怒\n因为你本来可以大有可为的…\n\n1785\n01:45:08.906 --> 01:45:10.096 align:middle line:100%,end position:50%,middle\n我没有对你感到愤怒\n\n1786\n01:45:10.207 --> 01:45:12.767 align:middle line:100%,end position:50%,middle\n你有 你对我感到愤怒\n\n1787\n01:45:12.767 --> 01:45:16.857 align:middle line:100%,end position:50%,middle\n你讨厌我 不过我不会为我的成就 而感到抱歉的\n\n1788\n01:45:16.947 --> 01:45:18.917 align:middle line:100%,end position:50%,middle\n你对我感到愤怒 因为你本来也可有我的成就！\n\n1789\n01:45:19.017 --> 01:45:20.618 align:middle line:100%,end position:50%,middle\n你扪心自问\n\n1790\n01:45:20.618 --> 01:45:23.358 align:middle line:100%,end position:50%,middle\n你要威尔有那种感受？\n\n1791\n01:45:23.358 --> 01:45:24.758 align:middle line:100%,end position:50%,middle\n你要他感觉像失败者？\n\n1792\n01:45:24.858 --> 01:45:26.658 align:middle line:100%,end position:50%,middle\n你这个自大狂！\n\n1793\n01:45:26.658 --> 01:45:29.399 align:middle line:100%,end position:50%,middle\n我不去同学会的原因\n\n1794\n01:45:29.399 --> 01:45:31.629 align:middle line:100%,end position:50%,middle\n是因为受不了你的眼神\n\n1795\n01:45:31.769 --> 01:45:34.029 align:middle line:100%,end position:50%,middle\n那种高高在上、替我难堪的眼神\n\n1796\n01:45:34.129 --> 01:45:36.799 align:middle line:100%,end position:50%,middle\n你觉得我失败，但我知道自己是谁\n\n1797\n01:45:36.799 --> 01:45:38.340 align:middle line:100%,end position:50%,middle\n我为自己的工作自豪\n\n1798\n01:45:38.340 --> 01:45:39.600 align:middle line:100%,end position:50%,middle\n那是自觉的选择\n\n1799\n01:45:39.740 --> 01:45:41.100 align:middle line:100%,end position:50%,middle\n我没搞砸！\n\n1800\n01:45:41.370 --> 01:45:43.740 align:middle line:100%,end position:50%,middle\n你和你朋友认为我很可怜\n\n1801\n01:45:43.740 --> 01:45:45.380 align:middle line:100%,end position:50%,middle\n你和你那群阿谀奉承的跟班\n\n1802\n01:45:45.380 --> 01:45:47.741 align:middle line:100%,end position:50%,middle\n整天跟在你身后喊“菲尔兹奖！”\n\n1803\n01:45:47.851 --> 01:45:51.051 align:middle line:100%,end position:50%,middle\n你怎么还是这么怕失败？\n\n1804\n01:45:51.051 --> 01:45:52.791 align:middle line:100%,end position:50%,middle\n是因为我的奖章，对吗？\n\n1805\n01:45:52.791 --> 01:45:54.692 align:middle line:100%,end position:50%,middle\n天哪 我回家拿给你 送给你好了\n\n1806\n01:45:54.792 --> 01:45:55.522 align:middle line:100%,end position:50%,middle\n拜托不要\n\n1807\n01:45:55.622 --> 01:45:58.222 align:middle line:100%,end position:50%,middle\n把奖章塞进你他妈的屁眼里\n\n1808\n01:45:58.332 --> 01:45:59.632 align:middle line:100%,end position:50%,middle\n因为我不在乎你的奖章\n\n1809\n01:45:59.632 --> 01:46:02.862 align:middle line:100%,end position:50%,middle\n因为你成为数学界大神之前我就认识你了\n\n1810\n01:46:02.862 --> 01:46:04.063 align:middle line:100%,end position:50%,middle\n早在你满脸青春痘 思乡\n\n1811\n01:46:04.163 --> 01:46:05.693 align:middle line:100%,end position:50%,middle\n连该尿在床的哪一头都不知道\n\n1812\n01:46:05.803 --> 01:46:07.773 align:middle line:100%,end position:50%,middle\n是 你过去现在都比我聪明\n\n1813\n01:46:07.773 --> 01:46:10.403 align:middle line:100%,end position:50%,middle\n你人生变成这样别怪我\n\n1814\n01:46:10.403 --> 01:46:12.674 align:middle line:100%,end position:50%,middle\n我没怪你！ 这跟你无关！\n\n1815\n01:46:12.674 --> 01:46:15.984 align:middle line:100%,end position:50%,middle\n你这数学混球！ 是关于那孩子！\n\n1816\n01:46:15.984 --> 01:46:17.714 align:middle line:100%,end position:50%,middle\n他是好孩子！ 我不会看着你\n\n1817\n01:46:17.814 --> 01:46:20.374 align:middle line:100%,end position:50%,middle\n像现在糟蹋我般糟蹋他\n\n1818\n01:46:20.484 --> 01:46:22.985 align:middle line:100%,end position:50%,middle\n让他也感觉是失败者！\n\n1819\n01:46:22.985 --> 01:46:24.555 align:middle line:100%,end position:50%,middle\n他不会失败！\n\n1820\n01:46:24.555 --> 01:46:25.925 align:middle line:100%,end position:50%,middle\n但你如果逼他！\n\n1821\n01:46:26.025 --> 01:46:32.096 align:middle line:100%,end position:50%,middle\n我有今天的成就 是因为别人逼过我\n也因为我学会了逼自己\n\n1822\n01:46:32.096 --> 01:46:35.236 align:middle line:100%,end position:50%,middle\n他不是你！ 你懂吗！\n\n1823\n01:46:37.036 --> 01:46:38.166 align:middle line:100%,end position:50%,middle\n我待会再来\n\n1824\n01:46:38.276 --> 01:46:43.327 align:middle line:100%,end position:50%,middle\n不 进来 我正要走\n\n1825\n01:46:52.858 --> 01:46:56.889 align:middle line:100%,end position:50%,middle\n他和我之间的陈年往事\n\n1826\n01:46:56.889 --> 01:46:59.639 align:middle line:100%,end position:50%,middle\n跟你无关\n\n1827\n01:47:02.769 --> 01:47:06.240 align:middle line:100%,end position:50%,middle\n那是什么？\n\n1828\n01:47:06.240 --> 01:47:07.460 align:middle line:100%,end position:50%,middle\n你的档案\n\n1829\n01:47:07.800 --> 01:47:09.900 align:middle line:100%,end position:50%,middle\n我要送回去给法官评估\n\n1830\n01:47:10.820 --> 01:47:15.991 align:middle line:100%,end position:50%,middle\n你不会给我不及格吧？\n\n1831\n01:47:18.981 --> 01:47:21.906 align:middle line:100%,end position:50%,middle\n里面怎么写？\n\n1832\n01:47:22.485 --> 01:47:23.782 align:middle line:100%,end position:50%,middle\n你想看吗？\n\n1833\n01:47:23.782 --> 01:47:24.800 align:middle line:100%,end position:50%,middle\n为什么？\n\n1834\n01:47:27.506 --> 01:47:30.470 align:middle line:100%,end position:50%,middle\n你对这个有任何经验吗？\n\n1835\n01:47:30.640 --> 01:47:31.938 align:middle line:100%,end position:50%,middle\n20年的心理咨询\n\n1836\n01:47:32.077 --> 01:47:34.064 align:middle line:100%,end position:50%,middle\n有 我看过不少惨痛案例\n\n1837\n01:47:34.703 --> 01:47:38.027 align:middle line:100%,end position:50%,middle\n我是说 你对这个有经验吗？\n\n1838\n01:47:42.099 --> 01:47:44.565 align:middle line:100%,end position:50%,middle\n个人而言？\n\n1839\n01:47:44.565 --> 01:47:45.623 align:middle line:100%,end position:50%,middle\n是的\n\n1840\n01:47:45.932 --> 01:47:48.228 align:middle line:100%,end position:50%,middle\n我有\n\n1841\n01:47:48.228 --> 01:47:49.556 align:middle line:100%,end position:50%,middle\n肯定不好\n\n1842\n01:47:53.688 --> 01:47:58.919 align:middle line:100%,end position:50%,middle\n我爸是个酒鬼，醉后凶狠得要命\n\n1843\n01:47:59.747 --> 01:48:02.682 align:middle line:100%,end position:50%,middle\n他喝醉回家就想打人\n\n1844\n01:48:02.682 --> 01:48:08.122 align:middle line:100%,end position:50%,middle\n我激怒他以保护妈妈和弟弟\n\n1845\n01:48:08.242 --> 01:48:10.678 align:middle line:100%,end position:50%,middle\n他戴着戒指回家的那些夜晚才精彩\n\n1846\n01:48:12.904 --> 01:48:19.202 align:middle line:100%,end position:50%,middle\n他把扳手 棍子和皮带摆桌上\n\n1847\n01:48:19.202 --> 01:48:21.638 align:middle line:100%,end position:50%,middle\n然后说“选一个”\n\n1848\n01:48:21.638 --> 01:48:23.295 align:middle line:100%,end position:50%,middle\n我会挑皮带\n\n1849\n01:48:23.395 --> 01:48:25.531 align:middle line:100%,end position:50%,middle\n我通常挑扳手\n\n1850\n01:48:25.531 --> 01:48:26.829 align:middle line:100%,end position:50%,middle\n为什么是扳手？\n\n1851\n01:48:27.427 --> 01:48:29.564 align:middle line:100%,end position:50%,middle\n因为去他妈的，就是这样\n\n1852\n01:48:29.564 --> 01:48:30.891 align:middle line:100%,end position:50%,middle\n你养父？\n\n1853\n01:48:30.891 --> 01:48:34.095 align:middle line:100%,end position:50%,middle\n对 那么 这是怎么回事？\n\n1854\n01:48:34.095 --> 01:48:39.985 align:middle line:100%,end position:50%,middle\n威尔有依恋障碍？是这类问题吗？\n\n1855\n01:48:39.985 --> 01:48:41.742 align:middle line:100%,end position:50%,middle\n害怕被遗弃？\n\n1856\n01:48:42.580 --> 01:48:46.214 align:middle line:100%,end position:50%,middle\n那是我跟斯凯勒分手的原因吗？\n\n1857\n01:48:46.214 --> 01:48:47.471 align:middle line:100%,end position:50%,middle\n我不晓得你们分手了\n\n1858\n01:48:47.741 --> 01:48:49.038 align:middle line:100%,end position:50%,middle\n分手了\n\n1859\n01:48:49.408 --> 01:48:50.396 align:middle line:100%,end position:50%,middle\n想谈吗？\n\n1860\n01:48:50.506 --> 01:48:51.664 align:middle line:100%,end position:50%,middle\n不想\n\n1861\n01:48:55.337 --> 01:49:01.466 align:middle line:100%,end position:50%,middle\n威尔 我知道的不多\n\n1862\n01:49:01.466 --> 01:49:03.263 align:middle line:100%,end position:50%,middle\n但你看到这个没？\n\n1863\n01:49:03.263 --> 01:49:04.590 align:middle line:100%,end position:50%,middle\n这些事\n\n1864\n01:49:09.791 --> 01:49:12.446 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1865\n01:49:13.953 --> 01:49:16.159 align:middle line:100%,end position:50%,middle\n是 我知道\n\n1866\n01:49:16.159 --> 01:49:20.022 align:middle line:100%,end position:50%,middle\n看着我 孩子 不是你的错\n\n1867\n01:49:20.022 --> 01:49:23.516 align:middle line:100%,end position:50%,middle\n我知道\n\n1868\n01:49:23.985 --> 01:49:25.712 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1869\n01:49:28.308 --> 01:49:29.775 align:middle line:100%,end position:50%,middle\n我知道\n\n1870\n01:49:29.775 --> 01:49:34.806 align:middle line:100%,end position:50%,middle\n你不知道 不是你的错\n\n1871\n01:49:34.926 --> 01:49:36.343 align:middle line:100%,end position:50%,middle\n我知道\n\n1872\n01:49:36.343 --> 01:49:37.671 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1873\n01:49:37.671 --> 01:49:38.569 align:middle line:100%,end position:50%,middle\n好\n\n1874\n01:49:38.809 --> 01:49:42.212 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1875\n01:49:43.171 --> 01:49:45.267 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1876\n01:49:45.267 --> 01:49:46.734 align:middle line:100%,end position:50%,middle\n别耍我 好吗？\n\n1877\n01:49:49.330 --> 01:49:51.496 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1878\n01:49:51.496 --> 01:49:54.460 align:middle line:100%,end position:50%,middle\n肖恩 别耍我 你可别这样！\n\n1879\n01:49:54.560 --> 01:49:57.994 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1880\n01:50:03.234 --> 01:50:07.277 align:middle line:100%,end position:50%,middle\n不是你的错\n\n1881\n01:50:13.007 --> 01:50:21.302 align:middle line:100%,end position:50%,middle\n天啊…天啊！真对不起！天啊！\n\n1882\n01:50:34.528 --> 01:50:37.582 align:middle line:100%,end position:50%,middle\n去他们的 好吗？\n\n1883\n01:52:02.719 --> 01:52:03.587 align:middle line:100%,end position:50%,middle\n有什么事吗？\n\n1884\n01:52:03.817 --> 01:52:06.652 align:middle line:100%,end position:50%,middle\n我是威尔·亨廷 我来谈工作\n\n1885\n01:52:06.951 --> 01:52:10.095 align:middle line:100%,end position:50%,middle\n请坐一下\n\n1886\n01:52:36.727 --> 01:52:37.885 align:middle line:100%,end position:50%,middle\n你选择哪一个？\n\n1887\n01:52:38.394 --> 01:52:40.121 align:middle line:100%,end position:50%,middle\n麦尼尔那边\n\n1888\n01:52:40.121 --> 01:52:43.056 align:middle line:100%,end position:50%,middle\n教授帮我安排的工作之一\n\n1889\n01:52:43.256 --> 01:52:47.648 align:middle line:100%,end position:50%,middle\n我还没告诉他 我和老板谈过\n\n1890\n01:52:47.648 --> 01:52:51.321 align:middle line:100%,end position:50%,middle\n新老板人好像不错\n\n1891\n01:52:51.321 --> 01:52:53.846 align:middle line:100%,end position:50%,middle\n那是你要的吗？\n\n1892\n01:52:53.846 --> 01:52:55.543 align:middle line:100%,end position:50%,middle\n对 我想是吧\n\n1893\n01:52:57.380 --> 01:52:59.896 align:middle line:100%,end position:50%,middle\n做得好 恭喜\n\n1894\n01:53:00.075 --> 01:53:02.591 align:middle line:100%,end position:50%,middle\n谢谢\n\n1895\n01:53:05.036 --> 01:53:07.552 align:middle line:100%,end position:50%,middle\n时间到了\n\n1896\n01:53:09.838 --> 01:53:13.102 align:middle line:100%,end position:50%,middle\n就这样？我们结束了？\n\n1897\n01:53:13.102 --> 01:53:15.927 align:middle line:100%,end position:50%,middle\n对 就这样\n\n1898\n01:53:15.927 --> 01:53:19.620 align:middle line:100%,end position:50%,middle\n你结束了 自由了\n\n1899\n01:53:20.828 --> 01:53:25.220 align:middle line:100%,end position:50%,middle\n我想跟你说 我…\n\n1900\n01:53:25.220 --> 01:53:26.687 align:middle line:100%,end position:50%,middle\n不客气\n\n1901\n01:53:32.117 --> 01:53:35.681 align:middle line:100%,end position:50%,middle\n希望我们保持联络\n\n1902\n01:53:35.681 --> 01:53:37.038 align:middle line:100%,end position:50%,middle\n我也希望\n\n1903\n01:53:37.707 --> 01:53:40.512 align:middle line:100%,end position:50%,middle\n我会旅行一阵子 会有点难\n\n1904\n01:53:40.512 --> 01:53:44.575 align:middle line:100%,end position:50%,middle\n不过大学里有我的电话留言机\n我会定时联系查看\n\n1905\n01:53:44.575 --> 01:53:48.198 align:middle line:100%,end position:50%,middle\n这是电话号码\n\n1906\n01:53:48.308 --> 01:53:52.001 align:middle line:100%,end position:50%,middle\n你打来 我会马上回电话\n\n1907\n01:53:52.001 --> 01:53:56.244 align:middle line:100%,end position:50%,middle\n我想把钱再押上桌\n\n1908\n01:53:56.244 --> 01:54:00.995 align:middle line:100%,end position:50%,middle\n看看这次会抽到什么牌\n\n1909\n01:54:00.995 --> 01:54:04.708 align:middle line:100%,end position:50%,middle\n你跟着心走就没事了\n\n1910\n01:54:08.621 --> 01:54:11.117 align:middle line:100%,end position:50%,middle\n谢谢你 肖恩\n\n1911\n01:54:11.117 --> 01:54:12.415 align:middle line:100%,end position:50%,middle\n谢谢你 威尔\n\n1912\n01:54:14.481 --> 01:54:18.314 align:middle line:100%,end position:50%,middle\n这会越过医患关系的界限吗？\n\n1913\n01:54:18.314 --> 01:54:19.971 align:middle line:100%,end position:50%,middle\n除非你抓我屁股\n\n1914\n01:54:23.704 --> 01:54:24.503 align:middle line:100%,end position:50%,middle\n保重\n\n1915\n01:54:24.523 --> 01:54:26.689 align:middle line:100%,end position:50%,middle\n你也是\n\n1916\n01:54:32.169 --> 01:54:33.497 align:middle line:100%,end position:50%,middle\n祝你好运 孩子\n\n1917\n01:54:45.355 --> 01:54:48.839 align:middle line:100%,end position:50%,middle\n两瓶啤酒\n\n1918\n01:54:51.754 --> 01:54:52.842 align:middle line:100%,end position:50%,middle\n你们去了吗？\n\n1919\n01:54:53.151 --> 01:54:55.018 align:middle line:100%,end position:50%,middle\n没有 我得安抚他\n\n1920\n01:54:55.018 --> 01:54:56.126 align:middle line:100%,end position:50%,middle\n你怎么不把他制服？\n\n1921\n01:54:56.126 --> 01:54:59.150 align:middle line:100%,end position:50%,middle\n小摩根这小子还挺能打\n\n1922\n01:54:59.150 --> 01:55:02.514 align:middle line:100%,end position:50%,middle\n每周都有人想扁他 他还不让步\n\n1923\n01:55:02.514 --> 01:55:03.732 align:middle line:100%,end position:50%,middle\n讲我什么？\n\n1924\n01:55:03.872 --> 01:55:07.864 align:middle line:100%,end position:50%,middle\n我跟你讲话吗？ 关你屁事\n\n1925\n01:55:08.204 --> 01:55:09.002 align:middle line:100%,end position:50%,middle\n帮我弄个啤酒\n\n1926\n01:55:09.172 --> 01:55:10.360 align:middle line:100%,end position:50%,middle\n我叫了两瓶\n\n1927\n01:55:10.939 --> 01:55:11.927 align:middle line:100%,end position:50%,middle\n浑蛋\n\n1928\n01:55:12.137 --> 01:55:12.696 align:middle line:100%,end position:50%,middle\n干嘛？ 贱货\n\n1929\n01:55:12.806 --> 01:55:14.233 align:middle line:100%,end position:50%,middle\n生日快乐\n\n1930\n01:55:14.233 --> 01:55:15.820 align:middle line:100%,end position:50%,middle\n以为我们忘了吗？ 贱货\n\n1931\n01:55:16.529 --> 01:55:19.853 align:middle line:100%,end position:50%,middle\n- 来吧！\n- 我来了，我来了\n\n1932\n01:55:19.853 --> 01:55:21.729 align:middle line:100%,end position:50%,middle\n谁先？\n\n1933\n01:55:21.899 --> 01:55:23.297 align:middle line:100%,end position:50%,middle\n- 来吧混蛋\n- 谁先？\n\n1934\n01:55:24.435 --> 01:55:26.311 align:middle line:100%,end position:50%,middle\n丹尼男孩\n\n1935\n01:55:26.391 --> 01:55:27.579 align:middle line:100%,end position:50%,middle\n你的礼物\n\n1936\n01:55:29.156 --> 01:55:31.891 align:middle line:100%,end position:50%,middle\n快点\n\n1937\n01:55:31.891 --> 01:55:34.646 align:middle line:100%,end position:50%,middle\n你的新工作要往返剑桥\n\n1938\n01:55:34.816 --> 01:55:39.677 align:middle line:100%,end position:50%,middle\n我不会每天载你 所以\n\n1939\n01:55:39.677 --> 01:55:41.414 align:middle line:100%,end position:50%,middle\n摩根想给你买张T卡月票\n\n1940\n01:55:41.414 --> 01:55:42.672 align:middle line:100%,end position:50%,middle\n我没那么说\n\n1941\n01:55:43.580 --> 01:55:47.203 align:middle line:100%,end position:50%,middle\n- 但你21岁了\n- 可以合法喝酒\n\n1942\n01:55:47.343 --> 01:55:49.669 align:middle line:100%,end position:50%,middle\n我们想最好的礼物就是车子\n\n1943\n01:55:49.809 --> 01:55:51.176 align:middle line:100%,end position:50%,middle\n喜欢吗？\n\n1944\n01:55:51.176 --> 01:55:52.564 align:middle line:100%,end position:50%,middle\n这是\n\n1945\n01:55:54.700 --> 01:55:59.232 align:middle line:100%,end position:50%,middle\n我这辈子看过最丑的车\n\n1946\n01:55:59.232 --> 01:56:00.200 align:middle line:100%,end position:50%,middle\n快 兄弟\n\n1947\n01:56:00.300 --> 01:56:01.587 align:middle line:100%,end position:50%,middle\n你们怎么弄的？\n\n1948\n01:56:01.657 --> 01:56:04.762 align:middle line:100%,end position:50%,middle\n我和比利一起凑齐了零件\n\n1949\n01:56:04.762 --> 01:56:08.225 align:middle line:100%,end position:50%,middle\n摩根每天出去乞讨零钱\n\n1950\n01:56:08.225 --> 01:56:10.222 align:middle line:100%,end position:50%,middle\n车身都是我搞的\n\n1951\n01:56:10.222 --> 01:56:11.689 align:middle line:100%,end position:50%,middle\n我也他妈有工作啊 兄弟\n\n1952\n01:56:11.689 --> 01:56:13.616 align:middle line:100%,end position:50%,middle\n这家伙为找份工作骚扰我两年\n\n1953\n01:56:13.616 --> 01:56:14.604 align:middle line:100%,end position:50%,middle\n我得让他为车出点力\n\n1954\n01:56:14.724 --> 01:56:16.221 align:middle line:100%,end position:50%,middle\n你终于有工作了？ 摩根\n\n1955\n01:56:16.221 --> 01:56:18.447 align:middle line:100%,end position:50%,middle\n有过一个 现在又没了\n\n1956\n01:56:18.447 --> 01:56:20.613 align:middle line:100%,end position:50%,middle\n那是什么？割草机？什么引擎？\n\n1957\n01:56:20.613 --> 01:56:24.077 align:middle line:100%,end position:50%,middle\n我和比利重新打造引擎\n\n1958\n01:56:24.077 --> 01:56:27.980 align:middle line:100%,end position:50%,middle\n这是辆好车 引擎不错\n\n1959\n01:56:27.980 --> 01:56:30.236 align:middle line:100%,end position:50%,middle\n21岁生日快乐，威尔\n\n1960\n01:56:30.236 --> 01:56:31.533 align:middle line:100%,end position:50%,middle\n21岁生日快乐 兄弟\n\n1961\n01:56:41.735 --> 01:56:44.460 align:middle line:100%,end position:50%,middle\n进来\n\n1962\n01:56:46.357 --> 01:56:48.123 align:middle line:100%,end position:50%,middle\n肖恩 我…\n\n1963\n01:56:48.463 --> 01:56:49.651 align:middle line:100%,end position:50%,middle\n我也是\n\n1964\n01:56:50.789 --> 01:56:54.073 align:middle line:100%,end position:50%,middle\n那就好\n\n1965\n01:56:54.791 --> 01:56:56.279 align:middle line:100%,end position:50%,middle\n听说你要请假\n\n1966\n01:56:56.548 --> 01:56:59.513 align:middle line:100%,end position:50%,middle\n对 我想旅行一阵子\n\n1967\n01:56:59.513 --> 01:57:00.611 align:middle line:100%,end position:50%,middle\n或许写书\n\n1968\n01:57:01.150 --> 01:57:02.777 align:middle line:100%,end position:50%,middle\n去哪里？\n\n1969\n01:57:02.777 --> 01:57:08.018 align:middle line:100%,end position:50%,middle\n印度 中国和巴尔的摩\n\n1970\n01:57:10.773 --> 01:57:12.210 align:middle line:100%,end position:50%,middle\n你知道几时回来吗？\n\n1971\n01:57:12.210 --> 01:57:16.273 align:middle line:100%,end position:50%,middle\n我前两天收到一张传单\n\n1972\n01:57:16.273 --> 01:57:19.497 align:middle line:100%,end position:50%,middle\n上面说72届同学半年后开同学会\n\n1973\n01:57:19.497 --> 01:57:21.154 align:middle line:100%,end position:50%,middle\n是 我也收到一张\n\n1974\n01:57:21.304 --> 01:57:23.759 align:middle line:100%,end position:50%,middle\n你来吧 我请你喝酒\n\n1975\n01:57:23.899 --> 01:57:25.885 align:middle line:100%,end position:50%,middle\n那种场合的酒是免费的\n\n1976\n01:57:27.163 --> 01:57:29.459 align:middle line:100%,end position:50%,middle\n我知道，杰里，我是在说反话\n\n1977\n01:57:34.620 --> 01:57:38.493 align:middle line:100%,end position:50%,middle\n现在喝一杯怎么样？\n\n1978\n01:57:38.493 --> 01:57:40.978 align:middle line:100%,end position:50%,middle\n好啊 好主意\n\n1979\n01:57:40.978 --> 01:57:44.072 align:middle line:100%,end position:50%,middle\n走 这杯我请\n\n1980\n01:57:46.179 --> 01:57:48.345 align:middle line:100%,end position:50%,middle\n我这张准能中 伙计\n\n1981\n01:57:48.345 --> 01:57:51.878 align:middle line:100%,end position:50%,middle\n对 就是这张\n\n1982\n01:57:51.878 --> 01:57:54.034 align:middle line:100%,end position:50%,middle\n通往天堂的票\n\n1983\n01:57:54.034 --> 01:57:56.440 align:middle line:100%,end position:50%,middle\n你知道彩票中奖的概率吗？\n\n1984\n01:57:56.440 --> 01:57:57.768 align:middle line:100%,end position:50%,middle\n四比一？\n\n1985\n01:57:57.768 --> 01:57:59.425 align:middle line:100%,end position:50%,middle\n三千万比一\n\n1986\n01:57:59.535 --> 01:58:01.601 align:middle line:100%,end position:50%,middle\n还是有机会\n\n1987\n01:58:01.601 --> 01:58:07.630 align:middle line:100%,end position:50%,middle\n就跟你此刻在楼梯上\n被闪电击中的概率差不多\n\n1988\n01:58:07.630 --> 01:58:11.723 align:middle line:100%,end position:50%,middle\n那也有可能 我是说\n三千两百万分之一 你看这个体积…\n\n1989\n01:59:40.283 --> 01:59:43.397 align:middle line:100%,end position:50%,middle\n威尔！\n\n1990\n02:00:01.634 --> 02:00:04.249 align:middle line:100%,end position:50%,middle\n威尔？\n\n1991\n02:01:11.418 --> 02:01:12.436 align:middle line:100%,end position:50%,middle\n他不在\n\n1992\n02:01:34.197 --> 02:01:34.956 align:middle line:100%,end position:50%,middle\n<i>肖恩</i>\n\n1993\n02:01:35.295 --> 02:01:37.637 align:middle line:100%,end position:50%,middle\n<i>如果教授问起工作的事</i>\n\n1994\n02:01:37.766 --> 02:01:43.651 align:middle line:100%,end position:50%,middle\n<i>跟他说抱歉 我要去找个女孩</i>\n\n1995\n02:01:43.651 --> 02:01:44.733 align:middle line:100%,end position:50%,middle\n<i>威尔</i>\n\n1996\n02:01:46.640 --> 02:01:50.980 align:middle line:100%,end position:50%,middle\n这个小混蛋 他偷了我的台词\n\n1997\n02:06:12.906 --> 02:06:17.578 align:middle line:100%,end position:50%,middle\n（纪念艾伦·金斯伯格和威廉·巴勒斯）\n";
